      "path": "src/index.ts",
      "content": "/**\n * meow-memory v2 — 喵版跨会话记忆插件（host 端）。\n *\n * 设计（2026-08-15 与用户拍板）：\n * - SQLite 结构化存储（node:sqlite，宿主同款），每 level 一表：\n *   soul / user / project / fact / lesson / topic / rules；id=时间前缀（排序=创建顺序）。\n * - 注入：会话开头 soul/user 全量 + 记忆导引（project/topic 标题列表，正文自取）\n *   + 第一条用户消息关键词命中 fact/lesson 短条目；无每轮注入。\n * - 去重：.dsh-meow/sessions/<sessionId>.json 记录本会话注入过的 memory id。\n * - 工具：memory_remember / memory_search / memory_read / memory_update\n *   + memory_dream（手动整理本窗口）。\n * - 反思：干过活的 turn 结束后引导模型记忆——【一】新记忆（project 列表/纠正/偏好）、\n *   【二】更新判断（含关键词不准反推）、【三】通用要求（subcategory/关键词 8-13/importance）；\n *   topic 归 dream 轮处理（用户拍板 2026-08-19）。\n * - dream：按窗口空闲整理（用户拍板 2026-08-19：空闲 ≥3h 即允许，替代原夜间窗口；\n *   北京时间峰时 09:00–12:00 / 14:00–18:00 及前 15 分钟抑制不触发）——每个窗口由\n *   自己的主 agent 整理自己建立/提取过的记忆，分轮处理（原子记忆 project/fact/lesson\n *   → topic 记忆 → 项目总结，2026-08-22 加第三轮），project 小标题分段；\n *   updated_at 封存（\"记忆时间戳\"=最后更新时间）；串行；旧窗口不碰。\n * - 迁移：首次打开库时把旧 PROJECT.md 导入 SQLite，文件改名 .imported 留底。\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport { boundContextSummary, createUserMessage } from '@deepseek-ai/dsh-llm'\nimport z from '@deepseek-ai/schemastery'\nimport { appendFileSync, existsSync, mkdirSync, readFileSync, renameSync, statSync, unlinkSync, writeFileSync } from 'node:fs'\nimport { homedir } from 'node:os'\nimport { dirname, join } from 'node:path'\nimport { backupMemoryDb, closeAllDbs, getDb, memoryDbPath } from './db.js'\nimport { parseModelSpec, REFLECT_DELEGATE_MARKER, REFLECT_DONE_DELEGATE_MARKER, DREAM_DELEGATE_MARKER, type AgentOptionsSpec } from './delegate.js'\nimport { CONFIG_DEFAULTS } from './defaults.js'\nimport { activeHomeDir, homeDirPresets, resolveHomeDir, switchHomeDir } from './home-dir.js'\nimport { ensureV0SessionsMigrated } from './migrate-v0.js'\n\nimport {\n  abortDream,\n  advanceDream,\n  DEFAULT_RULES_REVIEW_DAYS,\n  DREAM_MARKER,\n  dreamCommandDefinition,\n  dreamTool,\n  disposeDreamHeartbeats,\n  handleMemoryTurnFailure,\n  noteActivity,\n  registerLiveAgent,\n  scheduleDream,\n  sendMemoryTurn,\n  shortSessionId,\n  type DreamConfig,\n} from './dream.js'\nimport { buildHitInjection, buildInjection, buildReinjection, clearReinjectPending, isReinjectPending, markAccessed, markReinjectPending, markSearched, readProjectQueried, readSeen, readInjected, releaseSeen } from './inject.js'\nimport { migrateLegacy } from './migrate.js'\nimport { buildReflectMessage, consecutiveToolSteps, PLUGIN_SOURCE, REFLECT_MARKER, scanTurn } from './reflect.js'\nimport { isMeowSource } from './source.js'\nimport { registerMemoryTools, setMemoryToolGate } from './tools.js'\nimport { authGateLazy } from './auth-gate.js'\nimport { resolveSlotText, setPromptLang } from './prompt-loader.js'\nimport {\n  enableWorkspaceTrust,\n  hasExternalNoticeShown,\n  isUntrustedMemoryWorkspace,\n  markExternalNoticeShown,\n  normalizeWorkspacePath,\n  seedTrustedWorkspaces,\n  trustCommandDefinition,\n} from './trust.js'\n\n/** 首次欢迎引导的 seen 记账 id（accessed 通道，非真实记忆 id；releaseSeen 不清除）。 */\nconst WELCOME_GUIDE_SEEN_ID = '__welcomeGuide__'\n/** 首建提示的 accessed 哨兵（issue #37 增量①；per-session 至多一次）。 */\nconst FIRST_CREATE_NOTICE_SEEN_ID = '__firstCreateNotice__'\nimport { collectDreamStates, headerOf, DreamStateBroadcast, type PersistedSessionLike } from './dream-signal.js'\n\nexport const name = 'meow-memory'\nexport const inject = ['tools']\n\n/** 记忆来源机器元数据，供前端与下游消费，解耦于自然语言文本。 */\nexport interface MemorySourceMeta {\n  kind: 'initial' | 'hit' | 'reinjection' | 'welcome'\n  ids?: string[]\n}\n\n/** v0 会话格式兼容：MemorySourceMeta 编码为 sections 的保留节 __meta__。 */\nconst META_SECTION_NAME = '__meta__'\n\nfunction encodeMetaSection(meta: MemorySourceMeta): { name: string; text: string } {\n  return { name: META_SECTION_NAME, text: JSON.stringify(meta) }\n}\n\n/** 把动态记忆作为独立上下文消息交给模型，不改写人类 user 消息。 */\nfunction createMemorySnapshotMessage(text: string, meta: MemorySourceMeta): ReturnType<typeof createUserMessage> {\n  return createUserMessage({\n    content: [{ type: 'text', text }],\n    source: {\n      ...PLUGIN_SOURCE,\n      form: 'snapshot',\n      sections: [encodeMetaSection(meta), { name: '长期记忆', text }],\n    },\n  })\n}\n\n/** 构造独立的插件通知消息（如首次语言引导），不改写人类 user 消息。\n *  notice form 按 dsh-llm ContextFormed 契约带 summary（折叠行一行摘要，≤120 字符）；\n *  不复用 source.memory 顶层字段（v0.24- 遗留形态，新消息只用 ContextFormed 声明的键），\n *  welcome 类一次性通知的元数据本就无消费者。 */\nfunction createMemoryNoticeMessage(text: string): ReturnType<typeof createUserMessage> {\n  return createUserMessage({\n    content: [{ type: 'text', text }],\n    source: {\n      ...PLUGIN_SOURCE,\n      form: 'notice',\n      summary: boundContextSummary(text.replace(/\\s+/g, ' ').trim()),\n    },\n  })\n}\n\n/**\n * 记忆系统静态手册 —— 挂进 system prompt（order 130 = 工具指南区间末尾，\n * 紧随各 tool:* 说明（100–116）之后，与工具说明列在一起）。\n * 文本恒定、不随会话变化 → 前缀稳定，KV 缓存友好；动态记忆内容（soul/user/\n * 导引/命中）仍走首条消息注入。文案与 tools.ts 的工具 schema 保持一致。\n */\n/** system prompt 手册（文案外置 v0.19.0）：prompts/zh/system-guide.md，运行时读取——\n *  改 md 文件下一次 apply / 热重载后生效，无需改代码。文本恒定、不随会话变化 →\n *  前缀稳定，KV 缓存友好；动态记忆内容（soul/user/导引/命中）仍走首条消息注入。\n *  文案与 tools.md 的工具 schema 保持一致。\n */\nexport function getMemoryGuide(): string {\n  return resolveSlotText('system-guide')\n}\n\n// ── 性能诊断（perf.log，全局目录 activeHomeDir()；卡死时查数据） ─────────────\n// 模块级计数器：模块只初始化一次；apply 每次执行 +1——若日志里 apply 编号异常\n// 跳跃/重复，说明 apply 被多次调用（handler 叠加）。事件计数看事件吞吐。\nlet applyCount = 0\nlet evtCount = 0\nlet perfBoot = Date.now()\nlet lastPerfLog = Date.now()\nfunction perf(msg: string): void {\n  try {\n    const file = join(activeHomeDir(), 'perf.log') // 动态取：全局目录热切换后下一笔即落新目录\n    mkdirSync(dirname(file), { recursive: true })\n    appendFileSync(file, `[${new Date().toISOString()}] ${msg}\\n`)\n  } catch {\n    /* 日志失败不阻塞 */\n  }\n}\n/** 事件吞吐统计：每 5 秒落一条（同步追加，不阻塞）。 */\nfunction perfEvent(): void {\n  evtCount++\n  const now = Date.now()\n  if (now - lastPerfLog >= 5000) {\n    const elapsed = (now - perfBoot) / 1000\n    perf(`evt total=${evtCount} elapsed=${elapsed.toFixed(1)}s rate=${(evtCount / Math.max(elapsed, 0.001)).toFixed(1)}/s`)\n    lastPerfLog = now\n  }\n}\n\n// ── 主目录日志清扫（48h 保留 + perf.log 大小轮转；用户拍板 2026-09-24） ──────\n// 白名单精确点名，绝不 glob 目录——~/.dsh-meow 下还住着 window-index.json、\n// migrate-v0-state.json(.bak)、prompts/ 等非日志住户。判定用文件 mtime（append\n// 天然维护，恒等于最后一行的时刻，零解析）；双实例共享本目录时，活跃实例持续\n// 刷新 mtime，天然防误删活日志。单文件失败（占用/权限）静默跳过，下次启动再试。\nconst LOG_RETENTION_MS = 48 * 60 * 60 * 1000\nconst PERF_LOG_ROTATE_BYTES = 5 * 1024 * 1024\nconst HOME_LOGS = ['perf.log', 'perf.log.old', 'settings-register-error.log', 'apply-error.log']\n\n/** 启动清扫：白名单日志距上次写入超 48h 的删除；perf.log 超 5MB 轮转成 .old\n *  （覆盖上一代，历史保一代）。只在 apply（启动/热重载）时跑——废弃日志只有\n *  进程都停了才会变老，下次启动清扫即完备；disabled 时不跑。dir/now 参数化供\n *  测试隔离（测试绝不触真实全局目录）。返回值交调用方落 perf，自身零副作用日志。 */\nexport function sweepHomeLogs(dir = activeHomeDir(), now = Date.now()): { swept: string[]; rotated: boolean } {\n  const swept: string[] = []\n  const cutoff = now - LOG_RETENTION_MS\n  for (const name of HOME_LOGS) {\n    if (!name.endsWith('.log')) continue // 防御断言：名单误配也只可能是 .log\n    try {\n      const file = join(dir, name)\n      if (statSync(file).mtimeMs < cutoff) {\n        unlinkSync(file)\n        swept.push(name)\n      }\n    } catch {\n      /* 不存在/占用/权限：跳过 */\n    }\n  }\n  let rotated = false\n  try {\n    const cur = join(dir, 'perf.log')\n    if (statSync(cur).size > PERF_LOG_ROTATE_BYTES) {\n      renameSync(cur, join(dir, 'perf.log.old')) // 覆盖上一代（MOVEFILE_REPLACE_EXISTING）\n      rotated = true\n    }\n  } catch {\n    /* 不存在（刚被 48h 清掉）/被另一实例占用：跳过，下次启动再轮转 */\n  }\n  return { swept, rotated }\n}\n\n/** homeDirPresets 的启动期快照（模块加载时取一次；异常回空表——meta 缺席只损失\n *  设置页 radio 旁的预设路径显示，绝不弄崩插件加载）。 */\nfunction homeDirPresetsDefault(): Record<string, string> {\n  try {\n    return homeDirPresets()\n  } catch {\n    return {}\n  }\n}\n\nconst config = z.object({\n  /** 总开关：false 时注入、反思、工具全部停用。 */\n  enabled: z.boolean().default(true),\n  /** 记忆目录（相对工作区）。 */\n  projectDir: z.string().default('.dsh-meow'),\n  /** 全局目录（实例级数据家：日志/window-index/prompts 覆盖层/migrate 状态）。\n   *  'default'=平台用户主目录 | 'dsh-storage'=<DSH home>/storages/meow-memory |\n   *  'plugin-root'=<插件根>/storage | 绝对路径=自定义。''/缺省=默认。\n   *  变更即自动迁移旧目录内容（同盘移动/跨盘复制，旧目录绝不自动删）。 */\n  homeDir: z.string().required(false),\n  /** homeDirPresets（只读 meta，非配置）：三个全局目录预设的实际落点，设置页\n   *  radio 旁显示。0.1.7 的 base 视图 = 宿主 resolveConfig(inherited) 后按 schema\n   *  键投影——不在 schema 声明的键宿主永远剥掉，cordis.patch.yml 通道也走不通\n   * （patch config 会撞设置写入的全等比对死锁，2026-09-25 实证），所以只能住进\n   *  schema 默认值，由官方深填机带进 base/value 两视图。默认值在 schema 构建时\n   *  取一次：预设落点因机器/安装位置而异、进程内不变（热切换只改 active，不改\n   *  预设定义）。不进 CONFIG_DEFAULTS——「恢复默认」绝不能把它当字段写进 user 层；\n   *  它也不是设置页 FieldSpec，页面与 resolveConfig 都不读它。 */\n  homeDirPresets: z.dict(z.string()).default(homeDirPresetsDefault()),\n  /** 关键词命中条数上限（fact/lesson/rules/topic 短条目，每条用户消息命中注入）。 */\n  hitTopK: z.number().min(0).max(10).default(2),\n  /** 导引标题截断长度。 */\n  titleMax: z.number().min(10).max(200).default(40),\n  /** 是否在 ReAct 任务结束后自动注入反思。 */\n  reflect: z.boolean().default(true),\n  /** 单任务内连续工具 step 达到该值才在结束时触发反思（用户拍板：react ≥7 轮）。 */\n  reflectTurns: z.number().min(1).max(50).default(7),\n  /** 首次打开库时自动迁移旧 PROJECT.md。 */\n  autoMigrate: z.boolean().default(true),\n  /** prompt 语言（prompts/<lang>/ 语言包目录名）：决定注入/反思/dream 文案、工具\n   *  描述与 BM25 分词的语言。**首次使用建议显式配置**——记忆条目语言必须与 BM25\n   *  关键词语言一致，否则检索匹配率崩（详见 README）。zh=内置默认；en 等社区语言包\n   *  放 lib/prompts/（随包）或 homedir/.dsh-meow/prompts/（实例覆盖，可只覆盖部分槽位）。\n   *  不设置（undefined）：运行时按 zh 跑，且插件生效后的第一条真实用户消息会注入\n   *  「首次设置」引导任务（AI 判断用户语言并完成配置，每会话至多提醒一次）。 */\n  promptLang: z.string().required(false),\n  /** 空闲整理（dream）。 */\n  dream: z\n    .object({\n      enabled: z.boolean().default(true),\n      /** 窗口空闲多少分钟后允许 dream（用户拍板 2026-08-19：3 小时）。 */\n      idleMinutes: z.number().min(1).default(180),\n      /** 抑制时段（目标时区，\"HH:MM\" 起止）：这些时段内不触发 dream。 */\n      suppressWindows: z\n        .array(z.object({ start: z.string(), end: z.string() }))\n        .default([{ start: '09:00', end: '12:00' }, { start: '14:00', end: '18:00' }]),\n      /** 每个抑制时段开始前追加的不触发分钟数（峰时前 15 分钟也不触发）。 */\n      suppressLeadMinutes: z.number().min(0).max(120).default(15),\n      checkMinutes: z.number().min(1).default(15),\n      // 用户系统是美区时间（隐私设置），抑制时段按中国时区计算\n      timeZone: z.string().default('Asia/Shanghai'),\n      /** rules 防 churn（测评 2026-08-25）：updated_at 距今超该天数的稳定准则不进 dream 第 1 轮清单；0=不过滤。 */\n      rulesReviewDays: z.number().min(0).default(DEFAULT_RULES_REVIEW_DAYS),\n    })\n    .default({}),\n  /** 记忆停用工作区名单（#28）：cwd 精确匹配（路径归一：斜杠统一 + 去尾斜杠 + 大小写\n   *  不敏感）。命中的工作区完全停用记忆（读/整理/写全拒，含手动 /dream）——一次性\n   *  任务的工作区不污染记忆库。 */\n  disabledWorkspaces: z.array(z.string()).default([]),\n  /** 记忆库自动备份（#37，默认关）：每次 dream 收尾把 memory.db 快照轮转到\n   *  memory.db.bak（VACUUM INTO 一致性备份，mtime 判增量）。注册期消费，改动需重载。 */\n  backup: z\n    .object({\n      enabled: z.boolean().default(false),\n    })\n    .default({}),\n  /** 整理任务的模型（可选换模型）。反思/梦境永远在主窗口执行（steer）——配置了\n   *  model 时仅在这两类轮的请求上经 agent/request waterfall 覆盖 provider/model，\n   *  轮次结束自动换回主模型；不再提供\"独立执行\"开关（v0.24 移除）。 */\n  delegate: z\n    .object({\n      /** 反思/梦境轮换用模型：留空 = 全程主模型；'provider/model'（dsh route 格式）\n       *  指定 provider+model，'model' 只换 model（provider 继承主会话）。 */\n      model: z.string().required(false),\n    })\n    .default({}),\n})\n\n// DSH settings requires a volatile root schema. Legacy parsers return a plain\n// object; current Hosts provide a get() reference. Config merging and the live\n// reader accept both shapes and track replacement values behind the reference.\nObject.assign(config.meta, { volatile: true })\n\nexport { config as Config }\n\n// ── 设置页（喵记忆标签页）的数据底座 ──────────────────────────────────────────\n//\n// installSettingsSection(ctx, SETTINGS_NS, ...) 在 applyInner 最前面调用；标签页\n// （client/settings-page.ts）经 settingsScope.bind({namespace}) 读写 user 层，\n// applyInner 解析配置时把 user 层字段级合并进 patch config（用户改过的字段以\n// 设置页为准）。生效时机=config 在 apply 时解析 → 设置页保存后需热重载/重启插件。\n\nexport const SETTINGS_NS = 'meow-memory'\n\n/** 出厂默认值定义已抽到 defaults.ts（host/client 共用，理由见该文件头注释）；\n *  设置页 base（预填层）=出厂默认 + patch 基线，promptLang 刻意缺席=未设置语义。 */\nexport { CONFIG_DEFAULTS, factoryDefaultOf } from './defaults.js'\n\n/** 单个时间点（suppressWindows 的 start/end）。 */\nconst TIME_OF_DAY_RE = /^\\d{1,2}:\\d{2}$/\n\n/**\n * 设置页 user 层的字段级类型校验（RPC 写入走这里，编不过拒写）。\n * 手编 settings.yaml 不经此路径，由 merge 后 resolveConfig 的兜底解析防御。\n */\nexport function validateConfigUserLayer(value: unknown): void {\n  if (value === undefined || value === null || typeof value !== 'object' || Array.isArray(value)) {\n    throw new Error('配置必须是对象')\n  }\n  const v = value as Record<string, unknown>\n  const reqBool = (k: string): void => {\n    if (v[k] !== undefined && typeof v[k] !== 'boolean') throw new Error(`${k} 必须是布尔`)\n  }\n  const reqStr = (k: string): void => {\n    if (v[k] !== undefined && typeof v[k] !== 'string') throw new Error(`${k} 必须是字符串`)\n  }\n  const reqNum = (k: string): void => {\n    if (v[k] === undefined) return\n    if (typeof v[k] !== 'number' || !Number.isFinite(v[k] as number)) throw new Error(`${k} 必须是数字`)\n  }\n  reqBool('enabled')\n  reqStr('projectDir')\n  reqStr('homeDir')\n  reqNum('hitTopK')\n  reqNum('titleMax')\n  reqBool('reflect')\n  reqNum('reflectTurns')\n  reqBool('autoMigrate')\n  reqStr('promptLang')\n  const d = v.dream\n  if (d !== undefined) {\n    if (d === null || typeof d !== 'object' || Array.isArray(d)) throw new Error('dream 必须是对象')\n    const dd = d as Record<string, unknown>\n    if (dd.enabled !== undefined && typeof dd.enabled !== 'boolean') throw new Error('dream.enabled 必须是布尔')\n    reqNum('dream.idleMinutes') // 顶层校验器只认顶层键，dream 子键在此手查\n    if (dd.idleMinutes !== undefined && (typeof dd.idleMinutes !== 'number' || !Number.isFinite(dd.idleMinutes))) throw new Error('dream.idleMinutes 必须是数字')\n    for (const k of ['suppressLeadMinutes', 'checkMinutes', 'rulesReviewDays'] as const) {\n      if (dd[k] !== undefined && (typeof dd[k] !== 'number' || !Number.isFinite(dd[k]))) throw new Error(`dream.${k} 必须是数字`)\n    }\n    if (dd.timeZone !== undefined && typeof dd.timeZone !== 'string') throw new Error('dream.timeZone 必须是字符串')\n    if (dd.suppressWindows !== undefined) {\n      if (!Array.isArray(dd.suppressWindows)) throw new Error('dream.suppressWindows 必须是数组')\n      for (const w of dd.suppressWindows as unknown[]) {\n        const win = w as { start?: unknown; end?: unknown }\n        if (typeof win !== 'object' || win === null || typeof win.start !== 'string' || typeof win.end !== 'string' || !TIME_OF_DAY_RE.test(win.start) || !TIME_OF_DAY_RE.test(win.end)) {\n          throw new Error('dream.suppressWindows 每项必须是 { start: \"HH:MM\", end: \"HH:MM\" }')\n        }\n      }\n    }\n  }\n  const dg = v.delegate\n  if (dg !== undefined) {\n    if (dg === null || typeof dg !== 'object' || Array.isArray(dg)) throw new Error('delegate 必须是对象')\n    const ddg = dg as Record<string, unknown>\n    // v0.24 移除 delegate.reflect/dream（独立执行不再可选）；历史 settings.yaml\n    // user 层里残留的这两个键只忽略不报错（手编配置宽容，读取方不再消费）。\n    if (ddg.model !== undefined && typeof ddg.model !== 'string') throw new Error('delegate.model 必须是字符串')\n  }\n  if (v.disabledWorkspaces !== undefined) {\n    if (!Array.isArray(v.disabledWorkspaces)) throw new Error('disabledWorkspaces 必须是字符串数组')\n    for (const p of v.disabledWorkspaces) {\n      if (typeof p !== 'string' || p.trim().length === 0) throw new Error('disabledWorkspaces 每项必须是非空字符串')\n    }\n  }\n  if (v.backup !== undefined) {\n    if (v.backup === null || typeof v.backup !== 'object' || Array.isArray(v.backup)) throw new Error('backup 必须是对象')\n    const bkv = v.backup as Record<string, unknown>\n    if (bkv.enabled !== undefined && typeof bkv.enabled !== 'boolean') throw new Error('backup.enabled 必须是布尔值')\n  }\n}\n\n/** Read a legacy config object or the current Host's root volatile reference. */\nfunction readConfigRoot(value: unknown): unknown {\n  const ref = value as { get?: () => unknown } | null | undefined\n  return ref !== null && typeof ref === 'object' && typeof ref.get === 'function' ? ref.get() : value\n}\n\n/**\n * 设置页 user 层字段级覆盖 patch config（装配配置=基线）。\n * dream/delegate 子对象做浅合并：用户只改一个子字段不丢 patch 里的其余键。\n */\nexport function mergeConfigLayer(patch: unknown, user: Record<string, unknown> | undefined): unknown {\n  patch = readConfigRoot(patch)\n  user = readConfigRoot(user) as Record<string, unknown> | undefined\n  // user === null：YAML 里写成空段（`meow-memory:` 后面没内容）会解析成 null，而\n  // typeof null === 'object' 会漏过下面这行，随后 Object.entries(null) 抛 TypeError\n  // 直接崩掉 applyInner（插件整块不启动）。防御式直通 patch 层。\n  if (user === undefined || user === null || typeof user !== 'object') return patch\n  const base = (typeof patch === 'object' && patch !== null ? { ...(patch as Record<string, unknown>) } : {}) as Record<string, unknown>\n  for (const [key, value] of Object.entries(user)) {\n    if (key === 'dream' || key === 'delegate') {\n      // 子对象浅合并：用户只改一个子字段不丢 patch 里的其余键\n      const pv = (base[key] ?? {}) as Record<string, unknown>\n      const uv = (typeof value === 'object' && value !== null ? value : {}) as Record<string, unknown>\n      base[key] = { ...pv, ...uv }\n    } else {\n      base[key] = value\n    }\n  }\n  return base\n}\n\ninterface ResolvedConfig {\n  enabled: boolean\n  projectDir: string\n  /** 原样透传（'default'|'dsh-storage'|'plugin-root'|绝对路径|undefined）；绝对路径化在 resolveHomeDir。 */\n  homeDir: string | undefined\n  hitTopK: number\n  titleMax: number\n  reflect: boolean\n  reflectTurns: number\n  autoMigrate: boolean\n  /** undefined = 用户未配置（首次设置引导的触发信号）；运行时语言兜底 zh。 */\n  promptLang: string | undefined\n  dream: DreamConfig\n  delegate: { modelSpec: AgentOptionsSpec | undefined }\n  /** 记忆库自动备份（#37）：注册期消费（dream 收尾信号侧）。 */\n  backup: { enabled: boolean }\n  /** 工作区停用名单（#28）：原样保留，判定时路径归一。 */\n  disabledWorkspaces: string[]\n}\n\nfunction resolveConfig(config: unknown): ResolvedConfig {\n  const c = (config ?? {}) as Partial<ResolvedConfig>\n  const d = (c.dream ?? {}) as Partial<DreamConfig>\n  const dg = (c.delegate ?? {}) as { reflect?: boolean; model?: string }\n  const bk = (c.backup ?? {}) as { enabled?: boolean }\n  return {\n    enabled: c.enabled ?? true,\n    projectDir: c.projectDir ?? '.dsh-meow',\n    homeDir: typeof c.homeDir === 'string' ? c.homeDir : undefined,\n    hitTopK: c.hitTopK ?? 2,\n    titleMax: c.titleMax ?? 40,\n    reflect: c.reflect ?? true,\n    reflectTurns: c.reflectTurns ?? 7,\n    autoMigrate: c.autoMigrate ?? true,\n    promptLang: typeof c.promptLang === 'string' && c.promptLang.trim() ? c.promptLang.trim() : undefined,\n    dream: {\n      enabled: d.enabled ?? true,\n      idleMinutes: d.idleMinutes ?? 180,\n      suppressWindows: d.suppressWindows ?? [{ start: '09:00', end: '12:00' }, { start: '14:00', end: '18:00' }],\n      suppressLeadMinutes: d.suppressLeadMinutes ?? 15,\n      checkMinutes: d.checkMinutes ?? 15,\n      timeZone: d.timeZone ?? 'Asia/Shanghai',\n      rulesReviewDays: d.rulesReviewDays ?? DEFAULT_RULES_REVIEW_DAYS,\n    },\n    delegate: (() => {\n      // 反思/梦境永远 steer（主窗口执行，v0.24 拍板）；modelSpec 仅供 agent/request\n      // waterfall 在插件轮请求上覆盖模型（轮次结束自动换回主模型）。\n      return { modelSpec: parseModelSpec(dg.model) }\n    })(),\n    disabledWorkspaces: Array.isArray(c.disabledWorkspaces)\n      ? c.disabledWorkspaces.map((p) => String(p).trim()).filter((p) => p.length > 0)\n      : [],\n    backup: {\n      enabled: bk.enabled ?? false,\n    },\n  }\n}\n\ninterface SessionHeaderLike {\n  cwd?: string\n  id?: string\n  parentSession?: unknown\n  /** 子代理权威标记（dsh：origin === 'subagent'）；GUI fork 的会话只有 parentSession 无 origin。 */\n  origin?: unknown\n}\n\n// #71：agent/request 解析结果与要还原的模型路由（effort 只保留显式值）。\ninterface ModelRoute {\n  provider?: string\n  model?: string\n  reasoningEffort?: string\n}\n\n/** 工作区 = 会话 cwd（项目根）；目录名 projectDir 单独下传给各模块（防双拼）。 */\nfunction workspaceOfAgent(agent: { session?: { header?: SessionHeaderLike } }): string | null {\n  const cwd = agent?.session?.header?.cwd\n  return typeof cwd === 'string' && cwd.length > 0 ? cwd : null\n}\n\nfunction sessionIdOfAgent(agent: { session?: { header?: SessionHeaderLike } }): string {\n  const id = agent?.session?.header?.id\n  return typeof id === 'string' && id.length > 0 ? id : 'unknown'\n}\n\n/**\n * 双版本会话事件读取：dsh 0.1.2-alpha.4 重构移除 Session.events 属性，\n * 改为 ownEvents() 方法（返回剔除 fork 继承前缀的本会话事件，与旧版\n * events 语义等价）；旧版仍是数组属性。探测函数形态优先，回退属性，\n * 两者都缺返回空数组（fail-closed：绝不抛 events is not iterable）。\n */\nexport function sessionEventsOf(session: { events?: readonly unknown[]; ownEvents?: () => readonly unknown[] } | undefined | null): readonly unknown[] {\n  if (typeof session?.ownEvents === 'function') {\n    const evs = session.ownEvents()\n    return Array.isArray(evs) ? evs : []\n  }\n  const evs = session?.events\n  return Array.isArray(evs) ? evs : []\n}\n\n/** 本 turn 是否为 dream 轮（事件流里存在 meow-memory 的 dream 指令消息）。 */\nfunction wasDreamTurn(events: readonly unknown[]): boolean {\n  for (let i = events.length - 1; i >= 0; i--) {\n    const e = events[i] as { type?: string; data?: { source?: { kind?: string; plugin?: string }; content?: Array<{ type?: string; text?: string }> } }\n    if (e?.type === 'turn/start') break\n    if (e?.type === 'user/message' && isMeowSource(e.data?.source)) {\n      if ((e.data.content ?? []).some((b) => b.type === 'text' && b.text?.includes(DREAM_MARKER))) return true\n    }\n  }\n  return false\n}\n\n/**\n * 当前 turn 是否为 meow-memory 的反思/梦境轮（换模型覆盖判定，agent/request 用）。\n * 判定口径与事件链的插件消息识别一致：最后一个 turn/start 之后的 user/message 帧，\n * source.kind !== 'user'（用户亲手发的消息绝不判 marker，防引用标记文本误伤）且\n * 文本含 [meow-memory-reflect] / [meow-memory-dream]。steer 指令消息在请求发出前\n * 已落 log（agent-loop：pre-step decision → append user/message → step/buildRequest），\n * 因此请求时判定读到的数据完备；轮次结束不再 steer，下个 turn 无 marker → 自动\n * 换回主模型，无需任何状态清理。\n */\nexport function isMemoryTaskTurn(events: readonly unknown[]): boolean {\n  let startIdx = -1\n  for (let i = events.length - 1; i >= 0; i--) {\n    if ((events[i] as { type?: string })?.type === 'turn/start') {\n      startIdx = i\n      break\n    }\n  }\n  if (startIdx < 0) return false\n  for (let i = startIdx; i < events.length; i++) {\n    const e = events[i] as { type?: string; data?: { source?: { kind?: string }; content?: Array<{ type?: string; text?: string }> } }\n    if (e?.type !== 'user/message') continue\n    if (e.data?.source?.kind === 'user') continue\n    const text = (e.data?.content ?? [])\n      .filter((b) => b.type === 'text' && typeof b.text === 'string')\n      .map((b) => b.text ?? '')\n      .join(' ')\n    if (text.includes(REFLECT_MARKER) || text.includes(DREAM_MARKER)) return true\n  }\n  return false\n}\n\n/** 请求解析结果 → 主模型路由（#71 还原用）。 */\nfunction mainRouteOf(config: ModelRoute): ModelRoute {\n  return { provider: config.provider, model: config.model, ...(config.reasoningEffort === undefined ? {} : { reasoningEffort: String(config.reasoningEffort) }) }\n}\n\n// #71：覆盖之后用户是否亲手选过模型？宿主 selectForNextRequest 会 append model/selection。\n// 反向扫描：先撞到 model/selection = 用户选择（含选中 delegate 本身）；先撞到路由不等于\n// delegate 的 request/header = 覆盖之前的历史，结束（覆盖前后的 header 都是 delegate/主模型，\n// 不会误判）。零分配，O(尾部事件)。\nfunction userSelectedAfterOverride(events: readonly unknown[], route: ModelRoute): boolean {\n  for (let i = events.length - 1; i >= 0; i--) {\n    const e = events[i] as { type?: string; data?: { header?: { config?: ModelRoute } } } | undefined\n    if (e?.type === 'model/selection') return true\n    if (e?.type === 'request/header') {\n      const c = e.data?.header?.config\n      if (c?.provider !== route.provider || c?.model !== route.model) return false\n    }\n  }\n  return false\n}\n\n/** 最近一个 turn/end 的 reason.kind（aborted/interrupted 表示用户停止，不反思不推进）。 */\nfunction lastTurnEndReason(events: readonly unknown[]): string | null {\n  for (let i = events.length - 1; i >= 0; i--) {\n    const e = events[i] as { type?: string; data?: { reason?: { kind?: string } } }\n    if (e?.type === 'turn/start') break\n    if (e?.type === 'turn/end' && typeof e.data?.reason?.kind === 'string') return e.data.reason.kind\n  }\n  return null\n}\n\n/** apply 包装：错误落盘（homedir/.dsh-meow/apply-error.log），排查 fiber 启动失败。 */\nexport async function apply(ctx: Context, config: unknown): Promise<void> {\n  try {\n    return await applyInner(ctx, config)\n  } catch (e) {\n    try {\n      const errFile = join(activeHomeDir(), 'apply-error.log')\n      mkdirSync(dirname(errFile), { recursive: true })\n      appendFileSync(errFile, `[${new Date().toISOString()}] ${e instanceof Error ? (e.stack ?? e.message) : String(e)}\\n`)\n    } catch {\n      /* 日志失败忽略 */\n    }\n    throw e\n  }\n}\n\n/** dsh-settings 服务最小形态（新旧两版公共面并集）。 */\ninterface SettingsScopeLike {\n  get: () => unknown\n  watch: (cb: () => void) => unknown\n}\ninterface SettingsServiceLike {\n  /** dsh 0.1.3+ 服务方法；0.1.2 及以下不存在。 */\n  installSection?: (owner: Context, ns: string, schema: unknown, entry: unknown, hooks: Record<string, unknown>) => void\n  /** 两版都有：底层命名空间注册（旧 installSettingsSection 内部即调它）。 */\n  register?: (ns: string, schema: unknown, options: { base: unknown; validate?: (value: unknown) => void }) => SettingsScopeLike\n}\n\n/**\n * 双版本设置区注册：dsh 0.1.2 及以下旧版把 installSettingsSection 作为\n * dsh-settings 的自由函数提供（0.1.5 起已移除，故本插件不能静态 import 它——\n * ESM 缺导出会在模块加载期直接报错）。按「settings 服务是否暴露 installSection\n * 方法」分流，它正好是两版的能力分界：0.1.3+ 有 installSection（走新 API）；\n * 0.1.2 及以下没有（回退，复刻旧 installSettingsSection 的 register 行为）。\n */\nfunction installSettingsSectionCompat(\n  settingsCtx: unknown,\n  ownerCtx: Context,\n  ns: string,\n  schema: unknown,\n  entry: unknown,\n  hooks: {\n    validate?: (value: unknown) => void\n    setSource: (get: () => unknown) => void\n    onChange: () => void\n  },\n): void {\n  const sctx = settingsCtx as {\n    settings: SettingsServiceLike\n    effect: (fn: () => () => void) => unknown\n  }\n  const settings = sctx.settings\n\n  // 新版（dsh 0.1.3+）：官方服务方法 installSection。\n  if (typeof settings.installSection === 'function') {\n    settings.installSection(ownerCtx, ns, schema, entry, hooks as unknown as Record<string, unknown>)\n    return\n  }\n\n  // 旧版（dsh 0.1.2 及以下）：复刻 installSettingsSection 的 register + effect + watch。\n  const register = settings.register\n  if (typeof register !== 'function') {\n    // 0.1.7+：SettingsForms 已删 installSection/register，设置页由 Config schema 的\n    // describe 自动表单渲染，值读写走上方 describe/write 兼容腿——本函数无可注册项，\n    // 静默跳过。其余未知宿主：设置页本就不可用，warn 留痕（与注册失败 catch 路径同\n    // 口径）。原实现在此 throw，但它落在 inject 回调里、外层 catch 接不住，只会每轮\n    // 装配刷一条误导性 error（issue #34：功能其实全部正常），故一律不再抛。\n    const proto = Object.getPrototypeOf(settings) as { describe?: unknown } | null\n    if (proto !== null && typeof proto.describe === 'function') return\n    ownerCtx.logger.warn('meow-memory: settings 服务无 installSection/register（非 0.1.7+ 形态），跳过设置区注册（配置走 patch 层）')\n    return\n  }\n  const scope = register.call(settings, ns, schema, {\n    base: entry,\n    ...(hooks.validate === undefined ? {} : { validate: hooks.validate }),\n  })\n  hooks.setSource(() => scope.get())\n  sctx.effect(() => () => {\n    // fiber 收尾中（值镜像 cordis FiberState：4=DISPOSED / 5=UNLOADING）不再回填。\n    const state = (ownerCtx as unknown as { fiber?: { state?: number } }).fiber?.state\n    if (state === 4 || state === 5) return\n    hooks.setSource(() => entry)\n    hooks.onChange()\n  })\n  hooks.onChange()\n  scope.watch(() => {\n    const state = (ownerCtx as unknown as { fiber?: { state?: number } }).fiber?.state\n    if (state === 4 || state === 5) return\n    hooks.onChange()\n  })\n}\n\n/** 等设置源就绪的上限（issue #21）。真机上 inject 回调最快一个微任务就会跑，\n *  这里给足余量；仅当 settings 服务异常/注册回调始终不回填时才真的等满。 */\nconst SETTINGS_SOURCE_WAIT_MS = 250\n\n// ── 活配置（issue #26）────────────────────────────────────────────────────────\n// 250ms 有界等待在重 profile 上必输（实测 settings 命名空间晚 5.5s 就绪），输掉后\n// settingsGet 恒 undefined、resolved 全按出厂默认跑满进程生命周期——onChange 只热切\n// homeDir，meta.volatile 在 cordis 中无实现（死标记），「重载后生效」对绝大多数字段\n// 不成立。修法不重排 40+ 消费点：在 apply 解析出的 resolved 对象上，把「运行时被\n// 反复读取」的热字段换成 getter，背后接按引用相等做变更检测的缓存读取器。\n// 引用相等的前提：0.1.3+ installSection 作用域在写入提交前返回同一 frozen 对象\n// （commit 时才换引用），引用没变即未变，读取近乎零成本；0.1.7 describe 壳每次\n// 调用全量重建（引用恒新）→ 毫秒级节流兜底最坏路径。\n// ⚠️ 接线坑（#26 报告人 v1 实机踩坑）：settingsGet 本身是个函数（()=>scope.get()），\n// 外层必须再包一层 thunk 捕获 applyInner 作用域里那个稍后才赋值的 let——把函数本体\n// 当源传进去，引用恒定 → 缓存永不失效 → 单测全绿而实机仍按启动默认值跑。\n// 注册期消费的字段（projectDir/homeDir/enabled/delegate.modelSpec + setPromptLang 的\n// 启动调用）保持冻结：热改需要 dispose+重入，设置页按「需重载」语义对待（#26 同口径）。\n\nconst LIVE_CONFIG_KEYS = ['hitTopK', 'titleMax', 'reflect', 'reflectTurns', 'autoMigrate', 'promptLang', 'disabledWorkspaces'] as const\nconst LIVE_DREAM_KEYS = ['enabled', 'idleMinutes', 'suppressWindows', 'suppressLeadMinutes', 'checkMinutes', 'timeZone', 'rulesReviewDays'] as const\n\n/** 工作区是否在停用名单（归一后精确匹配）。导出供测试直调。 */\nexport function workspaceDisabledMatch(list: readonly string[], ws: string): boolean {\n  const n = normalizeWorkspacePath(ws)\n  return list.some((p) => normalizeWorkspacePath(p) === n)\n}\n\n/** 活配置读取器：源引用变化（或首次读取/节流窗口过后）才重新 resolveConfig，\n *  其余读取返回同一缓存对象（引用稳定，调用方可做 identity 比较）。导出供测试直调。 */\nexport function liveConfigReader(patch: unknown, getSource: () => Record<string, unknown> | undefined, minIntervalMs: number): () => ResolvedConfig {\n  let lastSource: Record<string, unknown> | undefined\n  let lastPatch: unknown\n  let lastAt = Number.NEGATIVE_INFINITY\n  let cached: ResolvedConfig | undefined\n  return (): ResolvedConfig => {\n    const now = Date.now()\n    if (cached !== undefined && now - lastAt < minIntervalMs) return cached\n    let source: Record<string, unknown> | undefined\n    try {\n      source = readConfigRoot(getSource()) as Record<string, unknown> | undefined\n    } catch {\n      source = undefined // 源读失败按「无 user 层」处理（patch 层兜底），绝不抛进事件链\n    }\n    const currentPatch = readConfigRoot(patch)\n    if (cached === undefined || source !== lastSource || currentPatch !== lastPatch) {\n      lastSource = source\n      lastPatch = currentPatch\n      cached = resolveConfig(mergeConfigLayer(currentPatch, source))\n    }\n    lastAt = now\n    return cached\n  }\n}\n\n/** 把 resolved 上的热字段替换为 getter（背后走活读取器）。dream 子对象整体换成\n *  一个属性全 getter 的视图——引用稳定，scheduleDream 捕获它不会丢活性。\n *  ⚠️ resolved 必须是独立于读取器缓存的对象（生产=resolveConfig(merged) 的新实例）：\n *  若误传读取器自身缓存，getter 读回同一对象会无限递归——defineLive 对此有防御\n *  （回退 defineProperty 前的原值），但防御态下热字段在下次源变化前不再更新。\n *  导出供测试直调。 */\nexport function applyLiveConfig(resolved: ResolvedConfig, readLiveConfig: () => ResolvedConfig): ResolvedConfig {\n  const defineLive = <O extends object, K extends keyof O>(obj: O, key: K, live: () => O): void => {\n    const fallback = obj[key]\n    Object.defineProperty(obj, key, {\n      configurable: true,\n      enumerable: true,\n      get: () => {\n        const cur = live()\n        return cur === obj ? fallback : cur[key]\n      },\n    })\n  }\n  for (const key of LIVE_CONFIG_KEYS) defineLive(resolved, key, readLiveConfig)\n  const dreamView = {} as DreamConfig\n  for (const key of LIVE_DREAM_KEYS) defineLive(dreamView, key, (): DreamConfig => readLiveConfig().dream)\n  Object.defineProperty(resolved, 'dream', { configurable: true, enumerable: true, get: () => dreamView })\n  return resolved\n}\n\n/** 全局目录切换结果落日志（apply 与设置页 onChange 共用口径；跨盘复制带多实例提醒）。 */\nfunction logHomeDirSwitch(ctx: Context, sw: ReturnType<typeof switchHomeDir>): void {\n  if (sw.mode === 'copy') {\n    ctx.logger.warn(`meow-memory: 全局目录已切换为 ${sw.to}（自 ${sw.from} 复制 ${sw.files} 项）。旧目录保留未删，确认无误后可手动删除；若多个 dsh 实例共享旧目录，请同步修改其他实例的设置`)\n  } else if (sw.migrated) {\n    ctx.logger.info(`meow-memory: 全局目录已切换为 ${sw.to}（自 ${sw.from} 移动 ${sw.files} 项）`)\n  } else if (sw.changed) {\n    ctx.logger.info(`meow-memory: 全局目录切换为 ${sw.to}（目标已有内容，直接启用未覆盖）`)\n  } else if (sw.mode === 'failed') {\n    ctx.logger.warn(`meow-memory: 全局目录切换失败（${sw.error}），继续使用 ${sw.from}`)\n  }\n}\n\n/** 设置页保存后的全局目录热切换（fire-and-forget，用户拍板 2026-09-24）：搬移可能\n *  跨盘复制（秒级），异步执行不阻塞保存链路；窗口期日志仍落旧目录（毫秒级），无碍。\n *  搬完把新目录的 window-index 账本 merge 进内存。切换失败只留日志，绝不影响保存。 */\nfunction hotSwitchHomeDir(ctx: Context, config: unknown, get: (() => unknown) | undefined): void {\n  try {\n    const merged = mergeConfigLayer(config, get?.() as Record<string, unknown> | undefined)\n    const resolved = resolveConfig(merged)\n    const target = resolveHomeDir(resolved.homeDir)\n    if (target === activeHomeDir()) return\n    void Promise.resolve().then(() => {\n      try {\n        const sw = switchHomeDir(target)\n        logHomeDirSwitch(ctx, sw)\n        if (sw.changed) {\n          loadWindowIndex(resolved.projectDir ?? '.dsh-meow')\n          // 信任注册表跟着全局目录走（#64）：新目录重新启用 + 播种。新 home 里没有\n          // window-index.json 时播种为空——既有信任以新目录注册表为准（用户主动\n          // 迁目录 = 重新建立信任面，与 window-index 同语义）。\n          enableWorkspaceTrust()\n          seedTrustedWorkspaces()\n        }\n      } catch {\n        /* 热切换失败不影响配置保存 */\n      }\n    })\n  } catch {\n    /* 解析失败不打扰保存 */\n  }\n}\n\nasync function applyInner(ctx: Context, config: unknown): Promise<void> {\n  // ── 设置页命名空间（喵记忆标签页的数据底座）──\n  // installSettingsSection 必须先于 resolveConfig，但「先注册」≠「注册时同步回填」——\n  // inject 回调是异步的（见下），所以 resolve 之前必须显式等 source 就绪。\n  // 三层模型：CONFIG_DEFAULTS（默认）< patch config（0.1.6 手编层，config 参数里已\n  // 合成）< 设置页 user 层（标签页改动，字段级覆盖）。\n  // 0.1.6 腿：settingsBase 显式合成 CONFIG_DEFAULTS⊕config，作为 register 的 base——\n  // patch 手编的值（如 delegate/model）不在 base 里的话标签页显示为空，用户会以为\n  // 配置丢了（2026-09-02 实测踩坑）。附加 homeDirPresets（只读 meta）同因：0.1.6 的\n  // base 通道只认 register 显式传参。\n  // 0.1.7 腿：register 已被宿主删除，base 视图改由宿主拿 Config schema 深填默认值\n  // （resolveConfig(inherited)）——预填全部声明进 schema（含 homeDirPresets），这里\n  // 不再需要任何手动注入。patch config 段已随全等比对死锁退役（2026-09-25）。\n  const settingsBase = { ...mergeConfigLayer(CONFIG_DEFAULTS, config), homeDirPresets: homeDirPresets() } as Record<string, unknown>\n  let settingsGet: (() => unknown) | undefined\n  // 设置源就绪信号（issue #21）：ctx.inject(deps, cb) 的回调**永远不会同步执行**——它\n  // 等价于 ctx.plugin({ inject, apply })，插件体跑在异步启动的子 fiber 里（cordis\n  // lib/index.js:1599），依赖是否已就绪都一样。原实现「注册完紧接着下一行读 setSource\n  // 回填的 getter」因此必然拿到 undefined：settings.yaml / 设置页的 user 层从未进过\n  // resolve，设置页对「影响行为」的字段等于纯展示，连\"重启后生效\"也不成立。\n  // 现在：注册后等 source 就绪再 resolve（等待有界，见 SETTINGS_SOURCE_WAIT_MS）。\n  let markSourceReady: (() => void) | undefined\n  const sourceReady = new Promise<void>((resolve) => { markSourceReady = resolve })\n  let sourceWaitArmed = false\n  // 活配置的 promptLang 热刷新出口（issue #26）：onChange / 0.1.7 写入壳回调。两者都\n  // 可能在 resolved 初始化之前同步触发（0.1.6 旧路径 installSettingsSectionCompat 的\n  // register 分支注册期就调一次 onChange）——holder 未置入时静默跳过，绝不能在\n  // inject 回调里踩 TDZ 把设置区注册炸掉。\n  let resolvedView: ResolvedConfig | undefined\n  const refreshPromptLang = (): void => {\n    if (resolvedView === undefined) return\n    setPromptLang(resolvedView.promptLang ?? 'zh')\n  }\n  try {\n    // 双版本设置区注册（0.1.2 及以下旧版 / 0.1.3+ 新版）分流见 installSettingsSectionCompat：\n    // 新版走 settings.installSection；旧版回退 settings.register 复刻旧自由函数行为。\n    // 注册失败（比如 settings 服务未装配）不影响插件本体：\n    // 下面 catch 会降级为只走 patch 层配置，设置页标签不可用。\n    ctx.inject(['settings'], (settingsCtx: {\n      settings: SettingsServiceLike\n      effect: (fn: () => () => void) => unknown\n    }) => {\n      // 服务端 write 取证壳（0.1.7 写入排障 2026-09-25）：settings 服务就绪回调里\n      // 实例必然在手——给 write 原型包装取证壳，宿主拒写的原始异常（含 message/栈，\n      // 栈定位 configEditor 内具体抛点）落盘 settings-diag.log。仅加日志不改行为。\n      // 必须在 installSectionCompat 之前装配：0.1.7 的服务无 installSection/register，\n      // compat 会抛「neither」被 cordis 静默吞掉——那本身就是关键诊断信号，也要留痕。\n      try {\n        const svc = settingsCtx.settings as unknown as Record<string, unknown>\n        const proto = Object.getPrototypeOf(svc) as { write?: (...args: unknown[]) => unknown; __writeProbe?: boolean }\n        if (proto !== undefined && typeof proto.write === 'function' && proto.__writeProbe !== true) {\n          proto.__writeProbe = true\n          const rawWrite = proto.write.bind(svc)\n          proto.write = (...args: unknown[]) => {\n            const result = rawWrite(...args)\n            if (result instanceof Promise) {\n              return result.catch((e: unknown) => {\n                try {\n                  const diagFile = join(activeHomeDir(), 'settings-diag.log')\n                  mkdirSync(dirname(diagFile), { recursive: true })\n                  appendFileSync(diagFile, `[${new Date().toISOString()}] write(ns=${String(args[0])}) rejected: ${e instanceof Error ? `${e.message}\\n${e.stack ?? ''}` : String(e)}\\n`)\n                } catch {\n                  /* 取证失败忽略 */\n                }\n                throw e\n              })\n            }\n            return result\n          }\n        }\n      } catch {\n        /* 取证壳装配失败忽略 */\n      }\n      // 宿主 configEditor 侧直接取证（write 的第一道门）：entries 的真实清单\n      try {\n        const ce = (svc as unknown as { ownerContext?: { configEditor?: { entries?: () => Array<Record<string, unknown>> } } }).ownerContext?.configEditor\n        if (ce && typeof ce.entries === 'function') {\n          const rows = ce.entries().map((entry) => {\n            const o = entry as Record<string, any>\n            return {\n              id: o.options?.id,\n              state: o.fiber?.state,\n              parent: o.parent?.tree?.ctx?.fiber?.entry?.id ?? null,\n              hasRuntimeConfig: o.fiber?.runtime !== undefined && 'Config' in (o.fiber.runtime as object),\n              configRaw: o.options?.config ?? null,\n            }\n          })\n          const diagFile2 = join(activeHomeDir(), 'settings-diag.log')\n          mkdirSync(dirname(diagFile2), { recursive: true })\n          appendFileSync(diagFile2, `[${new Date().toISOString()}] configEditor entries: ${JSON.stringify(rows)}\\n`)\n        }\n        // edit 取证壳：overridden 拒绝时复算 next/读取 raw 落盘——与合并结果对比差异键\n        if (typeof ce.edit === 'function' && (ce as unknown as { __editProbe?: boolean }).__editProbe !== true) {\n          ;(ce as unknown as { __editProbe?: boolean }).__editProbe = true\n          const origEdit = ce.edit.bind(ce)\n          ce.edit = async function (entry: Record<string, any>, change: (raw: any, inherited: any) => unknown) {\n            // 成功/失败双向取证：成功 dump 写盘的 next；失败 dump 原始异常（含栈）\n            const result = await origEdit(entry, change).catch((e: unknown) => {\n              try {\n                const f = join(activeHomeDir(), 'settings-diag.log')\n                mkdirSync(dirname(f), { recursive: true })\n                appendFileSync(f, `[${new Date().toISOString()}] edit THREW ns=${String(entry?.options?.id)}: ${e instanceof Error ? `${e.message}\\n${String(e.stack).split('\\n').slice(1, 4).join('\\n')}` : String(e)}\\n`)\n              } catch { /* 忽略 */ }\n              throw e\n            })\n            try {\n              const f = join(activeHomeDir(), 'settings-diag.log')\n              mkdirSync(dirname(f), { recursive: true })\n              appendFileSync(f, `[${new Date().toISOString()}] edit OK ns=${String(entry?.options?.id)}\\n`)\n            } catch { /* 忽略 */ }\n            return result\n          }\n        }\n      } catch {\n        /* configEditor 不可达：跳过 */\n      }\n      // 宿主视角的三层配置 dump：SettingsForms.describe 的 meow-memory 视图\n      // （value=最终生效 / base=出厂+patch / user=设置页层）。describe 无副作用，\n      // 启动即采一次 + 5 秒后再采一次（等 entry 激活）。\n      try {\n        const svcAny = settingsCtx.settings as unknown as { describe?: () => unknown }\n        if (typeof svcAny.describe === 'function') {\n          const dumpDescribe = (): void => {\n            try {\n              const view = svcAny.describe()\n              const diagFile = join(activeHomeDir(), 'settings-diag.log')\n              mkdirSync(dirname(diagFile), { recursive: true })\n              const info = {\n                isArray: Array.isArray(view),\n                keys: view && typeof view === 'object' && !Array.isArray(view) ? Object.keys(view) : null,\n                length: Array.isArray(view) ? view.length : null,\n                nsList: Array.isArray(view) ? view.map((row: any) => row?.ns) : null,\n              }\n              appendFileSync(diagFile, `[${new Date().toISOString()}] describe shape: ${JSON.stringify(info)}\\n`)\n              const meowRow = Array.isArray(view) ? view.find((row: any) => row?.ns === 'meow-memory') : undefined\n              if (meowRow !== undefined) {\n                appendFileSync(diagFile, `[${new Date().toISOString()}] meow view: ${JSON.stringify({\n                  revision: meowRow.revision,\n                  value: meowRow.value,\n                  base: meowRow.base,\n                  user: meowRow.user,\n                })}\\n`)\n                // volatile 表单认可的字段集=写入白名单的根；homeDir 在不在一看便知\n                const schemaObj = meowRow.schema as Record<string, unknown> | undefined\n                const schemaKeys = schemaObj && typeof schemaObj === 'object' ? Object.keys(schemaObj) : null\n                appendFileSync(diagFile, `[${new Date().toISOString()}] meow schema: ${JSON.stringify({\n                  schemaKeys,\n                  homeDirDeclared: schemaKeys !== null && schemaKeys.includes('homeDir'),\n                  schemaFull: JSON.stringify(schemaObj).slice(0, 3000),\n                })}\\n`)\n              }\n            } catch (e) {\n              try {\n                appendFileSync(join(activeHomeDir(), 'settings-diag.log'), `describe dump err: ${String(e)}\\n`)\n              } catch {\n                /* 忽略 */\n              }\n            }\n          }\n          dumpDescribe()\n          setTimeout(dumpDescribe, 5000)\n        }\n      } catch {\n        /* dump 失败忽略 */\n      }\n      // ── 0.1.7 宿主盲区补丁（2026-09-25 radio 冻结案）────────────────────────\n      // 0.1.7 的 SettingsForms（无 installSection/register）有三处盲区：\n      // ① write 只落盘+发 document-updated，**从不重载 entry**——describe 的 value\n      //    恒为 entry 启动时的解析值（entry.fiber.config），user 层（override）却是\n      //    新鲜的。设置页 radio（只认已保存镜像值）因此永远停在旧位置；bool/num/str\n      //    靠「保存后保留 draft」掩盖了同一冻结（实车 value=user=plugin-root vs\n      //    user=default 分裂实证）。→ describe 壳：meow 行现场重算 value=base⊕user。\n      // ② installSection 缺席 → base 没有 homeDirPresets，radio 旁看不到实际路径。\n      //    → describe 壳顺手注入（只进 base 不进 value：client 只从 base 读预设，\n      //    value 要过 configForms 的 schema decode，未知键有 decode 失败风险）。\n      // ③ scope.watch 缺席 → onChange 热切换不触发，改 homeDir 只落库不切换。\n      //    → write 壳：meow-memory 写入成功后补跑 hotSwitchHomeDir（与 0.1.6\n      //    onChange 同语义；get 走 describe 壳的现场合并值，天然含最新 user 层）。\n      // 0.1.6（installSection 在）三条原生链路全在，一概不装。壳只动 meow 行、\n      // 其他命名空间原样透传；revision/raw 指纹不碰（edit 的写入围栏还要读它）。\n      // 壳装配失败退回现状（value 冻结但不崩）。\n      if (typeof settingsCtx.settings.installSection !== 'function') {\n        try {\n          const svcAny = settingsCtx.settings as unknown as Record<string, unknown>\n          const proto = Object.getPrototypeOf(svcAny) as Record<string, unknown>\n          if (proto !== null && typeof proto.describe === 'function' && proto.__meowValueRefresh !== true) {\n            proto.__meowValueRefresh = true\n            const rawDescribe = (proto.describe as (...args: unknown[]) => unknown).bind(svcAny)\n            proto.describe = (...args: unknown[]): unknown => {\n              const rows = rawDescribe(...args) as Array<Record<string, unknown>>\n              try {\n                if (Array.isArray(rows)) {\n                  const row = rows.find((r) => r?.ns === SETTINGS_NS) as\n                    | { base?: Record<string, unknown>; user?: Record<string, unknown>; value?: unknown }\n                    | undefined\n                  if (row !== undefined && row.base !== undefined && row.base !== null && typeof row.base === 'object') {\n                    // 幂等：行对象跨多次 describe 复用，必须先剥掉上次注入的 presets\n                    // 再合成，否则第二轮 value 就带上了未知键（decode 失败风险）。\n                    const cleanBase = { ...row.base }\n                    delete cleanBase.homeDirPresets\n                    row.base = { ...cleanBase, homeDirPresets: homeDirPresets() }\n                    row.value = mergeConfigLayer(cleanBase, row.user as Record<string, unknown> | undefined)\n                  }\n                }\n              } catch {\n                /* 修正失败退回宿主原值（冻结但不崩） */\n              }\n              return rows\n            }\n            // 0.1.7 的设置源 = describe 壳的现场合并值（base⊕user，含最新 user 层）：\n            // resolveConfig 等待与热切换都从这读，等价 0.1.6 的 scope.get()。\n            settingsGet = (): unknown => {\n              const rows = (svcAny.describe as (...args: unknown[]) => unknown)() as Array<Record<string, unknown>>\n              const row = Array.isArray(rows) ? rows.find((r) => r?.ns === SETTINGS_NS) : undefined\n              return row?.value\n            }\n            markSourceReady?.()\n          }\n          if (proto !== null && typeof proto.write === 'function' && proto.__meowWriteHook !== true) {\n            proto.__meowWriteHook = true\n            const rawWriteHooked = (proto.write as (...args: unknown[]) => unknown).bind(svcAny)\n            proto.write = (...args: unknown[]): unknown => {\n              const result = rawWriteHooked(...args)\n              if (result instanceof Promise) {\n                return result.then((v: unknown) => {\n                  if (String(args[0]) === SETTINGS_NS) {\n                    ctx.logger.info('meow-memory: 配置已通过设置页更新（重载/重启插件后生效）')\n                    hotSwitchHomeDir(ctx, config, settingsGet)\n                    // promptLang 热字段刷新（issue #26）——0.1.7 无 installSection，\n                    // 这层 write 壳就是 onChange 的等位出口。\n                    refreshPromptLang()\n                  }\n                  return v\n                })\n              }\n              return result\n            }\n          }\n        } catch {\n          /* 盲区补丁装配失败：退回现状（value 冻结），不影响插件启动 */\n        }\n      }\n      installSettingsSectionCompat(settingsCtx, ctx, SETTINGS_NS, z.dict(z.any()), settingsBase, {\n        validate: (value: unknown): void => {\n          validateConfigUserLayer(value)\n        },\n        setSource: (get: () => unknown): void => {\n          settingsGet = get\n          markSourceReady?.() // 回填即就绪：唤醒下面的有界等待\n        },\n        onChange: (): void => {\n          ctx.logger.info('meow-memory: 配置已通过设置页更新（重载/重启插件后生效）')\n          // homeDir 热切换（用户拍板 2026-09-24：保存后立即生效，无需重启）——\n          // 全局目录消费点全是轻量读写（日志追加/小 JSON/按需读覆盖层），切模块级\n          // 状态口即可，dsh 主进程不重启、插件不重载、在跑会话无感知。\n          hotSwitchHomeDir(ctx, config, settingsGet)\n          // promptLang 热字段刷新（issue #26）：运行时 T() 文案随活配置切换；工具\n          // 描述与 system prompt 手册段在注册期定型，保持启动语言直到重载。\n          refreshPromptLang()\n        },\n      })\n    })\n    sourceWaitArmed = true // inject 已受理才值得等；ctx.inject 不存在时走 catch，不必等\n  } catch (e) {\n    // 设置服务未装配（别的 profile）不挡插件本体：config 退回 patch 层。\n    const msg = `meow-memory: 设置命名空间注册失败（标签页不可用，配置走 patch 层）：${e instanceof Error ? (e.stack ?? e.message) : String(e)}`\n    ctx.logger.warn(msg)\n    try {\n      const regErrFile = join(activeHomeDir(), 'settings-register-error.log')\n      mkdirSync(dirname(regErrFile), { recursive: true })\n      appendFileSync(regErrFile, `[${new Date().toISOString()}] ${msg}\\n`)\n    } catch {\n      /* 留痕失败忽略 */\n    }\n  }\n  // ── 服务端设置域诊断（0.1.7 写入排障，2026-09-25）：0.1.7 宿主对拒写静默、\n  // typert 信封剥 message——从宿主 configEditor 侧直接取证：entries 的 id/归属\n  // 节点/fiber 状态/Config 挂载，落 settings-diag.log。0.1.6 无此服务 → inject\n  // 挂起不回调，天然跳过。诊断失败绝不影响插件启动。\n  try {\n    ctx.inject(['configEditor'], (ce: {\n      entries: () => Array<{ options?: { id?: unknown }; fiber?: { state?: unknown; runtime?: unknown }; parent?: { tree?: { ctx?: { fiber?: { entry?: { id?: unknown } } } } } }>\n    }) => {\n      try {\n        const rows = ce.entries().map((entry) => ({\n          id: entry.options?.id,\n          state: entry.fiber?.state,\n          parent: entry.parent?.tree?.ctx?.fiber?.entry?.id ?? null,\n          hasConfig: entry.fiber?.runtime !== undefined && 'Config' in (entry.fiber.runtime as object),\n        }))\n        const diagFile = join(activeHomeDir(), 'settings-diag.log')\n        mkdirSync(dirname(diagFile), { recursive: true })\n        appendFileSync(diagFile, `[${new Date().toISOString()}] configEditor entries: ${JSON.stringify(rows)}\\n`)\n      } catch {\n        /* 诊断失败忽略 */\n      }\n    })\n  } catch {\n    /* 无 configEditor 服务（0.1.6）：跳过 */\n  }\n  // ── 宿主 write 异常落盘（同上排障）：0.1.7 的 settings 服务（SettingsForms）对\n  // write 抛错只回 code 不回 message——在同进程内给原型方法包一层取证壳，把原始\n  // 异常（含 message/栈，栈可定位 configEditor 内具体抛点）原样落盘。仅加日志不改\n  // 行为；settings 服务不存在（0.1.6 老链/未装配）时静默跳过。\n  try {\n    const settingsSvc = (ctx as unknown as { get?: (name: string) => unknown }).get?.('settings') as\n      | { write?: (...args: unknown[]) => unknown }\n      | undefined\n    const proto = settingsSvc !== undefined ? Object.getPrototypeOf(settingsSvc) as { write?: (...args: unknown[]) => unknown; __writeProbe?: boolean } : undefined\n    if (proto !== undefined && typeof proto.write === 'function' && proto.__writeProbe !== true) {\n      proto.__writeProbe = true\n      const rawWrite = proto.write.bind(settingsSvc)\n      proto.write = (...args: unknown[]) => {\n        const result = rawWrite(...args)\n        if (result instanceof Promise) {\n          return result.catch((e: unknown) => {\n            try {\n              const diagFile = join(activeHomeDir(), 'settings-diag.log')\n              mkdirSync(dirname(diagFile), { recursive: true })\n              appendFileSync(diagFile, `[${new Date().toISOString()}] write(ns=${String(args[0])}) rejected: ${e instanceof Error ? `${e.message}\\n${e.stack ?? ''}` : String(e)}\\n`)\n            } catch {\n              /* 取证失败忽略 */\n            }\n            throw e\n          })\n        }\n        return result\n      }\n    }\n  } catch {\n    /* 探针装配失败不影响启动 */\n  }\n  // 有界等待设置源就绪（issue #21）：真机上回调一个微任务内就跑完，不会真的等到上限；\n  // 服务缺失/注册失败时最多等 SETTINGS_SOURCE_WAIT_MS 就继续，绝不挂起。\n  if (sourceWaitArmed) {\n    await Promise.race([\n      sourceReady,\n      new Promise<void>((resolve) => { setTimeout(resolve, SETTINGS_SOURCE_WAIT_MS) }),\n    ])\n  }\n  const merged = mergeConfigLayer(config, settingsGet?.() as Record<string, unknown> | undefined)\n  // 活配置（issue #26）：热字段 getter 化——settings 命名空间晚于有界等待就绪时，\n  // 注册期字段（projectDir/homeDir/enabled/delegate）按 patch 层默认值生效（本次\n  // 启动内不纠正），运行时反复读取的热字段（注入/反思/dream 全系）在命名空间就绪\n  // 后的下一次读取自动纠正，不再需要重启。\n  const readLiveConfig = liveConfigReader(config, () => settingsGet?.() as Record<string, unknown> | undefined, SETTINGS_SOURCE_WAIT_MS)\n  const resolved = applyLiveConfig(resolveConfig(merged), readLiveConfig)\n  resolvedView = resolved\n  if (sourceWaitArmed && settingsGet === undefined) {\n    ctx.logger.warn('meow-memory: settings 服务在有界等待内未就绪——注册期字段本次启动按 patch 层默认值生效（需重载纠正）；热字段（注入/反思/dream）会在命名空间就绪后自动纠正（issue #26）')\n  }\n  // ── 记忆门控（issue #38/#28）───────────────────────────────────────────────\n  // 工作区停用（#28）：disabledWorkspaces 名单（cwd 归一匹配）= 硬开关，读/整理/写\n  // 全拒（含手动 /dream）。窗口级三档（#38）写 dream_skip 表：skip_dream（跳过整理）\n  // / skip_inject（停止读入）/ skip_write（停止写入，整理轮豁免——写入档只管普通轮）。\n  const workspaceDisabled = (ws: string): boolean => workspaceDisabledMatch(readLiveConfig().disabledWorkspaces, ws)\n  const memoryReadOff = (ws: string, sid: string): boolean => {\n    if (workspaceDisabled(ws)) return true\n    if (!existsSync(memoryDbPath(ws, resolved.projectDir))) return false\n    try {\n      return getDb(ws, resolved.projectDir).getMemoryScope(sid).inject\n    } catch {\n      return false // 库损坏按未停用处理：fail-open 与其余路径同风格\n    }\n  }\n  // ── 全局目录解析+切换（含首迁/回迁）：必须先于 sweep/loadWindowIndex——它们吃新目录。\n  // disabled 检查之前执行：插件停用时配置变更也要生效（switchHomeDir 幂等，重复启动无害）。\n  logHomeDirSwitch(ctx, switchHomeDir(resolveHomeDir(resolved.homeDir)))\n  // 诊断（issue #26）：把「设置源是否赶上」与关键解析值落到启动日志——配置不生效类\n  // 报告先看这一行：sourceReady=否 即冷启动竞态（settings 服务晚于等待上限就绪）。\n  ctx.logger.info(`meow-memory: config resolved (sourceReady=${settingsGet !== undefined}, enabled=${resolved.enabled}, dream.enabled=${resolved.dream?.enabled ?? 'default'}, promptLang=${resolved.promptLang ?? 'zh'}, projectDir=${resolved.projectDir ?? '.dsh-meow'})`)\n  if (!resolved.enabled) {\n    ctx.logger.info('meow-memory: disabled by config')\n    return\n  }\n  // prompt 语言（实例常量）：setPromptLang 一次，loader/bm25 内部取用——链路零透传。\n  // 必须先于工具注册（tools.md 描述也吃这个语言）。未配置时运行时兜底 zh。\n  setPromptLang(resolved.promptLang ?? 'zh')\n  applyCount++\n  perf(`apply #${applyCount} pid=${process.pid}`)\n  const sweptHome = sweepHomeLogs()\n  if (sweptHome.swept.length > 0 || sweptHome.rotated) {\n    perf(`home-log sweep: ${sweptHome.swept.join(',') || '-'}${sweptHome.rotated ? ' +perf.log->old' : ''}`)\n  }\n  loadWindowIndex(resolved.projectDir) // 恢复窗口索引（热重载/重启后旧窗口不失联）\n\n  // 工作区记忆库信任门（#64）：注册表住在全局目录（仓库作者碰不到）。先播种\n  // window-index.json 里出现过的工作区（升级前本机实际打开过 = 已知可信，老用户\n  // 零摩擦），再启用门——此后新遇到的「非本机创建 .dsh-meow」一律未信任（注入/\n  // 检索/整理/写入全停，判据与登记时机见 src/trust.ts），/meow-trust 恢复。建库\n  // 时刻的登记在 getDb（db.ts）；loadWindowIndex 只打开已存在的库、不会误建库。\n  enableWorkspaceTrust()\n  const seededTrust = seedTrustedWorkspaces()\n  if (seededTrust.listed > 0) {\n    ctx.logger.info(`meow-memory: workspace trust gate on (seeded ${seededTrust.trusted}/${seededTrust.listed} from window-index)`)\n  }\n\n  // v0 会话一次性迁移（issue #13）：标记未迁移时体检全部会话并把 source.memory 搬进\n  // sections.__meta__，完成后置位 .dsh-meow/migrate-v0-state.json，此后启动直接跳过。\n  // fire-and-forget：绝不阻塞 dsh 启动；单文件失败只记日志（用户拍板 2026-09-10）。\n  void ensureV0SessionsMigrated(resolved.projectDir, (m) => ctx.logger.info(m)).catch((e: unknown) => {\n    ctx.logger.warn(`meow-memory: migrate-v0 failed (non-fatal): ${e instanceof Error ? e.message : String(e)}`)\n  })\n  perf(`window-index restored ${windowIndex.size} windows`)\n\n  // 工具注册 + disposer 收集：热重载/重启时旧 fiber 的工具必须注销，\n  // 否则新 apply 重复注册同名工具会抛异常 → apply 中断 → 工具/手册/pre-step 全失效\n  // （真机踩坑 2026-08-17：04:35 配置变更触发的 reload 后首轮注入消失）。\n  const toolDisposers: Array<() => void> = []\n  // 记忆门控判定器（issue #38/#28）：工具层经 setMemoryToolGate 读取（活配置闭包）。\n  // 写档的整理轮豁免 = isPluginTurn（dream/reflect 指令轮的标记，本文件事件链维护）。\n  setMemoryToolGate({\n    refuseRead: (ws, sid) => {\n      if (workspaceDisabled(ws)) return '记忆对该工作区已停用（disabledWorkspaces 名单）：memory 工具不可用，请更换工作区或调整配置。'\n      if (isUntrustedMemoryWorkspace(ws)) return '此工作区自带未信任的外部记忆库（.dsh-meow 非本机创建，#64）：memory 工具已暂停。确认这是自己的项目，请让用户执行 /meow-trust 恢复。'\n      if (sid === null || !existsSync(memoryDbPath(ws, resolved.projectDir))) return null\n      return getDb(ws, resolved.projectDir).getMemoryScope(sid).inject ? '此窗口已停止读入记忆（记忆参与开关）：注入与检索均已关闭。' : null\n    },\n    refuseWrite: (ws, sid) => {\n      if (workspaceDisabled(ws)) return '记忆对该工作区已停用（disabledWorkspaces 名单）：写入被拒绝。'\n      if (isUntrustedMemoryWorkspace(ws)) return '此工作区自带未信任的外部记忆库（.dsh-meow 非本机创建，#64）：写入被拒绝。确认这是自己的项目，请让用户执行 /meow-trust 恢复。'\n      if (sid === null || !existsSync(memoryDbPath(ws, resolved.projectDir))) return null\n      if (isPluginTurn.get(sid) === true) return null // 整理轮豁免：整理轮写入跟随整理档（#38 联动）\n      return getDb(ws, resolved.projectDir).getMemoryScope(sid).write ? '此窗口已停止写入记忆（记忆参与开关）。' : null\n    },\n  })\n  registerMemoryTools((t) => {\n    const dispose = ctx.tools.register(t)\n    if (typeof dispose === 'function') toolDisposers.push(dispose)\n  }, resolved.projectDir)\n  // 会话列表\"已 dream\"小月牙信号（用户拍板 2026-08-19）：dream 开始推 dreaming、\n  // 完成推 dreamed、有新活动推 active。\n  const broadcast = new DreamStateBroadcast(ctx.logger)\n  // dream 收尾钩子（#37 增量②）：开启备份时把 memory.db 快照轮转到 .bak（mtime 判\n  // 增量幂等；VACUUM INTO 失败静默——备份是兜底措施，绝不影响主流程）。\n  const signalDreamState = (sessionId: string, state: 'dreaming' | 'dreamed' | 'active'): void => {\n    broadcast.broadcast(sessionId, state)\n    if (state === 'dreamed' && resolved.backup.enabled) {\n      const wsB = windowIndex.get(sessionId)\n      if (wsB !== undefined) {\n        try {\n          if (backupMemoryDb(wsB, resolved.projectDir)) ctx.logger.info(`meow-memory: memory.db 已备份（dream 收尾触发，${shortSessionId(sessionId)}）`)\n        } catch { /* 备份失败不影响主流程 */ }\n      }\n    }\n  }\n  const disposeDreamTool = ctx.tools.register(dreamTool(ctx, resolved.projectDir, signalDreamState, () => resolved.dream.rulesReviewDays, workspaceDisabled, isUntrustedMemoryWorkspace))\n  if (typeof disposeDreamTool === 'function') toolDisposers.push(disposeDreamTool)\n  ctx.logger.info('meow-memory: memory_remember/search/read/update + memory_dream registered')\n\n  // 记忆系统手册挂进 system prompt（静态文本 → KV 缓存友好；order 130 = 工具指南区间末尾，\n  // 与各 tool:* 说明（100–116）列在一起，不独占开头）。\n  // systemPrompt 是可选服务（别的 profile 可能没加载 dsh-system-prompt），且 fiber 并发\n  // 启动时可能晚于本插件就绪（与 webServer 路由同款竞态）→ 立即试；未就绪每 1s 重试\n  // （最多 20 次，同 tryRegisterDreamCommand 模式）。\n  // disposer 必须接住（0.1.2 / 0.1.3+ 的 section() 都返回 cordis effect disposer）：\n  // 热重载时 fiber dispose 先注销旧段，否则同名重复 insert 抛错会打断整个 apply。\n  // 双版本兼容：不假设返回值形状，typeof 校验后才登记（对旧版零影响）。\n  let guideRegistered = false\n  let guideTimer = 0\n  const tryRegisterGuideSection = (attempt: number): void => {\n    if (guideRegistered) return\n    const svc = (ctx as { get?: (name: string) => unknown }).get?.('systemPrompt') as\n      | { section?: (section: { name: string; order: number; text: string }) => unknown }\n      | undefined\n    if (svc === undefined || typeof svc.section !== 'function') {\n      if (attempt < 20) {\n        guideTimer = setTimeout(() => tryRegisterGuideSection(attempt + 1), 1000) as unknown as number\n      } else {\n        ctx.logger.warn('meow-memory: systemPrompt 服务 20s 内未就绪，记忆手册未挂进 system prompt（memory_* 工具不受影响）')\n      }\n      return\n    }\n    try {\n      const dispose = svc.section({ name: 'meow-memory:guide', order: 130, text: getMemoryGuide() })\n      guideRegistered = true\n      if (typeof dispose === 'function') toolDisposers.push(dispose)\n      ctx.logger.info('meow-memory: guide section registered into system prompt')\n    } catch (e) {\n      // 重复名冲突等注册错误：重试无意义（旧代未 dispose 时再试还是撞），记日志放弃。\n      ctx.logger.warn(`meow-memory: guide section 注册失败（记忆手册缺失，不影响其余功能）: ${e instanceof Error ? e.message : String(e)}`)\n      guideRegistered = true\n    }\n  }\n  tryRegisterGuideSection(0)\n  toolDisposers.push(() => clearTimeout(guideTimer))\n\n  // 窗口表：只处理低频事件类型（流式 assistant/chunk 每块一个事件，绝不逐块写库）。\n  // 节流：同一窗口 5 秒内最多落库一次（内存记 lastWrite，事件循环零阻塞）。\n  // 插件注入轮（反思/dream 的 steer 消息轮）内的事件不刷新 last_event_time：\n  // dream 轮自身事件会推后窗口活跃度 → 收尾后 last_dream_time < last_event_time\n  // → 窗口永远\"需要 dream\"，配合中断/多进程场景造成反复 dream。\n  const lastWindowWrite = new Map<string, number>()\n  const isPluginTurn = new Map<string, boolean>() // sid -> 本 turn 是否为 meow-memory 插件轮\n  const turnHadMessage = new Map<string, boolean>() // sid -> 本 turn 是否出现过任何 user/message（#36 裸轮判定：dream 任务被 claim 后未及落盘就装配崩溃的轮，全程零消息）\n  ctx.on('session/event', (session: { id?: string; header?: SessionHeaderLike }, event: { time?: number; type?: string; data?: unknown }) => {\n    perfEvent()\n    noteActivity()\n    const t = event?.type\n    const sid = session?.id\n    const cwd = session?.header?.cwd\n    // 压缩信号：会话历史被压缩（内容已不在上下文）→ 释放本会话已见记录，\n    // 允许之前注入/检索过的记忆被再次命中提取。\n    if (t === 'compaction/summary' || t === 'compaction/start') {\n      if (typeof sid === 'string' && typeof cwd === 'string') {\n        releaseSeen(cwd, sid, resolved.projectDir)\n        ctx.logger.info(`meow-memory: compaction signal, released seen memory for session ${shortSessionId(sid)}`)\n      }\n      return\n    }\n    // 压缩成功落地（compaction/end 无 error = 表层已替换，v0.21.0）：置重注入待办——\n    // 下一个含真实用户消息的 pre-step 重新注入「长期记忆快照 + 本会话查阅过的项目全景」。\n    // /compact 手动压缩与 token 压力自动压缩走同一生命周期，都覆盖。\n    // 带 error 的 end = 压缩失败、表层未变（原上下文还在），不打标记。\n    if (t === 'compaction/end') {\n      const err = (event.data as { error?: unknown } | undefined)?.error\n      if ((err === undefined || err === null || err === '') && typeof sid === 'string' && typeof cwd === 'string') {\n        markReinjectPending(cwd, sid, resolved.projectDir)\n        ctx.logger.info(`meow-memory: compaction finished, memory re-injection armed for session ${shortSessionId(sid)}`)\n      }\n      return\n    }\n    if (typeof sid === 'string') {\n      if (t === 'turn/start') {\n        isPluginTurn.set(sid, false) // 新轮重置\n        turnHadMessage.set(sid, false) // 新轮重置（#36 裸轮判定基线）\n        return\n      }\n      if (t === 'user/message') {\n        turnHadMessage.set(sid, true) // 任何来源的消息都算（裸轮 = 全程零消息）\n        const data = event.data as {\n          source?: { kind?: string; plugin?: string; form?: string }\n          content?: Array<{ type?: string; text?: string }>\n        } | undefined\n        const src = data?.source\n        // 插件自身消息识别（2026-09-05 扩大：原只认 source.kind='plugin'，漏掉两类——\n        // ①steer 模式 dream/reflect 指令消息（agent.steer 的 user 帧无 source，含\n        // [meow-memory-dream]/[meow-memory-reflect]）；②delegate 打点（session.append\n        // ('user/message') 无 source，含【记忆整理标记】等）——实证打点会 touchWindow\n        // 把 last_event_time 顶成 dream 时刻：掩盖真实活跃度，且 error 重试窗口被\n        // 反复刷新永不超 24h。用户亲手发的消息（source.kind='user'）绝不判 marker，\n        // 防引用标记文本误伤。命中 → 指令/打点：不 touchWindow 不刷新活跃度。\n        if (src?.kind !== 'user') {\n          const msgText = (data?.content ?? [])\n            .filter((b) => b.type === 'text' && typeof b.text === 'string')\n            .map((b) => b.text ?? '')\n            .join(' ')\n          if (\n            msgText.includes(REFLECT_MARKER) ||\n            msgText.includes(DREAM_MARKER) ||\n            msgText.includes(REFLECT_DELEGATE_MARKER) ||\n            msgText.includes(DREAM_DELEGATE_MARKER) ||\n            msgText.includes(REFLECT_DONE_DELEGATE_MARKER)\n          ) {\n            isPluginTurn.set(sid, true) // 反思/dream 指令轮或打点\n            return // 不刷新活跃度\n          }\n        }\n      }\n      // dream 轮失败即时处理（issue #36 建议二）：宿主的 agent/turn-stopping 只在\n      // 「某个 step 成功完成后」发射（dsh-agent-loop turn 循环内唯一发射点，且发射时\n      // 本轮 turn/end 还没落日志），首个 step 之前的失败（空 options 装配抛错、\n      // pre-step reject 等）永远走不到那里——turn-stopping 的 error 分支对这类失败是\n      // 死代码，租约只能等 6h 心跳封顶后被盖章（静默丢记忆）。turn/end 事件在宿主\n      // catch/finally 里必然落盘，用在这里兜底：\n      // ① 插件轮 error（消息标记已落盘的 dream/reflect 轮）→ handleMemoryTurnFailure；\n      // ② 「裸轮」error（本 turn 全程零 user/message）且有活跃 dream 租约 → 同样处理\n      //    （dream 任务被 claim 后未及落盘就装配崩溃的形状；窗口此刻非活跃使用场景，\n      //    误判代价仅为提前重试一次）。\n      if (t === 'turn/end' && (event.data as { reason?: { kind?: string } } | undefined)?.reason?.kind === 'error') {\n        const pluginTurn = isPluginTurn.get(sid) === true\n        const nakedTurn = turnHadMessage.get(sid) === false // turn/start 已见、其后零消息\n        if ((pluginTurn || nakedTurn) && typeof cwd === 'string' && existsSync(memoryDbPath(cwd, resolved.projectDir))) {\n          const outcome = handleMemoryTurnFailure(getDb(cwd, resolved.projectDir), sid, cwd, resolved.projectDir)\n          if (outcome !== 'none') broadcast.broadcast(sid, 'active') // 摘掉 dreaming 呼吸灯（重试/封存状态由后续 sweep 表达）\n        }\n      }\n      if (isPluginTurn.get(sid)) return // 插件轮内：不 touchWindow\n    }\n    if (t !== 'user/message' && t !== 'turn/end' && t !== 'assistant/message' && t !== 'tool/result') return\n    // 子代理会话不进窗口表/windowIndex：origin==='subagent'（dsh 权威标记，与注入链\n    // 同口径）。子代理的记忆活动按归属语义记父窗口名下，自身不是 dream 目标——否则\n    // dream fork 出的子代理会话也成待 dream 窗口，dream→再进表→再 dream 递归套娃\n    // （2026-09-05 真机实证 8fbc5d59→2f47c15b→63dad87b，depth 无限增长）。\n    // 压缩信号处理在上方，不受此 return 影响。\n    if (session?.header?.origin === 'subagent') return\n    if (typeof sid !== 'string' || typeof cwd !== 'string' || typeof event?.time !== 'number') return\n    const now = Date.now()\n    const last = lastWindowWrite.get(sid) ?? 0\n    if (now - last < 5000) return // 节流：5 秒内同窗口只写一次\n    lastWindowWrite.set(sid, now)\n    const db = getDb(cwd, resolved.projectDir)\n    db.touchWindow(sid, cwd, event.time)\n    // dream 状态信号：该会话有新活动 → 若曾 dream 过，推 active（去月亮；client 幂等忽略）。\n    const win = db.getWindow(sid)\n    if (win !== undefined && win.last_dream_time !== null) broadcast.broadcast(sid, 'active')\n    windowIndex.set(sid, cwd)\n    persistWindowIndex() // 窗口索引落盘（热重载/重启后恢复）\n  })\n\n  // 1) 注入：首轮快照（soul/user/设计原则/导引，仅一次）+ 命中链路（第二条起每条真实用户消息都跑）。\n  // 首轮判定（真机踩坑 2026-08-16）：不能看 decision.messages[0]——首条用户消息可能与\n  // 插件通知消息同批到达（如 user-approval 的 policy 变更通知，source.kind='plugin'），\n  // messages[0] 未必是用户消息。正确判定 = 本会话日志里还没有任何 user/message\n  // （harness 在 pre-step 之后才 append 当前消息，首条消息时日志必为空）+ 消息列表里\n  // 存在真实用户消息（source.kind === 'user'）。\n  // 首条消息：只注入长期记忆快照，绝不跑命中链路（用户拍板：命中从第二轮起）。\n  // 进程重启后恢复的会话：日志已有 user/message → 视为首轮已注入，只走命中链路。\n  const firstUserHandled = new Set<string>()\n  // 热路径 fail-open（2026-09-10）：pre-step 是 async 监听器，插件逻辑抛错会沿\n  // agent-loop 传播改变宿主 turn 的错误语义。包装器单独持有 next()——宿主 step\n  // 自身的错误原样上抛（abort 语义在内），只有本插件自己的注入/检索失败才吞掉\n  // （放弃本轮注入、放行原始 decision，与本插件其余路径的 fail-open 同风格）。\n  ctx.on('agent/pre-step', async ({ agent, messages, signal }, next) => {\n    const decision = await next()\n    try {\n      // preStepInject 内部把 decision 当透传黑盒（any）；出口 cast 回宿主形状。\n      return (await preStepInject({ agent, signal }, decision)) as typeof decision\n    } catch (e) {\n      try {\n        ctx.logger.warn(`meow-memory: pre-step 注入失败（fail-open 放行原始消息）: ${e instanceof Error ? e.message : String(e)}`)\n      } catch { /* 日志失败不阻塞 */ }\n      return decision\n    }\n  })\n\n  // decision 形状来自宿主事件映射，这里透传不重塑（内部只做 kind/messages 只读访问）。\n  const preStepInject = async ({ agent, signal }: { agent: any; signal: { aborted: boolean } }, decision: any): Promise<unknown> => {\n    const t0 = Date.now()\n    if (decision === undefined || decision.kind !== 'enter' || signal.aborted) return decision\n    if (decision.messages.length === 0) return decision\n    // 子代理不注入（origin === 'subagent'，dsh 权威标记）：它们的 prompt 由父代理提供\n    // （如 dsh-femo 的角色上下文）。注意不能只看 parentSession——GUI fork/续写的\n    // 主会话也有 parentSession（真机踩坑 2026-08-17：fca10feb 被误判为子代理导致注入全失效）。\n    if (agent.session.header.origin === 'subagent') return decision\n    registerLiveAgent(agent)\n    const sid = sessionIdOfAgent(agent)\n    const ws = workspaceOfAgent(agent)\n\n    // 真实用户消息（跳过插件通知等，source.kind='plugin' 的进不来）。\n    const userMsgs = decision.messages.filter((m: { source?: { kind?: string } }) => m.source?.kind === 'user')\n    if (userMsgs.length === 0) return decision // 工具轮/纯插件消息：不注入\n\n    // 外部记忆库信任门（#64）：.dsh-meow 非本机创建且未信任 → 全部记忆路径暂停\n    //（下方重注入/首轮快照/命中链都不会走到）。首个用户消息前插一次性说明（不\n    // 读库、不算注入），给出 /meow-trust 恢复方式。信任是活检查：/meow-trust 后\n    // 下一轮即恢复正常注入，无需重启。提示记账在全局注册表（工作区文件可预置，\n    // 不能当标记）。\n    if (ws !== null && isUntrustedMemoryWorkspace(ws)) {\n      if (!hasExternalNoticeShown(ws)) {\n        markExternalNoticeShown(ws)\n        try {\n          const notice = resolveSlotText('external-memory-notice')\n          const rewritten = [...decision.messages]\n          rewritten.splice(rewritten.indexOf(userMsgs[0]), 0, createMemoryNoticeMessage(notice))\n          ctx.logger.info('meow-memory: external memory library detected — paused until /meow-trust')\n          return { ...decision, messages: rewritten }\n        } catch {\n          /* 提示失败不阻塞：按无提示停用处理 */\n        }\n      }\n      return decision\n    }\n\n    // 记忆门控（issue #38/#28）：本窗口「停止读入」或工作区被配置停用 → 跳过全部\n    // 注入路径（重注入/首轮快照/引导/命中链）。读的入口统一在此封口。\n    if (ws !== null && memoryReadOff(ws, sid)) return decision\n\n    // 压缩重注入（v0.21.0）：compaction/end 成功后置位的待办——下一个含真实用户\n    // 消息的请求在消息前注入「长期记忆快照 + 本会话此前查阅过的项目全景」，然后清待办。\n    // 本轮不跑命中链路（等同新首轮：快照先行，命中从下一轮起）。待办置位但无可注入\n    // 内容（库空且项目全空）也一并清除，避免每个用户消息轮空转重查。\n    if (ws && isReinjectPending(ws, sid, resolved.projectDir)) {\n      const lastUser = userMsgs[userMsgs.length - 1]\n      const db = getDb(ws, resolved.projectDir)\n      const reinj = buildReinjection(db, ws, sid, readProjectQueried(ws, sid, resolved.projectDir), {\n        hitTopK: resolved.hitTopK,\n        titleMax: resolved.titleMax,\n      }, resolved.projectDir)\n      clearReinjectPending(ws, sid, resolved.projectDir)\n      if (reinj !== null) {\n        const rewritten = [...decision.messages]\n        rewritten.splice(rewritten.indexOf(lastUser), 0, createMemorySnapshotMessage(reinj.text, { kind: 'reinjection', ids: reinj.injectedIds }))\n        ctx.logger.info(`meow-memory: post-compaction memory re-injected (${reinj.text.length} chars)`)\n        return { ...decision, messages: rewritten }\n      }\n      return decision\n    }\n\n    // 首条用户消息（本进程内每个会话只判定一次）。\n    if (!firstUserHandled.has(sid)) {\n      firstUserHandled.add(sid)\n      let priorUser = 0\n      for (const e of sessionEventsOf(agent.session)) {\n        const evt = e as { type?: string; data?: { source?: { kind?: string } } }\n        if (evt?.type === 'user/message' && evt.data?.source?.kind === 'user') priorUser++\n      }\n      if (ws) {\n        try {\n          appendFileSync(join(ws, resolved.projectDir, 'dream-debug.log'), `[${new Date().toISOString()}] pre-step first pid=${process.pid} sid=${shortSessionId(sid)} priorUser=${priorUser} userMsgs=${userMsgs.length}\\n`)\n        } catch { /* 日志失败不阻塞 */ }\n      }\n      if (priorUser === 0) {\n        // 会话首条消息：只注入长期记忆快照，不跑命中链路。\n        if (ws) {\n          const firstUser = userMsgs[0]\n          const db = getDb(ws, resolved.projectDir)\n          if (resolved.autoMigrate && existsSync(join(ws, resolved.projectDir, 'PROJECT.md'))) {\n            const n = migrateLegacy(db, ws, resolved.projectDir)\n            if (n !== null) ctx.logger.info(`meow-memory: migrated legacy PROJECT.md → SQLite (${n} entries)`)\n          }\n          const firstText = firstUser.content\n            .filter((b: { type?: string; text?: string }) => b.type === 'text' && typeof b.text === 'string')\n            .map((b: { text?: string }) => b.text ?? '')\n            .join(' ')\n          const injected = buildInjection(db, ws, sid, firstText, {\n            hitTopK: resolved.hitTopK,\n            titleMax: resolved.titleMax,\n          }, resolved.projectDir)\n          if (injected) {\n            const rewritten = [...decision.messages]\n            rewritten.splice(rewritten.indexOf(firstUser), 0, createMemorySnapshotMessage(injected.text, { kind: 'initial', ids: injected.injectedIds }))\n            ctx.logger.info(`meow-memory: inserted memory snapshot (${injected.text.length} chars) before first user message`)\n            return { ...decision, messages: rewritten }\n          }\n        }\n        // 首建提示（issue #37 增量①）：记忆库还是空的（≈刚创建）时，随首轮注入一条\n        // 独立通知——库在工作区隐藏目录、误删不 recover，memory_home 可迁出、backup\n        // 可兜底。记账 = accessed 痕迹（per-session 至多一次；库有记忆后 isFresh=false\n        // 永久短路）。fail-open：任何失败只跳过提示。\n        try {\n          if (getDb(ws, resolved.projectDir).isFresh() && !readSeen(ws, sid, resolved.projectDir).has(FIRST_CREATE_NOTICE_SEEN_ID)) {\n            const firstUser2 = userMsgs[0]\n            markAccessed(ws, sid, [FIRST_CREATE_NOTICE_SEEN_ID], resolved.projectDir)\n            const notice = resolveSlotText('first-create-notice', { dbPath: join(ws, resolved.projectDir, 'memory.db'), homePath: homedir() })\n            const rewritten = [...decision.messages]\n            rewritten.splice(rewritten.indexOf(firstUser2), 0, createMemoryNoticeMessage(notice))\n            ctx.logger.info('meow-memory: first-create notice injected (fresh memory.db)')\n            return { ...decision, messages: rewritten }\n          }\n        } catch { /* 提示失败不阻塞注入链 */ }\n        return decision // 首条消息：不跑命中链路（首轮只注入长期记忆）\n      }\n      // 恢复的会话（日志已有历史消息）：首轮快照由上个进程注入过，只走命中链路。\n    }\n\n    // 首次设置引导（v0.19.0）：promptLang 未配置时，在插件生效后的第一条含真实用户\n    // 消息的请求前注入设置任务（AI 只依据用户消息判断语言 → 改 patch → 热重载）。\n    // 记账 = sessions/<id>.json 的 accessed 痕迹 '__welcomeGuide__'（per-session 至多一次；\n    // accessed 不被 releaseSeen 清除，上下文压缩后不会重注入；配置生效后 promptLang\n    // 有值 → 本分支永久短路）。首轮消息不进这里（首轮分支上方已 return——装插件场景\n    // 会话早已过首轮，且首轮用户往往还没好好说话，判断语言不可靠）。\n    // 作为独立的插件通知消息注入，不改写人类 user 消息。\n    if (resolved.promptLang === undefined && ws) {\n      const seen = readSeen(ws, sid, resolved.projectDir)\n      if (!seen.has(WELCOME_GUIDE_SEEN_ID)) {\n        const lastUser = [...decision.messages].reverse().find((m: { source?: { kind?: string } }) => m.source?.kind === 'user')\n        if (lastUser !== undefined) {\n          markAccessed(ws, sid, [WELCOME_GUIDE_SEEN_ID], resolved.projectDir)\n          const guide = resolveSlotText('welcome-guide', { homePath: homedir() })\n          const rewritten = [...decision.messages]\n          rewritten.splice(rewritten.indexOf(lastUser), 0, createMemoryNoticeMessage(guide))\n          ctx.logger.info('meow-memory: first-run lang guide injected as independent notice (promptLang unset)')\n          return { ...decision, messages: rewritten }\n        }\n      }\n    }\n\n    // 命中链路（从第二条用户消息起）：每条含真实用户消息的请求都跑关键词检索命中\n    // （top-K）。工具轮/子步骤的请求消息不含真实用户消息 → 不触发；\n    // 命中 id 记入已见，不再重复。\n    if (ws) {\n      const lastUser = [...decision.messages].reverse().find((m: { source?: { kind?: string } }) => m.source?.kind === 'user')\n      if (lastUser !== undefined) {\n        const text = lastUser.content\n          .filter((b: { type?: string; text?: string }) => b.type === 'text' && typeof b.text === 'string')\n          .map((b: { text?: string }) => b.text ?? '')\n          .join(' ')\n        const db = getDb(ws, resolved.projectDir)\n        const hit = buildHitInjection(db, ws, sid, text, {\n          hitTopK: resolved.hitTopK,\n          titleMax: resolved.titleMax,\n        }, resolved.projectDir)\n        try {\n          appendFileSync(join(ws, resolved.projectDir, 'dream-debug.log'), `[${new Date().toISOString()}] hit-chain pid=${process.pid} sid=${shortSessionId(sid)} textLen=${text.length} hit=${hit === null ? 'null' : 'yes'}\\n`)\n        } catch { /* 日志失败不阻塞 */ }\n        if (hit !== null) {\n          const rewritten = [...decision.messages]\n          rewritten.splice(rewritten.indexOf(lastUser), 0, createMemorySnapshotMessage(hit.text, { kind: 'hit', ids: hit.injectedIds }))\n          return { ...decision, messages: rewritten }\n        }\n      }\n      if (Date.now() - t0 > 10) perf(`pre-step hit ${Date.now() - t0}ms sid=${shortSessionId(sid)}`) // 热路径超 10ms 有鬼\n    }\n    return decision\n  }\n\n  // 2) turn 结束：dream 轮推进 / 自动反思。\n  // 同 pre-step 的 fail-open：同步监听器里抛错（如 advanceDream→steer、DB 读）不允许\n  // 改变宿主 turn 收尾语义，吞掉记日志（dream 租约有过期自愈兜底，不会因此卡死）。\n  // 反思排队判重（issue #19）：sendMemoryTurn 走 followup 把反思排进「下一轮」，它不在\n  // 本 turn 的事件流里，于是 scanTurn().sawReflect 在本 turn 收尾期间恒为 false。0.26.0\n  // 起 turn-stopping 在一次收尾窗口内会触发多次（每个 step 收尾、被其它插件 steer 续命\n  // 后再触发），每次都再排一条，排 N 条就被后面 N 个 turn 依次消费——真机实测同一反思\n  // 连发 4 次，每次都要模型回一句「无需记忆」，白烧 token。\n  // 判重键取宿主事件载荷里的 turn（agent/turn-stopping: { agent, turn, signal }）：同一\n  // turn 只排一条；反思轮真正跑起来后 sawReflect=true 自然清账；换 turn 键值不同自动放行\n  // ——不会像布尔闩那样在「排了却没跑」时永久卡死。载荷无 turn 的宿主退回旧行为。\n  const reflectQueuedTurn = new Map<string, number>()\n  const MAX_REFLECT_TRACKED = 512\n\n  ctx.on('agent/turn-stopping', ({ agent, turn }) => {\n    try {\n      turnStoppingCore(agent, turn)\n    } catch (e) {\n      try {\n        ctx.logger.warn(`meow-memory: turn-stopping 处理失败（已忽略）: ${e instanceof Error ? e.message : String(e)}`)\n      } catch { /* 日志失败不阻塞 */ }\n    }\n  })\n\n  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- agent 形状来自宿主事件映射，透传不重塑\n  const turnStoppingCore = (agent: any, turn?: number): void => {\n    const t0 = Date.now()\n    if (agent.session.header.origin === 'subagent') return // 子代理不参与（origin 权威判定）\n    registerLiveAgent(agent)\n    const endReason = lastTurnEndReason(sessionEventsOf(agent.session))\n    const dreamTurn = wasDreamTurn(sessionEventsOf(agent.session))\n    const wsTs = workspaceOfAgent(agent)\n    const sidTs = sessionIdOfAgent(agent)\n    if (wsTs) {\n      try {\n        appendFileSync(join(wsTs, resolved.projectDir, 'dream-debug.log'), `[${new Date().toISOString()}] turn-stopping pid=${process.pid} sid=${shortSessionId(sidTs)} reason=${endReason ?? 'none'} wasDream=${dreamTurn}\\n`)\n      } catch { /* 日志失败不阻塞 */ }\n    }\n    // 用户按停止（aborted/interrupted）：不反思、不推进下一组；但 dream 轮必须立即收尾，\n    // 否则 DB 租约残留，窗口要等租约过期（30min）才能再 dream。\n    if (endReason === 'aborted' || endReason === 'interrupted') {\n      if (dreamTurn) abortDream(agent, resolved.projectDir, signalDreamState)\n      return\n    }\n    if (dreamTurn) {\n      if (endReason === 'error') {\n        // steer 模式 dream 轮执行失败（LLM/网络瞬态故障，非用户中止）：释放租约不封存，\n        // 下个检查周期自动重试（与 delegate 路径 done 回调的 error 分支同语义，\n        // 2026-09-05 教训：封存会让一次断网永久吞掉窗口的 dream）。\n        try {\n          if (wsTs && sidTs) getDb(wsTs, resolved.projectDir).releaseDream(sidTs)\n        } catch { /* 释放失败不阻塞（租约 30min 过期自愈兜底） */ }\n        return\n      }\n      advanceDream(agent, resolved.projectDir, signalDreamState, resolved.dream.rulesReviewDays) // dream 轮：推进下一组或收尾（含孤儿收尾）\n      return\n    }\n\n    // 窗口/工作区整理门控（issue #38/#28）：「跳过整理」或工作区停用 → 自动反思一并\n    // 挡下（手动 /dream 不受限，手动=明确意愿）。dream 轮推进在上方分支已处理，不受此守卫影响。\n    // 外部记忆库信任门（#64）：未信任的工作区连库都不该读——自动反思同挡。\n    if (wsTs !== null) {\n      try {\n        if (isUntrustedMemoryWorkspace(wsTs) || workspaceDisabled(wsTs) || (existsSync(memoryDbPath(wsTs, resolved.projectDir)) && getDb(wsTs, resolved.projectDir).getMemoryScope(sidTs).dream)) return\n      } catch {\n        /* 门控读失败：放行（fail-open 同风格） */\n      }\n    }\n    if (!resolved.reflect) return\n    const ws = workspaceOfAgent(agent)\n    if (!ws) return\n    const { sawToolCall, lastToolName, sawReflect, turnText } = scanTurn(sessionEventsOf(agent.session))\n    if (sawReflect) {\n      reflectQueuedTurn.delete(sidTs) // 本 turn 已反思过（含反思轮自身结束）：排队痕迹用完即清\n      return\n    }\n    // 本 turn 已经排过一条（followup 排在 next-turn，事件流里还看不见）→ 不再重复排（issue #19）\n    if (turn !== undefined && reflectQueuedTurn.get(sidTs) === turn) return\n    if (!sawToolCall) return // 纯聊天轮，不反思\n    if (lastToolName !== undefined && lastToolName.startsWith('memory_')) return // 已主动记忆\n    if (consecutiveToolSteps(sessionEventsOf(agent.session)) < resolved.reflectTurns) return // 单任务内连续工具 step 不足\n    const message = buildReflectMessage(ws, turnText, resolved.projectDir)\n    // 反思任务送主会话独立新轮（v0.24 拍板进主会话；2026-09-10 起走 followup 另起\n    // 一轮——steer 延续同 turn 会把 AI 的工作汇报顶成中间步骤，见 sendMemoryTurn）。\n    // 换模型由下方 agent/request waterfall 承接——本 turn 带 REFLECT_MARKER 时自动覆盖模型。\n    if (sendMemoryTurn(agent, message, ws, resolved.projectDir, `reflect sid=${shortSessionId(sidTs)}`)) {\n      if (turn !== undefined) {\n        reflectQueuedTurn.set(sidTs, turn)\n        // 进程级 Map 兜底上限：只保最近 MAX_REFLECT_TRACKED 个会话（Map 保留插入序）。\n        while (reflectQueuedTurn.size > MAX_REFLECT_TRACKED) {\n          const oldest = reflectQueuedTurn.keys().next().value\n          if (oldest === undefined) break\n          reflectQueuedTurn.delete(oldest)\n        }\n      }\n      ctx.logger.info(`meow-memory: reflect sent as standalone turn after ${resolved.reflectTurns}+ tool turns`)\n    } else {\n      ctx.logger.warn('meow-memory: reflect 发送失败（本轮不反思，下轮重试）')\n    }\n    if (Date.now() - t0 > 20) perf(`turn-stopping slow ${Date.now() - t0}ms`)\n  }\n\n  // 2.5) 整理任务换模型（agent/request waterfall，dsh 官方单请求模型覆盖扩展点）：\n  //   配置了 delegate.model 时，本会话「反思轮/梦境轮」的请求把 provider/model 覆盖为\n  //   配置值，其余请求（正常对话/工具轮）原样放行——触发前换上、轮次结束自动换回，\n  //   无状态：判定=当前 turn 的指令消息是否带 [meow-memory-reflect]/[meow-memory-dream]\n  //   文本标记（steer 指令消息在请求前已落 log，agent-loop L554 实证；与 wasDreamTurn/\n  //   isPluginTurn 同口径）。\n  // #71：覆盖只作用于单个请求，但宿主把「本次请求实际路由」写进 request/header，其\n  //   modelSelection 投影的 lastUsed 因此变成 delegate 模型；反思轮结束后的下一条普通\n  //   请求没有 pending 可回落，就沿用 delegate 并自我固化（真机复现）。插件侧不 append\n  //   model/selection（那是用户选择语义），改为记住「被覆盖掉的主模型」：下一条普通请求\n  //   若仍解析到我们写下的 delegate 路由（= 纯 request/header 回落）就还原主模型并清账；\n  //   解析结果不同 = 用户在 dream 期间自己选了模型 → 原样放行并清账（绝不覆盖用户选择）。\n  //   用户恰好选中 delegate 模型本身：宿主会 append model/selection，日志里能看见 → 放行。\n  //   内存态仅进程内（宿主重启丢一次还原，已知限制）。\n  // waterfall 契约：listener 必须 return 最终 config（不改也要透传 next() 结果）。\n  if (resolved.delegate.modelSpec !== undefined) {\n    const spec = resolved.delegate.modelSpec\n    // #71：sid → 主模型路由 + 我们写下的 delegate 路由（配对保存，避免把 delegate 当主模型）\n    const delegateRestore = new Map<string, { main: ModelRoute; route: ModelRoute }>()\n    const MAX_DELEGATE_TRACKED = 512\n    ctx.on('agent/request', async (payload: { agent?: { session?: { header?: SessionHeaderLike } } }, next: () => Promise<unknown>) => {\n      const config = await next() as ModelRoute\n      const agent = payload?.agent\n      // 子代理请求不覆盖也不还原（fork 子代理已不再由本插件产生；GUI 手动 fork 的照常放行）\n      if (agent === undefined || agent.session?.header?.origin === 'subagent') return config\n      const sid = sessionIdOfAgent(agent)\n      const events = sessionEventsOf(agent.session as never)\n      if (isMemoryTaskTurn(events)) {\n        // 只在本会话还没记过时记：同一反思轮第 2 步起解析出的是我们写下的 delegate 路由，\n        // 记错会把 delegate 存成主模型（真机日志一次反思有 2 个 header）。无会话 id 不记（防串会话）。\n        const route: ModelRoute = { provider: spec.provider ?? config.provider, model: spec.model ?? config.model }\n        if (sid !== 'unknown' && !delegateRestore.has(sid)) {\n          delegateRestore.set(sid, { main: mainRouteOf(config), route })\n          // 进程级 Map 兜底上限（Map 保留插入序）：只保最近 MAX_DELEGATE_TRACKED 个会话\n          while (delegateRestore.size > MAX_DELEGATE_TRACKED) {\n            const oldest = delegateRestore.keys().next().value\n            if (oldest === undefined) break\n            delegateRestore.delete(oldest)\n          }\n        }\n        ctx.logger.info(`meow-memory: memory task turn → model override ${spec.provider ?? '(inherit)'}/${spec.model ?? ''}`)\n        return {\n          ...config,\n          ...(spec.provider !== undefined ? { provider: spec.provider } : {}),\n          ...(spec.model !== undefined ? { model: spec.model } : {}),\n        }\n      }\n      const remembered = delegateRestore.get(sid)\n      if (remembered === undefined) return config // 没覆盖过 / 已还原：零开销放行\n      delegateRestore.delete(sid)\n      if (userSelectedAfterOverride(events, remembered.route)) return config\n      if (config.provider !== remembered.route.provider || config.model !== remembered.route.model) return config // 用户换了别的模型：放行\n      ctx.logger.info(`meow-memory: restore main model ${remembered.main.provider}/${remembered.main.model} after memory task turn`)\n      const { reasoningEffort: _inherited, ...rest } = config\n      return { ...rest, provider: remembered.main.provider, model: remembered.main.model, ...(remembered.main.reasoningEffort === undefined ? {} : { reasoningEffort: remembered.main.reasoningEffort }) }\n    })\n    ctx.logger.info(`meow-memory: model override armed for reflect/dream turns (${spec.provider ?? '(inherit)'}/${spec.model ?? ''})`)\n  }\n\n  // 3) 空闲整理（按窗口；windowIndex 记录 sessionId → workspace）。\n  // dream 扫描的门控回调：停用名单 ∨ 未信任（#64）都不进 sweep（静默跳过，同\n  // disabledWorkspaces 待遇；用户可见的拦截文案在工具/命令层各自给出）。\n  const dreamSweepBlocked = (ws: string): boolean => workspaceDisabled(ws) || isUntrustedMemoryWorkspace(ws)\n  const stopDream = scheduleDream(ctx, resolved.dream, resolved.projectDir, windowIndex, signalDreamState, dreamSweepBlocked)\n  ctx.logger.info(\n    `meow-memory: dream scheduled (idle ${resolved.dream.idleMinutes}m, suppress ${resolved.dream.suppressWindows.map((w) => `${w.start}-${w.end}`).join(' ')} lead ${resolved.dream.suppressLeadMinutes}m, every ${resolved.dream.checkMinutes}m, tz ${resolved.dream.timeZone}, rules review ${resolved.dream.rulesReviewDays}d)`,\n  )\n\n  // 4) 会话列表\"已 dream\"图标数据面（仿 meow-eyes describe 路由，webServer 可选服务）：\n  //    - GET /meow-memory/dreamed-sessions：全量快照（client 挂载/重连时拉一次）；\n  //    - GET /meow-memory/dream-events：SSE 长连接，dream 完成/新活动时推送增量信号（事件驱动，无轮询）。\n  // webServer 服务可能晚于本插件就绪（fiber 并发启动竞态——实测 3080 重启后 apply 时\n  // webServer 未注册 → 路由缺失、SPA fallback 接管；热重载时代服务早已就绪无此问题）。\n  // 修复：立即尝试；未就绪则每 1s 重试（最多 20 次）；dispose 时清理定时器。\n  // 注册挂 ctx.effect：fiber dispose 时自动注销（super-injector 热重载契约——裸注册在\n  // 热重载时残留路由 → 下次 apply duplicate 报错）。\n  const routeDisposers: Array<() => void> = []\n  let routeTimer = 0\n  const tryRegisterDreamRoutes = (attempt: number): void => {\n    const ws = (ctx as { get?: (name: string) => unknown }).get?.('webServer') as\n      | { register?: (route: { kind: 'exact'; path: string; handler: (req: unknown, res: unknown) => void }) => () => void }\n      | undefined\n    if (ws !== undefined && typeof ws.register === 'function') {\n      // #57：动态路由全部过鉴权闸（与官方 /api 同闸）——webServer.register 不经过\n      // dsh-client-connection 的鉴权层，裸注册曾跨站可读可写。#78 起 connection\n      // 改懒解析（0.2.x 宿主对插件 ctx 结构性不可见，注册时捕获一次=永久 503）：\n      // 每请求现取，取到走官方闸/旧版 fence，取不到降级环回 fence（跨站仍全挡），\n      // 并打一次 warn。静态资源型路由（本插件无）保持开放。\n      const gated = <R,>(handler: (req: unknown, res: R) => void): ((req: unknown, res: R) => void) =>\n        authGateLazy<R>(ctx, handler, {\n          onDegraded: () => {\n            ctx.logger.warn('meow-memory: connection 服务不可用，/meow-memory/* 路由降级为环回 fence（#78：无 cookie 认证，跨站读写仍全挡）')\n          },\n        })\n      const registerOne = (route: { kind: 'exact'; path: string; handler: (req: unknown, res: unknown) => void }): void => {\n        try {\n          routeDisposers.push(ctx.effect(() => ws.register(route)))\n        } catch (e) {\n          ctx.logger.warn(`meow-memory: route ${route.path} 注册失败: ${e instanceof Error ? e.message : String(e)}`)\n        }\n      }\n      registerOne({\n        kind: 'exact',\n        path: '/meow-memory/dreamed-sessions',\n        handler: gated((_req, res) => {\n          void (async () => {\n            try {\n              const sessionPersistence = (ctx as { get?: (name: string) => unknown }).get?.('sessionPersistence') as\n                | { list?: () => Promise<ReadonlyArray<PersistedSessionLike>> }\n                | undefined\n              const sessions = typeof sessionPersistence?.list === 'function' ? await sessionPersistence.list() : []\n              const states = collectDreamStates(sessions, resolved.projectDir)\n              writeJson(res, 200, { sessionIds: states.dreamed, dreamingIds: states.dreaming })\n            } catch (e) {\n              writeJson(res, 500, { ok: false, error: e instanceof Error ? e.message : String(e) })\n            }\n          })()\n        }),\n      })\n      registerOne({\n        kind: 'exact',\n        path: '/meow-memory/dream-events',\n        handler: gated((req, res) => broadcast.handle(req as never, res as never)),\n      })\n      // 记忆参与门控（v0.16.0 跳过 dream → v0.30.0 三档门控，issue #38 的数据面）：\n      //    - GET  /meow-memory/skip-dreams → { sessionIds, scopes }（全部已知工作区\n      //      合并；scopes = 每窗口三档明细，sessionIds 保留旧客户端的 dream 档子集）；\n      //    - POST /meow-memory/skip-dreams { sessionId, field, value }（三档）或\n      //      { sessionId, skip }（旧形态 = dream 档），写库后经既有事件通道推\n      //      skip/unskip（dream 档，图标旧通道兼容）+ scope 明细（面板/新客户端）；\n      //      同实例多标签页即时同步，跨实例靠重连对账补齐——与 dream 图标同一限制）。\n      registerOne({\n        kind: 'exact',\n        path: '/meow-memory/skip-dreams',\n        handler: gated((req, res) => {\n          void (async () => {\n            try {\n              if ((req as { method?: string }).method === 'POST') {\n                const body = await readJsonBody(req) as { sessionId?: unknown; skip?: unknown; field?: unknown; value?: unknown }\n                const sessionId = typeof body.sessionId === 'string' ? body.sessionId : ''\n                if (sessionId.length === 0) return writeJson(res, 400, { ok: false, error: 'sessionId required' })\n                // 双形态：{ sessionId, skip }（v0.16.0 旧客户端）= dream 档；\n                // { sessionId, field, value }（v0.30.0 面板）= 三档任一。\n                let field: 'dream' | 'inject' | 'write' = 'dream'\n                let value = body.skip === true\n                if (body.field !== undefined) {\n                  if (body.field !== 'dream' && body.field !== 'inject' && body.field !== 'write') {\n                    return writeJson(res, 400, { ok: false, error: 'field must be dream|inject|write' })\n                  }\n                  field = body.field\n                  value = body.value === true\n                }\n                const ws = await resolveWorkspaceForSession(ctx, sessionId)\n                if (ws === null) return writeJson(res, 404, { ok: false, error: 'unknown session (no workspace)' })\n                getDb(ws, resolved.projectDir).setMemoryScopeField(sessionId, field, value)\n                if (field === 'dream') broadcast.broadcast(sessionId, value ? 'skip' : 'unskip') // dream 图标旧通道\n                broadcast.broadcastScope(sessionId, field, value) // 面板/新客户端通道\n                ctx.logger.info(`meow-memory: memory scope ${field}=${value ? 'on' : 'off'} for ${shortSessionId(sessionId)}`)\n                return writeJson(res, 200, { ok: true, field, value })\n              }\n              const workspaces = new Set<string>()\n              for (const [, w] of windowIndex) {\n                if (typeof w === 'string' && w.length > 0) workspaces.add(w)\n              }\n              const ids = new Set<string>()\n              const scopes: Array<{ sessionId: string; dream: boolean; inject: boolean; write: boolean }> = []\n              for (const w of workspaces) {\n                if (!existsSync(memoryDbPath(w, resolved.projectDir))) continue // 无记忆库不新建（collectDreamStates 同款）\n                try {\n                  for (const sc of getDb(w, resolved.projectDir).listMemoryScopes()) {\n                    scopes.push({ sessionId: sc.session_id, dream: sc.dream, inject: sc.inject, write: sc.write })\n                    if (sc.dream) ids.add(sc.session_id) // 旧客户端字段（dream 档子集）\n                  }\n                } catch {\n                  /* 单工作区库损坏：跳过 */\n                }\n              }\n              writeJson(res, 200, { sessionIds: [...ids], scopes })\n            } catch (e) {\n              writeJson(res, 500, { ok: false, error: e instanceof Error ? e.message : String(e) })\n            }\n          })()\n        }),\n      })\n      ctx.logger.info('meow-memory: dreamed-sessions snapshot + dream-events SSE + skip-dreams routes registered (behind auth gate)')\n      return\n    }\n    if (attempt < 20) {\n      routeTimer = setTimeout(() => tryRegisterDreamRoutes(attempt + 1), 1000) as unknown as number\n    } else {\n      ctx.logger.warn('meow-memory: webServer 服务 20s 内未就绪，会话列表 dream 图标数据路由未注册')\n    }\n  }\n  tryRegisterDreamRoutes(0)\n\n  // 5) 用户命令 /dream（dsh 命令平面，可选服务）：输入框敲 /dream 手动唤起本窗口\n  //    dream，斜杠菜单经 commands.list 自动列出（零客户端改动）。commands 服务可能\n  //    晚于本插件就绪（fiber 并发启动竞态，同 webServer 路由）→ 立即尝试 + 每 1s\n  //    重试（最多 20 次）；注册挂 ctx.effect：热重载/dispose 自动注销（裸注册在\n  //    热重载时残留 → 下次 apply duplicate 报错）。\n  const commandDisposers: Array<() => void> = []\n  let commandTimer = 0\n  const tryRegisterDreamCommand = (attempt: number): void => {\n    const commands = (ctx as { get?: (name: string) => unknown }).get?.('commands') as\n      | { register?: (definition: unknown) => unknown }\n      | undefined\n    if (commands !== undefined && typeof commands.register === 'function') {\n      try {\n        commandDisposers.push(ctx.effect(() => commands.register(dreamCommandDefinition(ctx, resolved.projectDir, signalDreamState, () => resolved.dream.rulesReviewDays, workspaceDisabled, isUntrustedMemoryWorkspace))))\n        ctx.logger.info('meow-memory: /dream user command registered')\n      } catch (e) {\n        ctx.logger.warn(`meow-memory: /dream 命令注册失败: ${e instanceof Error ? e.message : String(e)}`)\n      }\n      // /meow-trust（#64）：信任当前工作区自带的记忆库。与 /dream 同平面同注册\n      // 契约（commands 可选服务 + ctx.effect 清理）；定义在 trust.ts（无 ctx 依赖）。\n      try {\n        commandDisposers.push(ctx.effect(() => commands.register(trustCommandDefinition())))\n        ctx.logger.info('meow-memory: /meow-trust user command registered')\n      } catch (e) {\n        ctx.logger.warn(`meow-memory: /meow-trust 命令注册失败: ${e instanceof Error ? e.message : String(e)}`)\n      }\n      return\n    }\n    if (attempt < 20) {\n      commandTimer = setTimeout(() => tryRegisterDreamCommand(attempt + 1), 1000) as unknown as number\n    } else {\n      ctx.logger.warn('meow-memory: commands 服务 20s 内未就绪，/dream 用户命令未注册（memory_dream 工具不受影响）')\n    }\n  }\n  tryRegisterDreamCommand(0)\n\n  ctx.on('dispose', () => {\n    for (const dispose of toolDisposers) {\n      try {\n        dispose()\n      } catch {\n        /* 注销失败不阻塞 */\n      }\n    }\n    for (const dispose of routeDisposers) {\n      try {\n        dispose()\n      } catch {\n        /* 注销失败不阻塞 */\n      }\n    }\n    for (const dispose of commandDisposers) {\n      try {\n        dispose()\n      } catch {\n        /* 注销失败不阻塞 */\n      }\n    }\n    clearTimeout(routeTimer)\n    clearTimeout(commandTimer)\n    stopDream()\n    disposeDreamHeartbeats() // 热重载不残留 dream 租约心跳定时器\n    broadcast.dispose()\n    try {\n      closeAllDbs()\n    } catch {\n      /* 关库失败不阻塞清理链 */\n    }\n  })\n}\n\n/** 统一 JSON 响应（路由用）。 */\nfunction writeJson(res: unknown, status: number, body: unknown): void {\n  try {\n    const r = res as { writeHead?: (code: number, headers: Record<string, string>) => void; end?: (chunk?: string) => void }\n    r.writeHead?.(status, { 'content-type': 'application/json' })\n    r.end?.(JSON.stringify(body))\n  } catch {\n    /* 响应失败不抛 */\n  }\n}\n\n/** 读 POST JSON body（64KB 上限；空 body = {}）。 */\nfunction readJsonBody(req: unknown, maxBytes = 65_536): Promise<unknown> {\n  return new Promise((resolve, reject) => {\n    const r = req as { on?: (ev: string, cb: (chunk?: unknown) => void) => void }\n    const chunks: Buffer[] = []\n    let size = 0\n    r.on?.('data', (chunk: Buffer | string) => {\n      const buf = typeof chunk === 'string' ? Buffer.from(chunk) : chunk\n      size += buf.length\n      if (size > maxBytes) {\n        reject(new Error('request body too large'))\n        return\n      }\n      chunks.push(buf)\n    })\n    r.on?.('end', () => {\n      if (chunks.length === 0) {\n        resolve({})\n        return\n      }\n      try {\n        resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')))\n      } catch (e) {\n        reject(e instanceof Error ? e : new Error(String(e)))\n      }\n    })\n    r.on?.('error', (e: unknown) => reject(e instanceof Error ? e : new Error(String(e))))\n  })\n}\n\n/**\n * 解析会话 → 工作区：先查 windowIndex（模块级 sid→cwd 索引，apply 时已从\n * 文件+windows 表恢复）；查不到再用 sessionPersistence.list() 按 cwd 兜底\n * （覆盖从未产生过事件的全新会话），命中顺手回填索引。\n * 都找不到返回 null（该会话不属于任何已知工作区，无法定位其记忆库）。\n */\nasync function resolveWorkspaceForSession(ctx: Context, sessionId: string): Promise<string | null> {\n  const direct = windowIndex.get(sessionId)\n  if (typeof direct === 'string' && direct.length > 0) return direct\n  try {\n    const sp = (ctx as { get?: (name: string) => unknown }).get?.('sessionPersistence') as\n      | { list?: () => Promise<ReadonlyArray<PersistedSessionLike>> }\n      | undefined\n    const sessions = typeof sp?.list === 'function' ? await sp.list() : []\n    // 双版本形状（2026-09-10）：0.1.2- 扁平 SessionHeader / 0.1.3+ Snapshot{header}，headerOf 统一取。\n    const hit = sessions.map(headerOf).find((h) => h.id === sessionId)\n    if (hit && typeof hit.cwd === 'string' && hit.cwd.length > 0) {\n      windowIndex.set(sessionId, hit.cwd)\n      persistWindowIndex()\n      return hit.cwd\n    }\n  } catch {\n    /* sessionPersistence 不可用 */\n  }\n  return null\n}\n\n// ── 模块级窗口索引（sessionId → workspace） ────────────────────────────────\n// 持久化到全局目录（activeHomeDir()）/window-index.json：热重载/重启会重置模块级\n// Map，若不恢复则旧窗口（reload 后无新事件）从 dream 检查中失联——有记忆也不 dream。\n// 恢复后 agent 经 ctx.agents（AgentRegistry，harness 进程级）获取，不受插件 reload 影响。\n\nconst windowIndex = new Map<string, string>()\n\n/** apply 时恢复窗口索引：①文件（上次落盘）→ workspace 集合；②每个已知 workspace\n *  的 windows 表（DB 持久化，含 reload 前全部窗口）补全——旧窗口（reload 后无新\n *  事件、文件里没有）也能恢复，不会从 dream 检查中失联。indexFile 缺省动态取当前\n *  全局目录——热切换目录后重调本函数即可把新目录的账本 merge 进内存。 */\nexport function loadWindowIndex(dir = '.dsh-meow', indexFile = join(activeHomeDir(), 'window-index.json')): void {\n  const workspaces = new Set<string>()\n  try {\n    const merged = JSON.parse(readFileSync(indexFile, 'utf8')) as Record<string, unknown>\n    for (const [sid, ws] of Object.entries(merged)) {\n      if (typeof ws === 'string' && ws.length > 0) {\n        windowIndex.set(sid, ws)\n        workspaces.add(ws)\n      }\n    }\n  } catch {\n    /* 无文件/损坏 */\n  }\n  for (const ws of workspaces) {\n    // 已删除的工作区不复活（issue #27）：目录没了、或从未建过库的，一律跳过——\n    // 绝不为「恢复索引」新建目录或空库（collectDreamStates / skip-dreams 同款守卫）。\n    // json 里的 sid→workspace 映射不受影响（上面已恢复），只是不去打开它的库。\n    if (!existsSync(ws) || !existsSync(memoryDbPath(ws, dir))) continue\n    try {\n      for (const w of getDb(ws, dir).listWindows()) {\n        if (typeof w.workspace === 'string' && w.workspace.length > 0) windowIndex.set(w.session_id, w.workspace)\n      }\n    } catch {\n      /* 该 workspace 库不可用：跳过 */\n    }\n  }\n}\n\n/** 窗口索引落盘（读-合并-写，低频事件驱动；失败不阻塞）。 */\nfunction persistWindowIndex(): void {\n  const indexFile = join(activeHomeDir(), 'window-index.json')\n  try {\n    mkdirSync(dirname(indexFile), { recursive: true })\n    let merged: Record<string, string> = {}\n    try {\n      merged = JSON.parse(readFileSync(indexFile, 'utf8')) as Record<string, string>\n    } catch {\n      /* 首次写入 */\n    }\n    for (const [sid, ws] of windowIndex) merged[sid] = ws\n    writeFileSync(indexFile, JSON.stringify(merged), 'utf8')\n  } catch {\n    /* 持久化失败不阻塞 */\n  }\n}\n\n// re-export 供测试/调试/其他插件\nexport { PLUGIN_SOURCE, REFLECT_MARKER }\nexport { parseModelSpec, REFLECT_DELEGATE_MARKER, REFLECT_DONE_DELEGATE_MARKER, DREAM_DELEGATE_MARKER } from './delegate.js'\nexport { collectDreamStates, headerOf, type PersistedSessionLike } from './dream-signal.js'\nexport { MemoryDb, memoryDbPath, getDb, closeAllDbs, backupMemoryDb, LEVELS, newId, PROJECT_SUBCATEGORIES, projectList, projectCovers, projectLabel, relativeTime, isGlobalProject, isGlobalScope, globalProjectMarker, GLOBAL_PROJECT_CANON, GLOBAL_PROJECT_CANON_EN } from './db.js'\nexport { migrateLegacy } from './migrate.js'\nexport { buildHitInjection, buildInjection, buildReinjection, buildProjectSectionText, readSeen, markSearched, markAccessed, readInjected, markInjected, markProjectQueried, readProjectQueried, markWritten, readWritten, markReinjectPending, clearReinjectPending, isReinjectPending, MAX_REINJECT_PROJECTS, MAX_REINJECT_WRITTEN, sessionsFile, getCurrentProject, setCurrentProject, releaseSeen } from './inject.js'\nexport { buildReflectMessage, consecutiveToolSteps, scanTurn } from './reflect.js'\nexport { tokenize, stemEn, search, findSimilar, topicDrift, recencyWeight } from './bm25.js'\nexport { fillTemplate, keyedValue, resolveSlotText, setPromptLang, getPromptLang, DEFAULT_LANG, SLOTS } from './prompt-loader.js'\nexport { DEFAULT_HOME_DIR, activeHomeDir, setActiveHomeDir, dshHomeDir, pluginRootDir, homeDirPresets, resolveHomeDir, switchHomeDir, type HomeDirSwitch } from './home-dir.js'\nexport { setMemoryToolGate, registerMemoryTools } from './tools.js'\nexport { authGate, authGateLazy, connectionAuthOf } from './auth-gate.js'\n// 信任门（#64）：normalizeWorkspacePath 原定义在本文件（#28 口径），移入 trust.ts\n// 后在此 re-export 保持既有导出面不变；其余为信任注册表 API（测试直调）。\nexport { normalizeWorkspacePath, isTrustedWorkspace, isUntrustedMemoryWorkspace, trustWorkspace, registerCreatedWorkspace, hasExternalNoticeShown, markExternalNoticeShown, enableWorkspaceTrust, disableWorkspaceTrust, seedTrustedWorkspaces, trustCommandDefinition } from './trust.js'\nexport { collectDreamRounds, buildDreamMessage, windowNeedsDream, DREAM_MARKER, noteActivity, hourInTimeZone, minutesInTimeZone, isDreamSuppressed, startWindowDream, resumeAndDream, advanceDream, abortDream, recoverInterruptedDream, handleMemoryTurnFailure, dreamSweepTick, dreamCommandDefinition, isSubagentAgent, dreamSweepOnce, type DreamConfig } from './dream.js'\n"
    },
    {
      "path": "src/inject.ts",
      "content": "/**\n * meow-memory v2 — 会话开头注入。\n *\n * 结构（用户拍板）：soul/user 全量 + 记忆导引（project/topic 标题列表，\n * 正文模型自取）+ 第一条用户消息关键词命中 fact/lesson 短条目自动注入。\n * 无每轮注入——模型自己用 memory_search 深挖。\n *\n * 去重：.dsh-meow/sessions/<sessionId>.json 记录本会话注入过的 memory id，\n * 已注入不重复。\n */\n\nimport { mkdirSync, readFileSync, writeFileSync } from 'node:fs'\nimport { dirname, join } from 'node:path'\nimport type { Doc } from './bm25.js'\nimport { keywordHitScore, search, tokenize } from './bm25.js'\nimport { isGlobalProject, isGlobalScope, memoryDbPath, projectCovers, projectLabel, projectList, relativeTime, PROJECT_SUBCATEGORIES, type MemoryDb, type MemoryRow, type ProjectSubcategory } from './db.js'\nimport { fillTemplate, keyedValue } from './prompt-loader.js'\n\nexport interface InjectOptions {\n  /** 关键词命中条数上限（fact/lesson 短条目）。 */\n  hitTopK: number\n  /** 导引里 project/topic 标题超长截断长度。 */\n  titleMax: number\n}\n\nconst DEFAULT_OPTS: InjectOptions = { hitTopK: 2, titleMax: 40 }\n\nexport function sessionsFile(workspace: string, sessionId: string, dir = '.dsh-meow'): string {\n  // 会话 id 可能含 Windows 文件名非法字符（#56：飞书桥 lark-link:dm:…:0 的冒号）——\n  // 读写全部 ENOENT。非安全字符做百分号编码：确定性（跨重启同 id 同文件）、无碰撞\n  // （% 编码与原字符不重叠）、安全字符原样（既有会话文件不失效）。\n  const safe = sessionId.replace(/[^A-Za-z0-9._-]/g, (ch) => `%${ch.charCodeAt(0).toString(16).toUpperCase().padStart(2, '0')}`)\n  return join(workspace, dir, 'sessions', `${safe}.json`)\n}\n\n/** 会话记忆可见集：injected=注入过的，searched=search/find_similar 返回过的，\n *  accessed=memory_read 读过的（v0.17.0，dream 第一轮清单的\"查阅\"源）。\n *  前两者是\"本会话上下文里已经出现过的记忆\"，检索时应排除（省 token、扩大检索面）；\n *  accessed 只服务 dream 扫尾范围（读过的条目该被复查），不参与命中去重。 */\nexport interface SessionSeen {\n  injected: string[]\n  searched: string[]\n  accessed: string[]\n  /** 本会话写工具落库过的记忆 id（v0.23.0）：memory_remember（新建/合并）与\n   *  memory_update（实际写入）成功后记录，子代理代写归父窗口文件（source_session 同源）。\n   *  压缩重注入第三块数据源；releaseSeen 不清（同 projectsQueried，正是重注入数据源）。 */\n  written: string[]\n  /** 本会话 AI 调 memory_project 查阅过的项目名（v0.21.0，按查询顺序、去重、\n   *  最多保留 MAX_REINJECT_PROJECTS 个最近项）：会话压缩后重注入项目全景的清单。\n   *  '全局' 不记（全局 soul/user/rules 已在快照层，非项目）；多项目参数按逗号拆开记。 */\n  projectsQueried: string[]\n  /** 压缩成功落地后置 true（v0.21.0）：下一个含真实用户消息的 pre-step 注入\n   *  压缩重注入块（长期记忆快照 + 项目全景），随后清回 false。 */\n  reinjectPending: boolean\n  /** 当前 project 锚定（最近一次带 project 参数的 memory 工具调用）：命中检索限定\"全局+当前项目\"。 */\n  currentProject: string | null\n}\n\n/** projectsQueried 保留上限：压缩重注入的项目全景个数上限（防极端会话注入膨胀）。 */\nexport const MAX_REINJECT_PROJECTS = 8\n\n/** written 保留上限：压缩重注入\"本会话写过的记忆\"条数上限（防极端会话注入膨胀）。 */\nexport const MAX_REINJECT_WRITTEN = 20\n\nfunction readSeenFile(workspace: string, sessionId: string, dir: string): SessionSeen {\n  try {\n    const text = readFileSync(sessionsFile(workspace, sessionId, dir), 'utf8')\n    const parsed = JSON.parse(text) as Record<string, unknown>\n    return {\n      injected: Array.isArray(parsed.injected) ? parsed.injected.filter((x): x is string => typeof x === 'string') : [],\n      searched: Array.isArray(parsed.searched) ? parsed.searched.filter((x): x is string => typeof x === 'string') : [],\n      accessed: Array.isArray(parsed.accessed) ? parsed.accessed.filter((x): x is string => typeof x === 'string') : [],\n      written: Array.isArray(parsed.written) ? parsed.written.filter((x): x is string => typeof x === 'string') : [],\n      projectsQueried: Array.isArray(parsed.projectsQueried) ? parsed.projectsQueried.filter((x): x is string => typeof x === 'string') : [],\n      reinjectPending: parsed.reinjectPending === true,\n      currentProject: typeof parsed.currentProject === 'string' && parsed.currentProject.length > 0 ? parsed.currentProject : null,\n    }\n  } catch {\n    return { injected: [], searched: [], accessed: [], written: [], projectsQueried: [], reinjectPending: false, currentProject: null }\n  }\n}\n\n/** 统一写 sessions/<id>.json（全部字段一次写全——新增字段只改这里，防散落漏写）。 */\nfunction writeSeenFile(workspace: string, sessionId: string, seen: SessionSeen, dir: string): void {\n  const file = sessionsFile(workspace, sessionId, dir)\n  mkdirSync(dirname(file), { recursive: true })\n  writeFileSync(file, JSON.stringify({\n    injected: seen.injected,\n    searched: seen.searched,\n    accessed: seen.accessed,\n    written: seen.written,\n    projectsQueried: seen.projectsQueried,\n    reinjectPending: seen.reinjectPending,\n    currentProject: seen.currentProject,\n  }), 'utf8')\n}\n\n/** 读本会话已注入 id 列表（文件不存在返回空数组）。 */\nexport function readInjected(workspace: string, sessionId: string, dir = '.dsh-meow'): string[] {\n  return readSeenFile(workspace, sessionId, dir).injected\n}\n\n/** 追加写入已注入 id。 */\nexport function markInjected(workspace: string, sessionId: string, ids: string[], dir = '.dsh-meow'): void {\n  if (ids.length === 0) return\n  const seen = readSeenFile(workspace, sessionId, dir)\n  const set = new Set(seen.injected)\n  for (const id of ids) set.add(id)\n  seen.injected = [...set]\n  writeSeenFile(workspace, sessionId, seen, dir)\n}\n\n/** 本会话全部\"已见\" id（注入 + 检索 + 查阅），dream 第一轮清单范围 + 检索排除用。 */\nexport function readSeen(workspace: string, sessionId: string, dir = '.dsh-meow'): Set<string> {\n  const s = readSeenFile(workspace, sessionId, dir)\n  return new Set([...s.injected, ...s.searched, ...s.accessed])\n}\n\n/** 追加已检索返回的 id（memory_search / memory_find_similar 命中后调用）。 */\nexport function markSearched(workspace: string, sessionId: string, ids: string[], dir = '.dsh-meow'): void {\n  if (ids.length === 0) return\n  const seen = readSeenFile(workspace, sessionId, dir)\n  const set = new Set(seen.searched)\n  for (const id of ids) set.add(id)\n  seen.searched = [...set]\n  writeSeenFile(workspace, sessionId, seen, dir)\n}\n\n/** 追加 memory_read 读过的 id（v0.17.0）：dream 第一轮\"查阅过\"源。\n *  只由 memory_read 单条读取触发；memory_project 全景不标记（第三轮项目总结专门复查）。 */\nexport function markAccessed(workspace: string, sessionId: string, ids: string[], dir = '.dsh-meow'): void {\n  if (ids.length === 0) return\n  const seen = readSeenFile(workspace, sessionId, dir)\n  const set = new Set(seen.accessed)\n  for (const id of ids) set.add(id)\n  seen.accessed = [...set]\n  writeSeenFile(workspace, sessionId, seen, dir)\n}\n\n/** 追加本会话写工具落库过的 id（v0.23.0）：memory_remember（新建/合并）与\n *  memory_update（实际写入）成功后调用。重复写入移到末尾（最近优先），\n *  超过 MAX_REINJECT_WRITTEN 淘汰最旧的。 */\nexport function markWritten(workspace: string, sessionId: string, ids: string[], dir = '.dsh-meow'): void {\n  if (ids.length === 0) return\n  const seen = readSeenFile(workspace, sessionId, dir)\n  const ordered = seen.written.filter((id) => !ids.includes(id))\n  ordered.push(...ids)\n  seen.written = ordered.slice(-MAX_REINJECT_WRITTEN)\n  writeSeenFile(workspace, sessionId, seen, dir)\n}\n\n/** 读本会话写过的记忆 id 清单（压缩重注入第三块 + dream 第一轮清单用）。 */\nexport function readWritten(workspace: string, sessionId: string, dir = '.dsh-meow'): string[] {\n  return readSeenFile(workspace, sessionId, dir).written\n}\n\n/** 记录 memory_project 查阅过的项目（v0.21.0）：压缩重注入清单。\n *  全局标记（isGlobalProject，语言感知）/空串跳过；多项目参数按逗号拆开逐个记；\n *  重复查询移到末尾（最近优先）；超过 MAX_REINJECT_PROJECTS 淘汰最旧的。 */\nexport function markProjectQueried(workspace: string, sessionId: string, project: string, dir = '.dsh-meow'): void {\n  const names = project.split(',').map((p) => p.trim()).filter((p) => p.length > 0 && !isGlobalProject(p))\n  if (names.length === 0) return\n  const seen = readSeenFile(workspace, sessionId, dir)\n  const ordered = seen.projectsQueried.filter((p) => !names.includes(p))\n  ordered.push(...names)\n  seen.projectsQueried = ordered.slice(-MAX_REINJECT_PROJECTS)\n  writeSeenFile(workspace, sessionId, seen, dir)\n}\n\n/** 读本会话查阅过的项目清单（压缩重注入用；文件不存在返回空数组）。 */\nexport function readProjectQueried(workspace: string, sessionId: string, dir = '.dsh-meow'): string[] {\n  return readSeenFile(workspace, sessionId, dir).projectsQueried\n}\n\n/** 压缩成功落地后置位（compaction/end 无 error 时调用）：下一个含真实用户消息的\n *  pre-step 注入压缩重注入块。 */\nexport function markReinjectPending(workspace: string, sessionId: string, dir = '.dsh-meow'): void {\n  const seen = readSeenFile(workspace, sessionId, dir)\n  if (seen.reinjectPending) return\n  seen.reinjectPending = true\n  writeSeenFile(workspace, sessionId, seen, dir)\n}\n\n/** 清除重注入待办（重注入块注入完成后调用；幂等）。 */\nexport function clearReinjectPending(workspace: string, sessionId: string, dir = '.dsh-meow'): void {\n  const seen = readSeenFile(workspace, sessionId, dir)\n  if (!seen.reinjectPending) return\n  seen.reinjectPending = false\n  writeSeenFile(workspace, sessionId, seen, dir)\n}\n\n/** 读重注入待办标记。 */\nexport function isReinjectPending(workspace: string, sessionId: string, dir = '.dsh-meow'): boolean {\n  return readSeenFile(workspace, sessionId, dir).reinjectPending\n}\n\n/** 释放本会话已见记录（收到会话压缩信号后调用）：清空 injected/searched，\n *  允许之前注入/检索过的记忆被再次命中提取——压缩后它们的内容已不在上下文里。\n *  accessed 不清（用户拍板 2026-08-25）：它只服务 dream 扫尾范围、没有去重功能，\n *  清掉纯丢信息——长窗口压缩前读过的条目恰恰最该被 dream 复查。\n *  当前 project 锚定保留（与可见性无关）；projectsQueried/written/reinjectPending 保留\n *  （它们正是压缩重注入的数据源，见 buildReinjection）。 */\nexport function releaseSeen(workspace: string, sessionId: string, dir = '.dsh-meow'): void {\n  const seen = readSeenFile(workspace, sessionId, dir)\n  seen.injected = []\n  seen.searched = []\n  writeSeenFile(workspace, sessionId, seen, dir)\n}\n\n/** 读当前 project 锚定（最近一次带 project 参数的 memory 工具调用）；未锚定返回 null。 */\nexport function getCurrentProject(workspace: string, sessionId: string, dir = '.dsh-meow'): string | null {\n  return readSeenFile(workspace, sessionId, dir).currentProject\n}\n\n/** 锚定当前 project：memory 工具调用带 project 参数时更新会话状态（命中检索用它，免扫历史）。 */\nexport function setCurrentProject(workspace: string, sessionId: string, project: string, dir = '.dsh-meow'): void {\n  const seen = readSeenFile(workspace, sessionId, dir)\n  seen.currentProject = project\n  writeSeenFile(workspace, sessionId, seen, dir)\n}\n\nfunction toDocs(rows: MemoryRow[]): Doc[] {\n  return rows.map((r) => ({\n    id: r.id,\n    level: r.level,\n    title: r.title,\n    content: r.content,\n    keywords: r.keywords,\n    importance: r.importance,\n    created_at: r.created_at,\n    updated_at: r.updated_at,\n  }))\n}\n\nfunction shortTitle(row: MemoryRow, max: number): string {\n  const t = row.title?.trim()\n  if (t) return t.length > max ? t.slice(0, max) + '…' : t\n  const c = row.content.replace(/\\s+/g, ' ').trim()\n  return c.length > max ? c.slice(0, max) + '…' : c\n}\n/* v8 ignore next -- 保留工具函数（历史/调试用），当前导引不再截断标题 */\nvoid shortTitle\n\n/**\n * 构造长期记忆快照正文（buildInjection / buildReinjection 共用）：\n *   顶格「===== 长期记忆 =====」→ 【关于你】(soul) / 【关于user】/ 【设计原则】/ 【记忆导引】(两行)。\n * 不含结束标记与「本轮用户prompt：」尾巴（两链路各自拼装），也不做已见记账（调用方负责）。\n * @returns null = 只有标题头，无任何可注入内容。\n */\nfunction buildInjectionBody(\n  db: MemoryDb,\n  o: InjectOptions,\n): { body: string; injectedIds: string[] } | null {\n  // 框架词外置（v0.19.0）：labels.md 的 inject.* 键；记忆条目正文本身是数据不是文案，不外置。\n  const lbl = (key: string, params?: Record<string, string>): string => fillTemplate(keyedValue('labels', key), params)\n  const soul = db.list('soul', { status: 'active' })\n  const user = db.list('user', { status: 'active' })\n\n  const lines: string[] = [lbl('inject.title'), '']\n  const injected: string[] = []\n\n  const pushEntries = (label: string, rows: MemoryRow[]) => {\n    if (rows.length === 0) return\n    lines.push(lbl('inject.sectionFormat', { label }))\n    for (const r of rows) {\n      lines.push(`- ${r.content}`)\n      injected.push(r.id) // 正文已注入 → 记入已见（命中链路不再重复注入）\n    }\n    lines.push('')\n  }\n\n  pushEntries(lbl('inject.aboutYou'), soul)\n  pushEntries(lbl('inject.aboutUser'), user)\n\n  // 设计原则（rules）：注入「全局适用（未标记 null / 空串 / 全局标记「全局」「global」）\n  // 且 importance≥2」的——少而精的命令式准则。\n  // 2026-09-19 口径修复（用户拍板）：此前只认 project === null，而文档（tools.md /\n  // system-guide.md / dream-atomic.md）教模型写\"全局\"——按文档写的准则反而永不注入。\n  const globalRules = db.list('rules', { status: 'active' }).filter((r) => isGlobalScope(r.project) && r.importance >= 2)\n  pushEntries(lbl('inject.rules'), globalRules)\n\n  // 记忆导引：说明 + 项目列表（正文/标题一律自取，不列）。\n  // titleMax 落地（2026-09-10）：schema/设置页一直承诺「导引里项目名的截断长度」，\n  // 此前是死配置（shortTitle 被 void）。这里按承诺截断项目名——只影响导引一行展示，\n  // 记忆条目正文/标题依旧不截断（v0.19.0 拍板不变）。\n  const projectNames = db.listProjectNames()\n  if (projectNames.length > 0) {\n    const max = o.titleMax\n    const shown = projectNames.map((n) => (n.length > max ? n.slice(0, max) + '…' : n))\n    lines.push(lbl('inject.sectionFormat', { label: lbl('inject.guide') }))\n    lines.push(lbl('inject.guideSearchLine'))\n    lines.push(lbl('inject.guideProjectLine'))\n    lines.push(lbl('inject.guideProjects', { list: shown.join(' / ') }))\n    lines.push('')\n  }\n\n  if (lines.length <= 2) return null // 只有标题头，无任何内容\n  return { body: lines.join('\\n').trimEnd(), injectedIds: injected }\n}\n\n/**\n * 构造首轮长期记忆注入块（用户拍板格式，PR #10 起为独立 plugin snapshot 正文）：\n *   顶格「===== 长期记忆 =====」→ 【关于你】(soul) / 【关于user】/ 【设计原则】/ 【记忆导引】(两行)。\n *   不再拼接结束标记与「本轮用户prompt：」尾巴——正文作为独立消息插在真实用户消息前，\n *   用户 prompt 保持原样（防会话标题污染；旧格式历史会话由前端折叠兼容）。\n * 首轮只注入长期记忆，不做关键词命中（命中链路从第二轮起，见 buildHitInjection）；\n * 正文注入的 id 记入已见（命中链路不再重复注入它们）。\n * @returns { text, injectedIds }；无任何可注入内容返回 null。\n */\nexport function buildInjection(\n  db: MemoryDb,\n  workspace: string,\n  sessionId: string,\n  _firstUserText: string = '',\n  opts: Partial<InjectOptions> = {},\n  dir = '.dsh-meow',\n): { text: string; injectedIds: string[] } | null {\n  const o = { ...DEFAULT_OPTS, ...opts }\n  const built = buildInjectionBody(db, o)\n  if (built === null) return null\n  const text = built.body\n  if (built.injectedIds.length > 0) markInjected(workspace, sessionId, built.injectedIds, dir)\n  return { text, injectedIds: built.injectedIds }\n}\n\n/** 框架词（labels.md）：项目全景段落里的短词随语言包走（PR #6 外置，zh 值逐字不变）。 */\nconst lbl = (key: string, params?: Record<string, string>): string => fillTemplate(keyedValue('labels', key), params)\n/** 子标签 → 注入段落标题（文案外置：labels.md 的 project.section.*）。 */\nconst sectionTitle = (sub: ProjectSubcategory): string => lbl(`project.section.${sub}`)\n\n/** 组内排序：记忆时间戳（updated_at）旧→新，相同按创建时间；null 视为最旧。 */\nfunction sortByUpdatedAt(list: MemoryRow[]): MemoryRow[] {\n  return [...list].sort((a, b) => (a.updated_at ?? 0) - (b.updated_at ?? 0) || a.created_at - b.created_at)\n}\n\n/** 项目全景条目行（原文视图）：归属 + 完整 id + 绝对/相对时间戳，第二行完整内容。\n *  归属显示：'全局'=真全局；null=未标记（可能是数据 bug）；多值 join '/'。 */\nfunction fmtProjectRow(r: MemoryRow): string {\n  const abs = new Date(r.updated_at).toISOString().slice(0, 16).replace('T', ' ')\n  return `[${projectLabel(r.project)} : ${r.level}] [${r.id}] ${abs} [${relativeTime(r.updated_at)}]\\n${r.content}`\n}\n\n/**\n * 构造项目全景注入段落（memory_project 工具与压缩重注入共用，v0.21.0 从 tools.ts 迁入）：\n * 【项目：X】+ 项目设计原则(rules，放最前——规则优先于事实) + 各子标签分组\n * （组内按记忆时间戳旧→新；todo 含已完成最近 5 条）+ 检索说明尾注。\n * 非 todo 子标签只取 active；条目正文本身是数据，不做文案外置。\n * @returns null = 项目无任何可注入段落（active 条目与已完成 todo 皆空）。\n */\n/** 内部构造：段落文本 + 段内出现过的全部条目 id（压缩重注入第三块按此去重，防同块重复展示）。 */\nfunction buildProjectSection(db: MemoryDb, workspace: string, project: string, dir: string): { text: string; ids: string[] } | null {\n  // 项目视图按名单语义匹配（#61）：project 字段写多项目名（'dsh,femo'）的条目，\n  // 在任一名单项目的视图都该可见——SQL 精确等值会把两边都漏掉。全局标记/未标记\n  // projectList 为空、不命中任何具体项目名，保持「全局内容走快照层」的原语义。\n  const rows = db.list('project').filter((r) => projectList(r.project).includes(project))\n  const ids: string[] = []\n  const render = (list: MemoryRow[]): string => {\n    for (const r of list) ids.push(r.id)\n    return list.map(fmtProjectRow).join('\\n')\n  }\n  const active = rows.filter((r) => r.status === 'active')\n  // todo 已完成：stale 且 updated_at 非空，按 updated_at 取最近 5 条（展示仍按旧→新）。\n  const done = sortByUpdatedAt(\n    rows\n      .filter((r) => r.subcategory === 'todo' && r.status === 'stale' && r.updated_at !== null)\n      .sort((a, b) => (b.updated_at ?? 0) - (a.updated_at ?? 0))\n      .slice(0, 5),\n  )\n  const bySub = new Map<ProjectSubcategory, MemoryRow[]>()\n  for (const r of active) {\n    const sub = r.subcategory ?? 'overview' // 早期无子类条目归概述组\n    const list = bySub.get(sub) ?? []\n    list.push(r)\n    bySub.set(sub, list)\n  }\n  const sections: string[] = []\n  // 项目设计原则（rules，project 特定）：放最前——规则优先于事实。\n  const projectRules = sortByUpdatedAt(\n    db.list('rules').filter((r) => projectList(r.project).includes(project) && r.status === 'active'),\n  )\n  if (projectRules.length > 0) {\n    sections.push(`${lbl('inject.rules')}\\n${render(projectRules)}`)\n  }\n  for (const sub of PROJECT_SUBCATEGORIES) {\n    if (sub === 'todo') {\n      const todos = sortByUpdatedAt(bySub.get('todo') ?? [])\n      if (todos.length === 0 && done.length === 0) continue\n      const lines = [sectionTitle('todo')]\n      if (done.length > 0) {\n        lines.push(lbl('project.todoDone'))\n        for (const r of done) {\n          ids.push(r.id)\n          lines.push(fmtProjectRow(r))\n        }\n      }\n      if (todos.length > 0) {\n        lines.push(lbl('project.todoOpen'))\n        for (const r of todos) {\n          ids.push(r.id)\n          lines.push(fmtProjectRow(r))\n        }\n      }\n      sections.push(lines.join('\\n'))\n    } else {\n      const list = sortByUpdatedAt(bySub.get(sub) ?? [])\n      if (list.length === 0) continue\n      sections.push(`${sectionTitle(sub)}\\n${render(list)}`)\n    }\n  }\n  if (sections.length === 0) return null\n  const dbPath = memoryDbPath(workspace, dir)\n  const text = [\n    lbl('project.header', { name: project }),\n    '',\n    sections.join('\\n\\n'),\n    '',\n    '——',\n    '说明：此处只提供 active 的记忆。',\n    `如果你想看非 active 条目（archived=删除 / stale=完结），或某条记忆的具体时间戳（记忆时间戳=该窗口 dream 封存时刻）、记忆来源（source_session）、重要性、关键词等元数据，可以直接去搜记忆库 SQLite：${dbPath}`,\n    '（库内结构：七层表 soul/user/project/fact/lesson/topic/rules，字段含 id/title/content/importance/keywords/status/corrected/project/subcategory/goal/source_session/created_at/updated_at（记忆时间戳=最后更新时间）/last_accessed_at；另有 dream_log 整理留痕表、windows 窗口时间表；也可按 id 用 memory_read 看单条完整元数据）',\n    `如果你想了解未被记录的更多细节，可以直接去搜会话历史目录（dsh 的 session 日志，位置由 DSH_HOME 决定，默认 ~/.dsh/sessions，喵版为 dsh-home/sessions），按会话 id 查原始记录。`,\n  ].join('\\n')\n  return { text, ids }\n}\n\n/** 段落文本视图（memory_project 工具用）：只要文本。 */\nexport function buildProjectSectionText(db: MemoryDb, workspace: string, project: string, dir = '.dsh-meow'): string | null {\n  return buildProjectSection(db, workspace, project, dir)?.text ?? null\n}\n\n/**\n * 压缩重注入第三块（v0.23.0）：本会话写过的记忆原文回放。\n * 数据源 = sessions/<id>.json 的 written（memory_remember/memory_update 落库痕迹，\n * 子代理代写归父窗口）∪ db 层 source_session=本会话 的新建条目（双保险，覆盖插件\n * 热更新前旧代码写入的条目）。按当前库最新数据解析原文（不缓存旧文本）；只回放\n * status=active（archived/stale 内容已失效，回放会误导）；排除快照正文与项目全景\n * 已展示的 id（防同块重复）；超出 MAX_REINJECT_WRITTEN 保留最近写入的。\n * @returns null = 本会话没有可回放的写入条目。\n */\nfunction buildWrittenSection(\n  db: MemoryDb,\n  workspace: string,\n  sessionId: string,\n  dir: string,\n  exclude: ReadonlySet<string>,\n): { text: string; ids: string[] } | null {\n  const ordered: string[] = [...readWritten(workspace, sessionId, dir)]\n  for (const { id } of db.idsBySession(sessionId)) {\n    if (!ordered.includes(id)) ordered.push(id)\n  }\n  const rows: MemoryRow[] = []\n  for (const id of ordered) {\n    if (exclude.has(id)) continue\n    const found = db.findById(id)\n    if (!found || found.row.status !== 'active') continue\n    rows.push(found.row)\n  }\n  const kept = rows.slice(-MAX_REINJECT_WRITTEN)\n  if (kept.length === 0) return null\n  return {\n    text: [\n      lbl('inject.sectionFormat', { label: lbl('inject.writtenSection') }),\n      lbl('inject.writtenIntro'),\n      ...kept.map(fmtProjectRow),\n    ].join('\\n'),\n    ids: kept.map((r) => r.id),\n  }\n}\n\n/**\n * 构造压缩重注入块（v0.21.0 三块制，v0.23.0 增第三块）：\n * ① 长期记忆快照正文（与首轮 buildInjection 同款）；\n * ② 【会话已压缩】说明 + 本会话此前查阅过的项目全景（按当前库最新数据重新构造，\n *    空项目跳过；项目全景条目按现行原则不标记已见）；\n * ③ 【本会话写过的记忆】+ 本会话写工具落库过的条目原文（见 buildWrittenSection）。\n * 不拼尾注（PR #10 起）：正文作为独立 plugin snapshot 消息插在真实用户消息前，\n * 用户 prompt 保持原样。\n * 快照条目 id 与回放的 written id 重新记入 injected——压缩后内容重新进入上下文，\n * 去重语义随之恢复（合并更新过的他窗条目不再被关键词命中重复注入）。\n * @returns null = 无任何可注入内容（库无快照正文、项目全空且无写入条目）；调用方仍应\n *          清除 reinjectPending，避免每个用户消息轮空转重查。\n */\nexport function buildReinjection(\n  db: MemoryDb,\n  workspace: string,\n  sessionId: string,\n  projects: readonly string[],\n  opts: Partial<InjectOptions> = {},\n  dir = '.dsh-meow',\n): { text: string; injectedIds: string[] } | null {\n  const o = { ...DEFAULT_OPTS, ...opts }\n  const snapshot = buildInjectionBody(db, o)\n  const projectTexts: string[] = []\n  const projectIds = new Set<string>()\n  for (const project of projects) {\n    const built = buildProjectSection(db, workspace, project, dir)\n    if (built !== null) {\n      projectTexts.push(built.text)\n      for (const id of built.ids) projectIds.add(id)\n    }\n  }\n  // 第三块：本会话写过的记忆（排除快照与项目全景已展示的 id，防同块重复）。\n  const written = buildWrittenSection(db, workspace, sessionId, dir, new Set([...(snapshot?.injectedIds ?? []), ...projectIds]))\n  if (snapshot === null && projectTexts.length === 0 && written === null) return null\n  const lines: string[] = []\n  if (snapshot !== null) {\n    lines.push(snapshot.body)\n    lines.push('')\n  }\n  if (projectTexts.length > 0 || written !== null) {\n    lines.push(lbl('inject.sectionFormat', { label: lbl('inject.reinjectSection') }))\n    lines.push(lbl('inject.reinjectIntro'))\n    lines.push('')\n    if (projectTexts.length > 0) {\n      lines.push(projectTexts.join('\\n\\n'))\n      lines.push('')\n    }\n  }\n  if (written !== null) {\n    lines.push(written.text)\n    lines.push('')\n  }\n  const text = lines.join('\\n').trimEnd()\n  const replayedIds = [...(snapshot?.injectedIds ?? []), ...(written?.ids ?? [])]\n  if (replayedIds.length > 0) markInjected(workspace, sessionId, replayedIds, dir)\n  return { text, injectedIds: replayedIds }\n}\n\n/** 关键词命中查询（首轮与每条消息链路共用）：active 的 fact/lesson/rules/topic，\n *  范围=全局 或 当前 project 锚定；排除本会话已见（injected+searched）；\n *  不检索本 session 建立的记忆（它们就在上下文里，AI 最清楚，无需命中）。\n *  命中打分基于条目关键词（keywords，+title）而非全文——全文匹配噪音大\n *  （常见 bigram 如\"的时\"每条消息都有，长条目一碰词就整条注入）。 */\nfunction hitQuery(\n  db: MemoryDb,\n  workspace: string,\n  sessionId: string,\n  userText: string,\n  o: InjectOptions,\n  dir: string,\n): Array<{ id: string; level: string; content: string; updated_at: number | null }> {\n  const seenState = readSeenFile(workspace, sessionId, dir)\n  const currentProject = seenState.currentProject\n  const hitRows = [\n    ...db.list('fact', { status: 'active' }),\n    ...db.list('lesson', { status: 'active' }),\n    ...db.list('rules', { status: 'active' }),\n    ...db.list('topic', { status: 'active' }),\n  ].filter((r) =>\n    (isGlobalScope(r.project) || (currentProject !== null && projectCovers(r.project, currentProject)))\n    && r.source_session !== sessionId // 本 session 建立的记忆在上下文里，不命中\n    && !seenState.injected.includes(r.id), // 已注入先排除再截断（#67）：先 hitTopK 后过滤，\n  ) // top-K 被旧命中占满时本轮会颗粒无收，注入数恒低于上限\n  if (hitRows.length === 0) return []\n  const query = userText.slice(0, 500)\n  const docs = toDocs(hitRows).map((d) => ({\n    ...d,\n    // 匹配面 = 条目关键词（LLM 提取或自动 bigram；无关键词的旧条目回退内容前 100 字）。\n    content: d.keywords.length > 0 ? d.keywords.join(' ') : d.content.slice(0, 100),\n  }))\n  // 命中专用打分：交集×覆盖率×艾宾浩斯(updated_at)×importance×title 加成（艾宾浩斯开着）。\n  const hits = keywordHitScore(query, docs, { k: o.hitTopK })\n  const byId = new Map(hitRows.map((r) => [r.id, r]))\n  // 展示/注入用原文 content（docs 的 content 只是 keywords 匹配面，不能当正文）。\n  // 已注入的进入本函数前就排掉了（#67），这里不再二次过滤。\n  return hits\n    .map((h) => {\n      const row = byId.get(h.id)\n      return { id: h.id, level: h.level, content: row?.content ?? h.content, project: row?.project ?? null, updated_at: row?.updated_at ?? null }\n    })\n}\n\n/**\n * 每条用户消息的关键词命中注入（独立于首轮注入的链路）：\n * 检索 active 的 fact/lesson/rules/topic（全局+当前锚定项目），top-K 命中注入，\n * 命中 id 记入本会话已见（之后不再命中；压缩释放 seen 后恢复）。\n * 格式：顶格「可能相关的记忆，仅供参考：」→ 条目（- [id] 换行接内容、\n * 条目间空行）。返回文本作为独立 plugin snapshot 消息的正文。\n * @returns 命中注入块；无命中返回 null。\n */\nexport function buildHitInjection(\n  db: MemoryDb,\n  workspace: string,\n  sessionId: string,\n  userText: string,\n  opts: Partial<InjectOptions> = {},\n  dir = '.dsh-meow',\n): { text: string; injectedIds: string[] } | null {\n  const o = { ...DEFAULT_OPTS, ...opts }\n  const fresh = hitQuery(db, workspace, sessionId, userText, o, dir)\n  if (fresh.length === 0) return null\n  const lines = [keyedValue('labels', 'inject.hitHeader')]\n  for (const h of fresh) {\n    // 原文视图：归属 + 完整 id + 绝对/相对时间戳（记忆时间戳=updated_at 最后更新时间；无时间戳不显示），第二行完整内容。\n    const proj = projectLabel(h.project)\n    const time = h.updated_at\n      ? ` ${new Date(h.updated_at).toISOString().slice(0, 16).replace('T', ' ')} [${relativeTime(h.updated_at)}]`\n      : ''\n    lines.push(`[${proj} : ${h.level}] [${h.id}]${time}`)\n    lines.push(h.content)\n    lines.push('')\n  }\n  const text = lines.join('\\n').trimEnd()\n  const ids = fresh.map((h) => h.id)\n  markInjected(workspace, sessionId, ids, dir)\n  return { text, injectedIds: ids }\n}\n\n// 导出 tokenize 供索引/测试复用\nexport { tokenize }\n"
    },
    {
      "path": "src/tools.ts",
      "content": "/**\n * meow-memory v2 — 工具面：memory_remember / memory_search / memory_read / memory_update。\n *\n * 写规则（进 description 给模型看）：\n * - fact/lesson 一句话直陈 ≤60 字（短是关键词命中注入的前提）；\n * - 用户介绍项目设计思路/框架/决策理由的原话必须保留措辞，不转述（project/lesson）；\n * - project 必填项目名（femo / meow-memory / meow-eyes / dsh …）；\n * - topic 必填标题（对象+动作，禁宽泛名）+ 建议目标句。\n */\n\nimport type { ToolDefinition, ToolRunContext } from '@deepseek-ai/dsh-tools'\nimport { isAbsolute, resolve } from 'node:path'\nimport { findSimilar, search, tokenize, type RankedHit } from './bm25.js'\nimport { getDb, getDreamWorkspace, globalProjectMarker, isGlobalProject, projectCovers, projectLabel, projectList, relativeTime, type Level, LEVELS, type MemoryPatch, type MemoryRow, type ProjectSubcategory, PROJECT_SUBCATEGORIES } from './db.js'\nimport { fillTemplate, keyedValue } from './prompt-loader.js'\nimport { activeHomeDir, homeDirPresets, resolveHomeDir, switchHomeDir } from './home-dir.js'\n\n/** tools.md 键值取用（prompt 文案外置 v0.19.0）：缺键时 keyedValue throw。 */\nconst T = (key: string): string => keyedValue('tools', key)\n/** 框架词/报错文案（labels.md）：与工具描述同源，随语言包走。 */\nconst L = (key: string, params?: Record<string, string>): string => fillTemplate(keyedValue('labels', key), params)\nimport { buildProjectSectionText, markProjectQueried, markWritten, readSeen, markAccessed, markSearched, setCurrentProject } from './inject.js'\n\nexport type { Level }\n\n// ── 记忆门控（issue #38/#28）：host 注册工具时注入判定器 ─────────────────────\n// 读档 = skip_inject / disabledWorkspaces → search/read/findSimilar/project 拒绝；\n// 写档 = skip_write / disabledWorkspaces → remember/update 拒绝（整理轮豁免由 host\n// 侧的 refuseWrite 闭包判定——工具层不感知轮次语义）。refusal 文案随既有工具错误\n// 通道（throw new Error）走，模型可直接读到原因。\nexport interface MemoryToolGate {\n  refuseRead?: (workspace: string, sessionId: string | null) => string | null\n  refuseWrite?: (workspace: string, sessionId: string | null) => string | null\n}\n\nlet toolGate: MemoryToolGate | undefined\n/** host 在 apply 时注入门控判定器（活配置闭包；随插件重载重建）。 */\nexport function setMemoryToolGate(gate: MemoryToolGate | undefined): void {\n  toolGate = gate\n}\n\n/** 门控检查：拒绝时抛出带理由的 Error（工具错误的既有通道）。 */\nfunction refuseOrThrow(kind: 'read' | 'write', exec: ToolRunContext): void {\n  if (toolGate === undefined) return\n  const workspace = workspaceOf(exec)\n  if (workspace === undefined) return\n  const sessionId = sessionIdOf(exec)\n  const refusal = kind === 'read' ? toolGate.refuseRead?.(workspace, sessionId) : toolGate.refuseWrite?.(workspace, sessionId)\n  if (refusal !== null && refusal !== undefined) throw new Error(refusal)\n}\n\n// ── 参数通道兜底（issue #24）────────────────────────────────────────────────\n// 部分宿主/模型走 XML 参数通道时，schema 声明为 array/number/boolean 的值会以\n// **字符串**形态到达 execute（用户实测：keywords 变成 '[\"代码审计\",\"静态扫描\"]'\n// 这类 JSON 文本，50 余次调用只有 1 次成功）。旧实现只认 Array.isArray，其余一律\n// 判「必填」清空 → memory_remember 在该类宿主上完全不可用，逼得用户绕过插件直接写\n// sqlite。这里统一做「能救就救」的归一：形态不对但语义可解析就照收，绝不因为通道\n// 差异丢参数；只有真的解析不出才报错。\n\n/** 参数形态描述（报错文案用，帮用户/模型定位通道问题）。 */\nfunction describeArg(value: unknown): string {\n  if (typeof value === 'string') return `string(\"${value.slice(0, 40)}\")`\n  if (Array.isArray(value)) return `array(${value.length})`\n  if (value === null) return 'null'\n  return typeof value\n}\n\n/**\n * 关键词归一：数组 / JSON 数组文本 / 「a, b」分隔文本 → string[]（去空白、丢空串、保持顺序）。\n * 递归处理「数组里套 JSON 文本」的形态（如 ['[\"a\",\"b\"]']）。\n */\nexport function normalizeKeywords(raw: unknown): string[] {\n  const out: string[] = []\n  const push = (v: string): void => {\n    const t = v.trim()\n    if (t.length > 0) out.push(t)\n  }\n  const walk = (v: unknown): void => {\n    if (Array.isArray(v)) {\n      for (const item of v) walk(item)\n      return\n    }\n    if (typeof v !== 'string') return\n    const text = v.trim()\n    if (text.length === 0) return\n    if (text.startsWith('[')) {\n      try {\n        const parsed: unknown = JSON.parse(text)\n        if (Array.isArray(parsed)) {\n          walk(parsed)\n          return\n        }\n      } catch { /* 非法 JSON（如 '[a, b]'）：剥掉方括号按分隔文本处理 */ }\n      walk(text.replace(/^\\[+|\\]+$/g, ''))\n      return\n    }\n    if (/[,，、;；\\n]/.test(text)) {\n      for (const part of text.split(/[,，、;；\\n]+/)) push(part)\n      return\n    }\n    push(text)\n  }\n  walk(raw)\n  return out\n}\n\n/** 数值归一：number 原样（非有限值视为未提供）；纯数字字符串（'2' / '2.0'）→ number；其余 undefined。 */\nexport function coerceNumber(raw: unknown): number | undefined {\n  if (typeof raw === 'number') return Number.isFinite(raw) ? raw : undefined\n  if (typeof raw === 'string') {\n    const t = raw.trim()\n    if (t.length === 0) return undefined\n    const n = Number(t)\n    return Number.isFinite(n) ? n : undefined\n  }\n  return undefined\n}\n\n/** 布尔归一：true / 'true' / '1' / 'yes' / 'y' / 1 → true；其余 false。 */\nexport function coerceBoolean(raw: unknown): boolean {\n  if (raw === true) return true\n  if (typeof raw === 'number') return raw === 1\n  if (typeof raw === 'string') return ['true', '1', 'yes', 'y'].includes(raw.trim().toLowerCase())\n  return false\n}\n\n/** 检索范围过滤（查询参数）：只按 project/status/days 过滤。\n *  已见（injected+searched）与本 session 建立的记忆不再预排除——search 先全量排名，\n *  前 5 条无脑取（不排除任何记忆），第 6 名起绕开已见补齐（用户拍板 2026-08-19）。 */\nfunction filterSearchable(\n  rows: MemoryRow[],\n  opts: { project?: string[] | null; status?: string[] | null; days?: number | null },\n): MemoryRow[] {\n  return rows.filter((r) => {\n    // project 多选（OR 语义）：任一项目覆盖即通过；\"全局\"/未标记天然覆盖。\n    if (opts.project && opts.project.length > 0 && !opts.project.some((p) => projectCovers(r.project, p))) return false\n    // status 多选（OR 语义）：'all' 表示不过滤。\n    const statuses = opts.status?.filter((s) => s !== 'all') ?? []\n    if (statuses.length > 0 && !statuses.includes(r.status)) return false\n    if (opts.days && Date.now() - r.created_at > opts.days * 86_400_000) return false\n    return true\n  })\n}\n\nexport function workspaceOf(exec: ToolRunContext): string | undefined {\n  const cwd = exec.agent?.session?.header?.cwd\n  if (typeof cwd === 'string' && cwd.length > 0) return cwd\n  return getDreamWorkspace() ?? undefined\n}\n\nexport function sessionIdOf(exec: ToolRunContext): string | null {\n  const header = (exec.agent?.session?.header ?? {}) as { id?: unknown; parentSession?: unknown; origin?: unknown }\n  const id = typeof header.id === 'string' && header.id.length > 0 ? header.id : null\n  // 子 agent（origin='subagent'）：source_session 继承母窗口（用户拍板：子 agent 写记忆归属父窗口）。\n  // 注意：GUI fork/续写的主会话也有 parentSession 但 origin 无——不继承（它是独立主会话）。\n  if (header.origin === 'subagent' && header.parentSession !== undefined) {\n    const p = header.parentSession\n    if (typeof p === 'string' && p.length > 0) return p\n    if (p !== null && typeof p === 'object' && typeof (p as { id?: unknown }).id === 'string') {\n      return (p as { id: string }).id\n    }\n  }\n  return id\n}\n\n/** 自动提取关键词：bigram 词频 top N（去重、去纯数字）。 */\nexport function extractKeywords(content: string, n = 10): string[] {\n  const freq = new Map<string, number>()\n  for (const t of tokenize(content)) {\n    if (/^[0-9]+$/.test(t)) continue\n    freq.set(t, (freq.get(t) ?? 0) + 1)\n  }\n  return [...freq.entries()]\n    .sort((a, b) => b[1] - a[1])\n    .slice(0, n)\n    .map(([t]) => t)\n}\n\n/** bigram Jaccard 相似度（去重用）。 */\nexport function similarity(a: string, b: string): number {\n  const sa = new Set(tokenize(a))\n  const sb = new Set(tokenize(b))\n  if (sa.size === 0 || sb.size === 0) return 0\n  let inter = 0\n  for (const t of sa) if (sb.has(t)) inter++\n  return inter / (sa.size + sb.size - inter)\n}\n\nconst DEDUP_THRESHOLD = 0.8\n\nfunction rememberTool(dir: string): ToolDefinition {\n  return {\n    name: 'memory_remember',\n    description: T('memory_remember.description'),\n    parameters: {\n      type: 'object',\n      additionalProperties: false,\n      required: ['content', 'project', 'keywords', 'importance'],\n      properties: {\n        content: { type: 'string', description: T('memory_remember.param.content') },\n        level: {\n          type: 'string',\n          enum: [...LEVELS],\n          default: 'fact',\n          description: T('memory_remember.param.level'),\n        },\n        project: { type: 'string', description: T('memory_remember.param.project') },\n        subcategory: { type: 'string', enum: [...PROJECT_SUBCATEGORIES], description: T('memory_remember.param.subcategory') },\n        goal: { type: 'string', description: T('memory_remember.param.goal') },\n        importance: { type: 'integer', default: 1, description: T('memory_remember.param.importance') },\n        corrected: { type: 'boolean', default: false, description: T('memory_remember.param.corrected') },\n        keywords: { type: 'array', items: { type: 'string' }, description: T('memory_remember.param.keywords') },\n      },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        required: ['ok'],\n        properties: {\n          ok: { type: 'boolean' },\n          id: { type: 'string' },\n          level: { type: 'string' },\n          merged: { type: 'boolean' },\n          keywords: { type: 'array', items: { type: 'string' }, description: T('memory_remember.out.keywords') },\n          project: { type: 'string', description: T('memory_remember.out.project') },\n        },\n      },\n      render: (_args, value) => {\n        const v = value as { level?: unknown; merged?: unknown; id?: unknown; keywords?: unknown; project?: unknown }\n        const kw = Array.isArray(v.keywords) && v.keywords.length > 0 ? `关键词：${v.keywords.join(' / ')}。` : ''\n        const proj = typeof v.project === 'string' ? `项目：${v.project}。` : ''\n        const head = v.merged ? '✅ 已合并到已有条目' : '✅ 记忆已写入'\n        return [{\n          type: 'text' as const,\n          text: `${head}（${String(v.level ?? 'fact')}${typeof v.id === 'string' ? `，id=${v.id.slice(0, 8)}` : ''}）。${proj}${kw}无需重复调用本工具。`,\n        }]\n      },\n    },\n    async execute(args: unknown, exec: ToolRunContext) {\n      refuseOrThrow('write', exec)\n      const parsed = args as { content?: unknown; level?: unknown; project?: unknown; subcategory?: unknown; goal?: unknown; importance?: unknown; corrected?: unknown; keywords?: unknown }\n      const content = typeof parsed.content === 'string' ? parsed.content.trim() : ''\n      // 四必填：缺失逐个报错并引导重填（用户拍板 2026-08-19）。\n      if (content.length === 0) throw new Error(L('remember.error.content'))\n      const project = typeof parsed.project === 'string' && parsed.project.trim() ? parsed.project.trim() : null\n      if (project === null) throw new Error(L('remember.error.project', { global: globalProjectMarker() }))\n      const keywords = normalizeKeywords(parsed.keywords)\n      if (keywords.length === 0) {\n        // 区分「压根没传」与「传了但解析不出任何关键词」（issue #24）：旧实现两者都\n        // 报「必填」，用户明明带了 8-13 个关键词却被告知没填，排查方向被带偏。\n        const missing = parsed.keywords === undefined || parsed.keywords === null\n          || (typeof parsed.keywords === 'string' && parsed.keywords.trim() === '')\n          || (Array.isArray(parsed.keywords) && parsed.keywords.length === 0)\n        throw new Error(missing\n          ? L('remember.error.keywords')\n          : L('remember.error.keywordsEmpty', { received: describeArg(parsed.keywords) }))\n      }\n      const importanceRaw = coerceNumber(parsed.importance)\n      if (importanceRaw === undefined) throw new Error(L('remember.error.importance'))\n      const level: Level = typeof parsed.level === 'string' && (LEVELS as readonly string[]).includes(parsed.level)\n        ? (parsed.level as Level)\n        : 'fact'\n      const importance = Math.round(importanceRaw)\n      const subcategory =\n        level === 'project' && typeof parsed.subcategory === 'string' && (PROJECT_SUBCATEGORIES as readonly string[]).includes(parsed.subcategory)\n          ? (parsed.subcategory as ProjectSubcategory)\n          : null\n      const goal = typeof parsed.goal === 'string' && parsed.goal.trim() ? parsed.goal.trim() : null\n      const corrected = coerceBoolean(parsed.corrected) ? 1 : 0\n\n      const workspace = workspaceOf(exec)\n      if (!workspace) throw new Error('memory_remember: 无法确定工作区（会话无 cwd）')\n      const db = getDb(workspace, dir)\n      const source_session = sessionIdOf(exec)\n      // 锚定当前 project：带 project 参数的 memory 调用更新会话状态（命中检索用它）；\"全局\"与多项目（逗号分隔）不锚定。\n      if (project && !isGlobalProject(project) && !project.includes(',')) setCurrentProject(workspace, source_session ?? 'unknown', project, dir)\n\n      // 去重：同 level 找相似条目 → 合并更新\n      const existing = db.list(level)\n      let merged: MemoryRow | undefined\n      for (const r of existing) {\n        if (similarity(r.content, content) >= DEDUP_THRESHOLD) {\n          merged = r\n          break\n        }\n      }\n      if (merged) {\n        const patch: MemoryPatch = {\n          content,\n          importance: Math.max(merged.importance, importance),\n        }\n        if (project && (level === 'project' || level === 'fact' || level === 'lesson' || level === 'topic' || level === 'rules')) patch.project = project\n        if (subcategory && level === 'project') patch.subcategory = subcategory\n        if (goal && level === 'topic') patch.goal = goal\n        if (level === 'lesson' && corrected) patch.corrected = 1\n        patch.keywords = keywords // 显式关键词才覆盖合并目标（能走到这里说明关键词非空）\n        db.update(level, merged.id, patch)\n        // 写痕迹（v0.23.0）：合并落库也记入 written——压缩重注入第三块回放本会话写过的记忆。\n        markWritten(workspace, source_session ?? 'unknown', [merged.id], dir)\n        // 读回合并后的实际存储结果（关键词等），让模型知道最终落库形态。\n        const after = db.findById(merged.id)?.row\n        return {\n          ok: true,\n          id: merged.id,\n          level,\n          merged: true,\n          keywords: after?.keywords ?? merged.keywords,\n          ...(after?.project ? { project: after.project } : {}),\n        }\n      }\n\n      const row = db.insert({\n        level,\n        content,\n        project,\n        subcategory,\n        goal,\n        importance,\n        corrected,\n        keywords,\n        source_session,\n      })\n      // 写痕迹（v0.23.0）：新建落库记入 written——压缩重注入第三块回放本会话写过的记忆。\n      markWritten(workspace, source_session ?? 'unknown', [row.id], dir)\n      return {\n        ok: true,\n        id: row.id,\n        level,\n        merged: false,\n        keywords: row.keywords,\n        ...(row.project ? { project: row.project } : {}),\n      }\n    },\n    presentCall(args: unknown): { card: 'generic'; title: string; kind: 'write' } {\n      const parsed = args as { content?: unknown }\n      const preview = typeof parsed.content === 'string' ? parsed.content.slice(0, 40) : ''\n      return { card: 'generic', title: `memory_remember: ${preview}`, kind: 'write' }\n    },\n  }\n}\n\nfunction searchTool(dir: string): ToolDefinition {\n  return {\n    name: 'memory_search',\n    description: T('memory_search.description'),\n    parameters: {\n      type: 'object',\n      additionalProperties: false,\n      required: ['query'],\n      properties: {\n        query: { type: 'string', description: T('memory_search.param.query') },\n        level: { type: 'string', description: T('memory_search.param.level') },\n        project: { type: 'string', description: T('memory_search.param.project') },\n        status: { type: 'string', description: T('memory_search.param.status') },\n        days: { type: 'integer', minimum: 1, maximum: 3650, description: T('memory_search.param.days') },\n        k: { type: 'integer', minimum: 1, maximum: 50, default: 10, description: T('memory_search.param.k') },\n        content_max: { type: 'integer', minimum: 0, maximum: 5000, default: 300, description: T('memory_search.param.content_max') },\n        explain: { type: 'boolean', default: false, description: T('memory_search.param.explain') },\n      },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        required: ['note', 'hits'],\n        properties: {\n          note: { type: 'string', description: T('memory_search.out.note') },\n          hits: {\n            type: 'array',\n            items: {\n              type: 'object',\n              additionalProperties: false,\n              required: ['id', 'level'],\n              properties: {\n                id: { type: 'string', description: T('memory_search.out.hits.id') },\n                level: { type: 'string' },\n                title: { type: 'string' },\n                content: { type: 'string' },\n                keywords: { type: 'array', items: { type: 'string' }, description: T('memory_search.out.hits.keywords') },\n                project: { type: 'string', description: T('memory_search.out.hits.project') },\n                score: { type: 'number' },\n                updated_at: { type: 'number', description: T('memory_search.out.hits.updated_at') },\n                explain: {\n                  type: 'object',\n                  additionalProperties: false,\n                  required: ['bm25', 'importance', 'recencyWeight', 'status'],\n                  properties: {\n                    bm25: { type: 'number', description: T('memory_search.out.hits.explain') },\n                    importance: { type: 'number' },\n                    recencyWeight: { type: 'number' },\n                    status: { type: 'string' },\n                  },\n                },\n              },\n            },\n          },\n        },\n      },\n      render: (_args, value) => {\n        const v = value as { note?: string; hits?: Array<{ id?: string; level?: string; content?: string; keywords?: unknown; project?: string | null; updated_at?: number | null; score?: number; explain?: { bm25?: number; importance?: number; recencyWeight?: number; status?: string } }> }\n        const lines = [String(v.note ?? '')]\n        for (const h of v.hits ?? []) {\n          // 检索元数据视图：归属 + id + 相对时间 + 关键词（无关键词回退原文开头）；原文内容不显示。\n          const kw = (Array.isArray(h.keywords) ? h.keywords : []).filter((x): x is string => typeof x === 'string' && x.length > 0)\n          const about = kw.length > 0 ? kw.join(', ') : `${String(h.content ?? '').slice(0, 40)}…`\n          // 归属显示：'全局'=真全局；null=未标记（可能是数据 bug）；多值 join '/'（如 dsh/femo）。\n          const proj = `${projectLabel(h.project)} : ${String(h.level ?? '')}`\n          const rel = relativeTime(h.updated_at ?? null)\n          lines.push(`[${proj}] [${String(h.id ?? '')}] [${rel}] 关于：${about}`)\n          // explain=true（#51/#79）：分项得分追加一行。宿主把 render 产物作为工具结果\n          // content 喂给模型（dsh-tools createSuccessResult）——只进结构化字段不渲染\n          // 等于对模型不可见（#79 的报告即因此误判功能缺失）。\n          const ex = h.explain\n          if (ex !== undefined) {\n            lines.push(`  bm25=${String(ex.bm25 ?? 0)} importance=${String(ex.importance ?? 0)} recencyWeight=${String(ex.recencyWeight ?? 1)} status=${String(ex.status ?? 'active')} score=${String(h.score ?? 0)}`)\n          }\n        }\n        return lines.map((t) => ({ type: 'text' as const, text: t }))\n      },\n    },\n    async execute(args: unknown, exec: ToolRunContext) {\n      refuseOrThrow('read', exec)\n      const parsed = args as { query?: unknown; level?: unknown; project?: unknown; status?: unknown; days?: unknown; k?: unknown; content_max?: unknown; explain?: unknown }\n      const explain = parsed.explain === true\n      const query = typeof parsed.query === 'string' ? parsed.query.trim() : ''\n      if (!query) throw new Error('memory_search: query 必填且不能为空（例：{\"query\": \"关键词\"}）；浏览项目全貌请用 memory_project')\n      const workspace = workspaceOf(exec)\n      if (!workspace) throw new Error('memory_search: 无法确定工作区（会话无 cwd）')\n      const db = getDb(workspace, dir)\n      const sessionId = sessionIdOf(exec)\n      const seen = readSeen(workspace, sessionId ?? 'unknown', dir)\n      // project/status 支持逗号多选（OR 语义，用户拍板 2026-08-19）。\n      const projectList = typeof parsed.project === 'string' && parsed.project.trim()\n        ? parsed.project.split(',').map((s) => s.trim()).filter((s) => s.length > 0)\n        : []\n      const project = projectList.length > 0 ? projectList : null\n      // 锚定当前 project（命中检索限定\"全局+当前项目\"）；单值才锚定，\"全局\"不锚定。\n      if (projectList.length === 1 && !isGlobalProject(projectList[0])) setCurrentProject(workspace, sessionId ?? 'unknown', projectList[0], dir)\n      const statusList = typeof parsed.status === 'string' && parsed.status.trim()\n        ? parsed.status.split(',').map((s) => s.trim()).filter((s) => s.length > 0)\n        : []\n      const status = statusList.length > 0 ? statusList : null\n      const daysRaw = coerceNumber(parsed.days)\n      const days = daysRaw !== undefined && daysRaw > 0 ? daysRaw : null\n      const kRaw = coerceNumber(parsed.k)\n      const k = kRaw !== undefined ? Math.max(1, Math.min(50, Math.round(kRaw))) : 10\n      const cmRaw = coerceNumber(parsed.content_max)\n      const contentMax = cmRaw !== undefined ? Math.max(0, Math.min(5000, Math.round(cmRaw))) : 300\n\n      const levels: Level[] = typeof parsed.level === 'string' && parsed.level.trim()\n        ? parsed.level.split(',').map((s) => s.trim()).filter((s): s is Level => (LEVELS as readonly string[]).includes(s))\n        : (['fact', 'lesson', 'topic', 'rules'] as Level[])\n      const rows = levels.flatMap((lv) => {\n        // 'all' = 不过滤 → 全量直出（#68：listSearchable 只出 active+todo-stale，\n        // archived 在 db 层就被滤掉，\"all\" 名不符实）。单一非默认 status → db 层过滤；\n        // 多选 → 全量取出后 filterSearchable 过滤；默认 active（+todo stale）。\n        if (statusList.includes('all')) return db.list(lv)\n        if (statusList.length === 1 && statusList[0] !== 'active') return db.list(lv, { status: statusList[0] as MemoryRow['status'] })\n        if (statusList.length > 1) return db.list(lv)\n        return db.listSearchable(lv)\n      })\n      // 查询参数过滤（project/status/days）；不再预排除已见/本 session 建立的记忆。\n      const filtered = filterSearchable(rows, { project, status, days })\n      const byId = new Map(filtered.map((r) => [r.id, r]))\n      const docs = filtered.map((r) => ({\n        id: r.id,\n        level: r.level,\n        title: r.title,\n        content: r.content,\n        keywords: r.keywords,\n        importance: r.importance,\n        created_at: r.created_at,\n        updated_at: r.updated_at,\n      }))\n      // 全量排名（分高到低）后分段选取（用户拍板 2026-08-19）：\n      //   前 5 条无脑取（不排除任何记忆，含已见/本 session 建立的）；\n      //   第 6 名起逐个往下，绕开已见（injected+searched）的记忆补足，保证新信息。\n      const ranked = search(query, docs, { k: docs.length, explain })\n      const blindCount = Math.min(5, k)\n      const blind = ranked.slice(0, blindCount)\n      const fresh: RankedHit[] = []\n      for (const h of ranked.slice(blindCount)) {\n        if (fresh.length >= k - blindCount) break\n        if (seen.has(h.id)) continue\n        fresh.push(h)\n      }\n      const hits = [...blind, ...fresh]\n      for (const h of hits) db.bumpHit(h.level as Level, h.id)\n      markSearched(workspace, sessionId ?? 'unknown', hits.map((h) => h.id), dir)\n      // 按记忆时间戳（updated_at）重排：旧→新；null 视为最旧（从未封存/更新）。\n      const reordered = [...hits].sort((a, b) => (a.updated_at ?? 0) - (b.updated_at ?? 0))\n      const BASE_NOTE = '如果冲突，以最新的为准。时间戳较旧的条目可作为事情发展过程的参考。如果你确实需要更多细节，可以直接去聊天记录里搜索相关关键词。'\n      // 零命中 + 未显式传 level（#79 顺带）：默认范围不含 soul/user（它们每会话首轮\n      // 全量注入、不参与关键词检索）——现场极易误判成\"库是空的\"，补一句排查指引。\n      const explicitLevels = typeof parsed.level === 'string' && parsed.level.trim().length > 0\n      const note = hits.length === 0 && !explicitLevels\n        ? `${BASE_NOTE}本次零命中：默认检索范围是 fact/lesson/topic/rules，soul 与 user 层不参与关键词检索（要查它们请显式传 level，如 {\"level\":\"soul,user\"}）；若记忆库刚启用，也可能确实还没有可检索的记忆。`\n        : BASE_NOTE\n      return {\n        note,\n        hits: reordered.map((h) => {\n          const row = byId.get(h.id)\n          return {\n            id: h.id,\n            level: h.level,\n            title: h.title ?? '',\n            content: contentMax > 0 ? h.content.slice(0, contentMax) : h.content,\n            keywords: row?.keywords ?? [],\n            project: row?.project ?? '',\n            score: Math.round(h.score * 100) / 100,\n            updated_at: h.updated_at ?? 0,\n            // 可解释检索（#51）：explain=true 时附分项得分。状态过滤是检索前的二值\n            // 过滤、不进打分——这里补 status 字段让分解完整。\n            ...(explain\n              ? {\n                  explain: {\n                    bm25: h.explain?.bm25 ?? 0,\n                    importance: row?.importance ?? 0,\n                    recencyWeight: h.explain?.recencyWeight ?? 1,\n                    status: row?.status ?? 'active',\n                  },\n                }\n              : {}),\n          }\n        }),\n      }\n    },\n    presentCall(args: unknown): { card: 'generic'; title: string; kind: 'read' } {\n      const parsed = args as { query?: unknown }\n      return { card: 'generic', title: `memory_search: ${String(parsed.query ?? '').slice(0, 40)}`, kind: 'read' }\n    },\n  }\n}\n\nfunction findSimilarTool(dir: string): ToolDefinition {\n  return {\n    name: 'memory_find_similar',\n    description: T('memory_find_similar.description'),\n    parameters: {\n      type: 'object',\n      additionalProperties: false,\n      required: ['id'],\n      properties: {\n        id: { type: 'string', description: T('memory_find_similar.param.id') },\n        k: { type: 'integer', minimum: 1, maximum: 20, default: 5, description: T('memory_find_similar.param.k') },\n        content_max: { type: 'integer', minimum: 0, maximum: 5000, default: 200, description: T('memory_find_similar.param.content_max') },\n      },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        required: ['hits'],\n        properties: {\n          hits: {\n            type: 'array',\n            items: {\n              type: 'object',\n              additionalProperties: false,\n              required: ['id', 'level', 'similarity'],\n              properties: {\n                id: { type: 'string' },\n                level: { type: 'string' },\n                title: { type: 'string' },\n                content: { type: 'string' },\n                similarity: { type: 'number', description: T('memory_find_similar.out.hits.similarity') },\n              },\n            },\n          },\n        },\n      },\n      render: (_args, value) => {\n        const v = value as { hits?: Array<{ id?: string; level?: string; title?: string; content?: string; similarity?: number }> }\n        return (v.hits ?? []).map((h) => ({\n          type: 'text' as const,\n          text: `[${String(h.level ?? '')} ${String(h.id ?? '').slice(0, 12)}] 相似度 ${Number(h.similarity ?? 0).toFixed(3)} ${String(h.title ?? '')} ${String(h.content ?? '').slice(0, 80)}`,\n        }))\n      },\n    },\n    async execute(args: unknown, exec: ToolRunContext) {\n      refuseOrThrow('read', exec)\n      const parsed = args as { id?: unknown; k?: unknown; content_max?: unknown }\n      const id = typeof parsed.id === 'string' ? parsed.id.trim() : ''\n      if (!id) throw new Error('memory_find_similar: id 不能为空')\n      const workspace = workspaceOf(exec)\n      if (!workspace) throw new Error('memory_find_similar: 无法确定工作区（会话无 cwd）')\n      const db = getDb(workspace, dir)\n      const found = db.findById(id)\n      if (!found) throw new Error(`memory_find_similar: 未找到记忆 ${id.slice(0, 12)}`)\n      const sessionId = sessionIdOf(exec)\n      const seen = readSeen(workspace, sessionId ?? 'unknown', dir)\n      const kRaw = coerceNumber(parsed.k)\n      const k = kRaw !== undefined ? Math.max(1, Math.min(20, Math.round(kRaw))) : 5\n      const cmRaw = coerceNumber(parsed.content_max)\n      const contentMax = cmRaw !== undefined ? Math.max(0, Math.min(5000, Math.round(cmRaw))) : 200\n\n      const rows = LEVELS.flatMap((lv) => (lv === 'soul' || lv === 'user' ? [] : db.listSearchable(lv)))\n      const candidates = rows.filter((r) => r.id !== found.row.id && !seen.has(r.id) && r.source_session !== sessionId)\n      const docs = candidates.map((r) => ({\n        id: r.id,\n        level: r.level,\n        title: r.title,\n        content: r.content,\n        keywords: r.keywords,\n        importance: r.importance,\n        created_at: r.created_at,\n        updated_at: r.updated_at,\n      }))\n      const hits = findSimilar(found.row.content, docs, k)\n      markSearched(workspace, sessionId ?? 'unknown', hits.map((h) => h.id), dir)\n      return {\n        hits: hits.map((h) => ({\n          id: h.id,\n          level: h.level,\n          title: h.title ?? '',\n          content: contentMax > 0 ? h.content.slice(0, contentMax) : h.content,\n          similarity: h.similarity,\n        })),\n      }\n    },\n    presentCall(args: unknown): { card: 'generic'; title: string; kind: 'read' } {\n      const parsed = args as { id?: unknown }\n      return { card: 'generic', title: `memory_find_similar: ${String(parsed.id ?? '').slice(0, 12)}`, kind: 'read' }\n    },\n  }\n}\n\nfunction readTool(dir: string): ToolDefinition {\n  return {\n    name: 'memory_read',\n    description: T('memory_read.description'),\n    parameters: {\n      type: 'object',\n      additionalProperties: false,\n      required: ['id'],\n      properties: {\n        id: { type: 'string', description: T('memory_read.param.id') },\n      },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        required: ['found'],\n        properties: {\n          found: { type: 'boolean' },\n          id: { type: 'string' },\n          level: { type: 'string' },\n          title: { type: 'string' },\n          content: { type: 'string' },\n          importance: { type: 'number' },\n          status: { type: 'string' },\n          keywords: { type: 'array', items: { type: 'string' } },\n          project: { type: 'string' },\n          goal: { type: 'string' },\n          corrected: { type: 'boolean' },\n          created_at: { type: 'number' },\n          updated_at: { type: 'number' },\n        },\n      },\n      render: (_args, value) => {\n        const v = value as { found?: boolean; level?: unknown; title?: unknown; content?: unknown; status?: unknown; project?: unknown; goal?: unknown }\n        const hint = '如果你确实需要更多细节，可以直接去聊天记录里搜索相关关键词。'\n        if (!v.found) return [{ type: 'text' as const, text: `未找到该记忆。${hint}` }]\n        const parts = [`[${String(v.level ?? '')}] ${String(v.title ?? '')}（${String(v.status ?? '')}）`]\n        if (v.project) parts.push(`项目：${String(v.project)}`)\n        if (v.goal) parts.push(`目标：${String(v.goal)}`)\n        parts.push(String(v.content ?? ''))\n        parts.push(hint)\n        return [{ type: 'text' as const, text: parts.join('\\n') }]\n      },\n    },\n    async execute(args: unknown, exec: ToolRunContext) {\n      refuseOrThrow('read', exec)\n      const parsed = args as { id?: unknown }\n      const id = typeof parsed.id === 'string' ? parsed.id.trim() : ''\n      if (!id) throw new Error('memory_read: id 不能为空')\n      const workspace = workspaceOf(exec)\n      if (!workspace) throw new Error('memory_read: 无法确定工作区（会话无 cwd）')\n      const found = getDb(workspace, dir).findById(id)\n      if (!found) return { found: false }\n      const { row } = found\n      // 查阅留痕（v0.17.0）：dream 第一轮清单的\"查阅过\"源（memory_project 全景不标记，第三轮专门复查）。\n      markAccessed(workspace, sessionIdOf(exec) ?? 'unknown', [row.id], dir)\n      return {\n        found: true,\n        id: row.id,\n        level: row.level,\n        title: row.title ?? '',\n        content: row.content,\n        importance: row.importance,\n        status: row.status,\n        keywords: row.keywords,\n        project: row.project ?? '',\n        goal: row.goal ?? '',\n        corrected: row.corrected === 1,\n        created_at: row.created_at,\n        updated_at: row.updated_at,\n      }\n    },\n    presentCall(args: unknown): { card: 'generic'; title: string; kind: 'read' } {\n      const parsed = args as { id?: unknown }\n      return { card: 'generic', title: `memory_read: ${String(parsed.id ?? '').slice(0, 16)}`, kind: 'read' }\n    },\n  }\n}\n\nfunction updateTool(dir: string): ToolDefinition {\n  return {\n    name: 'memory_update',\n    description: T('memory_update.description'),\n    parameters: {\n      type: 'object',\n      additionalProperties: false,\n      required: ['id'],\n      properties: {\n        id: { type: 'string', description: T('memory_update.param.id') },\n        content: { type: 'string', description: T('memory_update.param.content') },\n        status: { type: 'string', enum: ['active', 'archived', 'stale'], description: T('memory_update.param.status') },\n        importance: { type: 'integer', description: T('memory_update.param.importance') },\n        goal: { type: 'string', description: T('memory_update.param.goal') },\n        project: { type: 'string', description: T('memory_update.param.project') },\n        keywords: { type: 'array', items: { type: 'string' }, description: T('memory_update.param.keywords') },\n      },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        required: ['ok'],\n        properties: {\n          ok: { type: 'boolean' },\n          id: { type: 'string' },\n          level: { type: 'string' },\n        },\n      },\n      render: (_args, value) => {\n        const v = value as { ok?: boolean; level?: unknown; id?: unknown }\n        return [{ type: 'text' as const, text: v.ok ? `✅ 已更新（${String(v.level ?? '')} ${String(v.id ?? '').slice(0, 8)}）。` : '更新失败：未找到该记忆。' }]\n      },\n    },\n    async execute(args: unknown, exec: ToolRunContext) {\n      refuseOrThrow('write', exec)\n      const parsed = args as { id?: unknown; content?: unknown; status?: unknown; importance?: unknown; goal?: unknown; project?: unknown; keywords?: unknown }\n      const id = typeof parsed.id === 'string' ? parsed.id.trim() : ''\n      if (!id) throw new Error('memory_update: id 不能为空')\n      const workspace = workspaceOf(exec)\n      if (!workspace) throw new Error('memory_update: 无法确定工作区（会话无 cwd）')\n      const db = getDb(workspace, dir)\n      const sessionId = sessionIdOf(exec)\n      // 写路径必须歧义拒绝（#62）：findById 取首条 + 拿解析出的全 id 去 update，\n      // 会绕过 db.update 内部的 LIKE 歧义守卫、静默改错条目。多命中 → 报错列候选。\n      const matches = db.findByIdAll(id)\n      if (matches.length > 1) {\n        const list = matches\n          .map((m) => `${m.level}:${m.row.id.slice(0, 8)} ${m.row.title || m.row.content.slice(0, 40)}`)\n          .join('；')\n        throw new Error(`memory_update: 短 id \"${id}\" 命中 ${matches.length} 条（${list}），请改用完整 id`)\n      }\n      const found = matches[0]\n      if (!found) return { ok: false, id, level: '' }\n      const patch: MemoryPatch = {}\n      if (typeof parsed.content === 'string' && parsed.content.trim()) patch.content = parsed.content.trim()\n      if (typeof parsed.status === 'string' && ['active', 'archived', 'stale'].includes(parsed.status)) patch.status = parsed.status as MemoryPatch['status']\n      const importanceRaw = coerceNumber(parsed.importance)\n      if (importanceRaw !== undefined) patch.importance = Math.round(importanceRaw)\n      if (typeof parsed.goal === 'string' && parsed.goal.trim() && found.level === 'topic') patch.goal = parsed.goal.trim()\n      if (typeof parsed.project === 'string' && (found.level === 'project' || found.level === 'fact' || found.level === 'lesson' || found.level === 'rules' || found.level === 'topic')) {\n        const cleared = parsed.project.trim() === ''\n        patch.project = cleared ? null : parsed.project.trim()\n        // 锚定当前 project（命中检索限定\"全局+当前项目\"）；\"全局\"、清空归属、多项目（逗号分隔）不锚定。\n        if (!cleared && !isGlobalProject(String(patch.project)) && !String(patch.project).includes(',')) setCurrentProject(workspace, sessionId ?? 'unknown', patch.project, dir)\n      }\n      {\n        // 空数组 / 未提供 = 不更新（用户拍板：防 AI 幻觉\"不想改关键词\"却传 [] 把关键词全清空）；\n        // 字符串形态经通道兜底归一后同样接受（issue #24）。\n        const kw = normalizeKeywords(parsed.keywords)\n        if (kw.length > 0) patch.keywords = kw\n      }\n      // 记忆时间戳 = 最后更新时间：db.update 内部自动刷新 updated_at（任何 update 都刷新）。\n      // patch 为空（如只想传 keywords:[] 表达\"不更新\"）→ 视为调用成功、无字段变化。\n      const ok = Object.keys(patch).length > 0 ? db.update(found.level, found.row.id, patch) : true\n      // 写痕迹（v0.23.0）：实际落库（patch 非空且 update 成功）才记——空 patch 无字段变化不算写。\n      if (ok && Object.keys(patch).length > 0) markWritten(workspace, sessionId ?? 'unknown', [found.row.id], dir)\n      return { ok, id: found.row.id, level: found.level }\n    },\n    presentCall(args: unknown): { card: 'generic'; title: string; kind: 'write' } {\n      const parsed = args as { id?: unknown; status?: unknown }\n      return { card: 'generic', title: `memory_update: ${String(parsed.id ?? '').slice(0, 8)}${parsed.status ? ` → ${String(parsed.status)}` : ''}`, kind: 'write' }\n    },\n  }\n}\n\n/**\n * memory_project：取回某项目的完整注入段落（用户拍板规格）。\n * - 非 todo 子标签：active 条目全部；\n * - todo 子标签：active 全部为「To do list：」+ stale（已完成）按 updated_at 取最近 5 条为「已完成：」；\n * - 组内按记忆时间戳旧→新；只拼 content 纯文本，不写复杂格式。\n * 段落构造与压缩重注入共用 buildProjectSectionText（v0.21.0，inject.ts）。\n */\nfunction projectTool(dir: string): ToolDefinition {\n  return {\n    name: 'memory_project',\n    description: T('memory_project.description'),\n    parameters: {\n      type: 'object',\n      additionalProperties: false,\n      required: ['project'],\n      properties: {\n        project: { type: 'string', description: T('memory_project.param.project') },\n      },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        required: ['project', 'text'],\n        properties: {\n          project: { type: 'string' },\n          text: { type: 'string', description: T('memory_project.out.text') },\n        },\n      },\n      render: (_args, value) => {\n        const v = value as { text?: unknown }\n        return [{ type: 'text' as const, text: String(v.text ?? '') }]\n      },\n    },\n    async execute(args: unknown, exec: ToolRunContext) {\n      refuseOrThrow('read', exec)\n      const parsed = args as { project?: unknown }\n      const project = typeof parsed.project === 'string' ? parsed.project.trim() : ''\n      if (!project) throw new Error('memory_project: project 不能为空')\n      const workspace = workspaceOf(exec)\n      if (!workspace) throw new Error('memory_project: 无法确定工作区（会话无 cwd）')\n      const db = getDb(workspace, dir)\n      // 锚定当前 project：用户话题切到某项目时 AI 调 memory_project → 命中检索立即跟进；\"全局\"与多项目不锚定。\n      const sessionId = sessionIdOf(exec)\n      if (!isGlobalProject(project) && !project.includes(',')) setCurrentProject(workspace, sessionId ?? 'unknown', project, dir)\n      // 查阅留痕（v0.21.0）：本会话查阅过的项目记入 sessions/<id>.json——会话压缩成功后\n      // 按此清单重注入项目全景。全局标记不记（markProjectQueried 内部过滤，全局层走快照）；\n      // 多项目参数按逗号拆开逐个记（重注入按单项目段落拼装）。\n      markProjectQueried(workspace, sessionId ?? 'unknown', project, dir)\n      const text = buildProjectSectionText(db, workspace, project, dir)\n      if (text === null) {\n        return { project, text: L('project.empty', { name: project }) }\n      }\n      return { project, text }\n    },\n    presentCall(args: unknown): { card: 'generic'; title: string; kind: 'read' } {\n      const parsed = args as { project?: unknown }\n      return { card: 'generic', title: `memory_project: ${String(parsed.project ?? '').slice(0, 24)}`, kind: 'read' }\n    },\n  }\n}\n\n/** 全局数据目录查看/切换（用户拍板 2026-09-25）：对用户=说一句话即可换目录，\n *  零代码零重启——不依赖 dsh 0.1.7 设置页写入链（其真机写入被拒、拒因静默）。\n *  切换=插件内部 switchHomeDir（同盘移动/跨盘复制+旧目录绝不自动删+失败留原地）。 */\nfunction homeTool(): ToolDefinition {\n  return {\n    name: 'memory_home',\n    description: T('memory_home.description'),\n    parameters: {\n      type: 'object',\n      additionalProperties: false,\n      properties: {\n        target: { type: 'string', description: T('memory_home.param.target') },\n      },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        required: ['note'],\n        properties: { note: { type: 'string', description: T('memory_home.out.note') } },\n      },\n      render: (_args, value) => {\n        const v = value as { note?: string }\n        return [{ type: 'text' as const, text: String(v.note ?? '') }]\n      },\n    },\n    async execute(args: unknown) {\n      const parsed = args as { target?: unknown }\n      const presets = homeDirPresets()\n      const raw = typeof parsed.target === 'string' ? parsed.target.trim() : ''\n      if (raw === '') {\n        return { note: [\n          `当前全局数据目录：${activeHomeDir()}`,\n          `预设 default（系统用户主目录）：${presets.default}`,\n          `预设 dsh-storage（DSH 根目录 Storage）：${presets['dsh-storage']}`,\n          `预设 plugin-root（插件本体根目录）：${presets['plugin-root']}`,\n          `不修改则不传 target；要切换请传预设标记或绝对路径。`,\n        ].join('\\n') }\n      }\n      const LEGAL = ['default', 'dsh-storage', 'plugin-root']\n      const target = resolveHomeDir(raw)\n      // 非法输入防误切：resolveHomeDir 会把非法值回落默认——这里识别出来直接报错\n      const downgraded = target === resolveHomeDir(undefined) && !LEGAL.includes(raw)\n      if (downgraded) {\n        return { note: `无法识别的 target：\"${raw}\"（可用预设标记或绝对路径）。当前目录未变：${activeHomeDir()}` }\n      }\n      const sw = switchHomeDir(target)\n      if (sw.mode === 'same') return { note: `全局数据目录本就是 ${sw.to}，未变更。` }\n      if (sw.mode === 'failed') return { note: `切换失败：${sw.error}。仍使用 ${sw.from}，数据未受影响，可稍后重试。` }\n      if (sw.mode === 'reused-nonempty') return { note: `已切换为 ${sw.to}（目标目录已有内容，直接启用、未覆盖）。旧目录 ${sw.from} 原样保留。` }\n      if (sw.mode === 'rename') return { note: `已切换为 ${sw.to}：自 ${sw.from} 移动 ${sw.files} 项完成（同盘移动）。如本机有多个 dsh 实例共享旧目录，请同步修改它们的设置。` }\n      return { note: `已切换为 ${sw.to}：自 ${sw.from} 复制 ${sw.files} 项（跨盘复制为快照）。旧目录 ${sw.from} 保留未删，确认无误后可手动删除；若多个 dsh 实例共享旧目录，请同步修改其他实例的设置。` }\n    },\n  }\n}\n\nexport function registerMemoryTools(register: (t: ToolDefinition) => void, dir = '.dsh-meow'): void {\n  // 门控判定器经 setMemoryToolGate 注入（apply 期设置；工具工厂签名保持不变）。\n  register(rememberTool(dir))\n  register(searchTool(dir))\n  register(findSimilarTool(dir))\n  register(readTool(dir))\n  register(updateTool(dir))\n  register(projectTool(dir))\n  register(homeTool())\n}"
